import operator
from . import libmp
from .libmp.backend import basestring
from .libmp import int_types, MPZ_ONE, prec_to_dps, dps_to_prec, repr_dps, round_floor, round_ceiling, fzero, finf, fninf, fnan, mpf_le, mpf_neg, from_int, from_float, from_str, from_rational, mpi_mid, mpi_delta, mpi_str, mpi_abs, mpi_pos, mpi_neg, mpi_add, mpi_sub, mpi_mul, mpi_div, mpi_pow_int, mpi_pow, mpi_from_str, mpci_pos, mpci_neg, mpci_add, mpci_sub, mpci_mul, mpci_div, mpci_pow, mpci_abs, mpci_pow, mpci_exp, mpci_log, ComplexResult, mpf_hash, mpc_hash
from .matrices.matrices import _matrix
mpi_zero = (fzero, fzero)
from .ctx_base import StandardBaseContext
new = object.__new__

def convert_mpf_(x, prec, rounding):
    if hasattr(x, '_mpf_'):
        return x._mpf_
    if isinstance(x, int_types):
        return from_int(x, prec, rounding)
    if isinstance(x, float):
        return from_float(x, prec, rounding)
    if isinstance(x, basestring):
        return from_str(x, prec, rounding)
    raise NotImplementedError

class ivmpf(object):

    def __new__(cls, x=0):
        return cls.ctx.convert(x)

    def cast(self, cls, f_convert):
        a, b = self._mpi_
        if a == b:
            return cls(f_convert(a))
        raise ValueError

    def __int__(self):
        return self.cast(int, libmp.to_int)

    def __float__(self):
        return self.cast(float, libmp.to_float)

    def __complex__(self):
        return self.cast(complex, libmp.to_float)

    def __hash__(self):
        a, b = self._mpi_
        if a == b:
            return mpf_hash(a)
        else:
            return hash(self._mpi_)

    @property
    def real(self):
        return self

    @property
    def imag(self):
        return self.ctx.zero

    def conjugate(self):
        return self

    @property
    def a(self):
        a, b = self._mpi_
        return self.ctx.make_mpf((a, a))

    @property
    def b(self):
        a, b = self._mpi_
        return self.ctx.make_mpf((b, b))

    @property
    def mid(self):
        ctx = self.ctx
        v = mpi_mid(self._mpi_, ctx.prec)
        return ctx.make_mpf((v, v))

    @property
    def delta(self):
        ctx = self.ctx
        v = mpi_delta(self._mpi_, ctx.prec)
        return ctx.make_mpf((v, v))

    @property
    def _mpci_(self):
        return (self._mpi_, mpi_zero)

    def _compare(*args):
        raise TypeError('no ordering relation is defined for intervals')
    __gt__ = _compare
    __le__ = _compare
    __gt__ = _compare
    __ge__ = _compare

    def __contains__(self, t):
        t = self.ctx.mpf(t)
        return self.a <= t.a and t.b <= self.b

    def __str__(self):
        return mpi_str(self._mpi_, self.ctx.prec)

    def __repr__(self):
        if self.ctx.pretty:
            return str(self)
        a, b = self._mpi_
        n = repr_dps(self.ctx.prec)
        a = libmp.to_str(a, n)
        b = libmp.to_str(b, n)
        return 'mpi(%r, %r)' % (a, b)

    def _compare(s, t, cmpfun):
        if not hasattr(t, '_mpi_'):
            try:
                t = s.ctx.convert(t)
            except:
                return NotImplemented
        return cmpfun(s._mpi_, t._mpi_)

    def __eq__(s, t):
        return s._compare(t, libmp.mpi_eq)

    def __ne__(s, t):
        return s._compare(t, libmp.mpi_ne)

    def __lt__(s, t):
        return s._compare(t, libmp.mpi_lt)

    def __le__(s, t):
        return s._compare(t, libmp.mpi_le)

    def __gt__(s, t):
        return s._compare(t, libmp.mpi_gt)

    def __ge__(s, t):
        return s._compare(t, libmp.mpi_ge)

    def __abs__(self):
        return self.ctx.make_mpf(mpi_abs(self._mpi_, self.ctx.prec))

    def __pos__(self):
        return self.ctx.make_mpf(mpi_pos(self._mpi_, self.ctx.prec))

    def __neg__(self):
        return self.ctx.make_mpf(mpi_neg(self._mpi_, self.ctx.prec))

    def ae(s, t, rel_eps=None, abs_eps=None):
        return s.ctx.almosteq(s, t, rel_eps, abs_eps)

class ivmpc(object):

    def __new__(cls, re=0, im=0):
        re = cls.ctx.convert(re)
        im = cls.ctx.convert(im)
        y = new(cls)
        y._mpci_ = (re._mpi_, im._mpi_)
        return y

    def __hash__(self):
        (a, b), (c, d) = self._mpci_
        if a == b and c == d:
            return mpc_hash((a, c))
        else:
            return hash(self._mpci_)

    def __repr__(s):
        if s.ctx.pretty:
            return str(s)
        return 'iv.mpc(%s, %s)' % (repr(s.real), repr(s.imag))

    def __str__(s):
        return '(%s + %s*j)' % (str(s.real), str(s.imag))

    @property
    def a(self):
        (a, b), (c, d) = self._mpci_
        return self.ctx.make_mpf((a, a))

    @property
    def b(self):
        (a, b), (c, d) = self._mpci_
        return self.ctx.make_mpf((b, b))

    @property
    def c(self):
        (a, b), (c, d) = self._mpci_
        return self.ctx.make_mpf((c, c))

    @property
    def d(self):
        (a, b), (c, d) = self._mpci_
        return self.ctx.make_mpf((d, d))

    @property
    def real(s):
        return s.ctx.make_mpf(s._mpci_[0])

    @property
    def imag(s):
        return s.ctx.make_mpf(s._mpci_[1])

    def conjugate(s):
        a, b = s._mpci_
        return s.ctx.make_mpc((a, mpf_neg(b)))

    def overlap(s, t):
        t = s.ctx.convert(t)
        real_overlap = s.a <= t.a <= s.b or s.a <= t.b <= s.b or t.a <= s.a <= t.b or (t.a <= s.b <= t.b)
        imag_overlap = s.c <= t.c <= s.d or s.c <= t.d <= s.d or t.c <= s.c <= t.d or (t.c <= s.d <= t.d)
        return real_overlap and imag_overlap

    def __contains__(s, t):
        t = s.ctx.convert(t)
        return t.real in s.real and t.imag in s.imag

    def _compare(s, t, ne=False):
        if not isinstance(t, s.ctx._types):
            try:
                t = s.ctx.convert(t)
            except:
                return NotImplemented
        if hasattr(t, '_mpi_'):
            tval = (t._mpi_, mpi_zero)
        elif hasattr(t, '_mpci_'):
            tval = t._mpci_
        if ne:
            return s._mpci_ != tval
        return s._mpci_ == tval

    def __eq__(s, t):
        return s._compare(t)

    def __ne__(s, t):
        return s._compare(t, True)

    def __lt__(s, t):
        raise TypeError('complex intervals cannot be ordered')
    __le__ = __gt__ = __ge__ = __lt__

    def __neg__(s):
