    if not minx:
        raise ValueError('PSLQ requires a vector of nonzero numbers')
    if minx < tol // 100:
        if verbose:
            print('STOPPING: (one number is too small)')
        return None
    g = sqrt_fixed((4 << prec) // 3, prec)
    A = {}
    B = {}
    H = {}
