        ttype = type(t)
        if ttype in int_types:
            a, b = s._mpq_
            if t:
                if t < 0:
                    a, b, t = (b, a, -t)
                v = new(mpq)
                v._mpq_ = (a ** t, b ** t)
                return v
            raise ZeroDivisionError
        return NotImplemented
