from ..libmp.backend import xrange
from .calculus import defun
try:
    next = next
except NameError:
    next = lambda _: _.next()

@defun
def richardson(ctx, seq):
    if len(seq) < 3:
        raise ValueError('seq should be of minimum length 3')
    if ctx.sign(seq[-1] - seq[-2]) != ctx.sign(seq[-2] - seq[-3]):
        seq = seq[::2]
    N = len(seq) // 2 - 1
    s = ctx.zero
    c = (-1) ** N * N ** N / ctx.mpf(ctx._ifac(N))
    maxc = 1
    for k in xrange(N + 1):
        s += c * seq[N + k]
        maxc = max(abs(c), maxc)
        c *= (k - N) * ctx.mpf(k + N + 1) ** N
        c /= (1 + k) * ctx.mpf(k + N) ** N
    return (s, maxc)

@defun
def shanks(ctx, seq, table=None, randomized=False):
    if len(seq) < 2:
        raise ValueError('seq should be of minimum length 2')
    if table:
        START = len(table)
    else:
        START = 0
        table = []
    STOP = len(seq) - 1
    if STOP & 1:
        STOP -= 1
    one = ctx.one
    eps = +ctx.eps
    if randomized:
        from random import Random
        rnd = Random()
        rnd.seed(START)
    for i in xrange(START, STOP):
        row = []
        for j in xrange(i + 1):
            if j == 0:
                a, b = (0, seq[i + 1] - seq[i])
            else:
                if j == 1:
                    a = seq[i]
                else:
                    a = table[i - 1][j - 2]
                b = row[j - 1] - table[i - 1][j - 1]
            if not b:
                if randomized:
                    b = (1 + rnd.getrandbits(10)) * eps
                elif i & 1:
                    return table[:-1]
                else:
                    return table
            row.append(a + one / b)
        table.append(row)
    return table

class levin_class:

    def __init__(self, method='levin', variant='u'):
        self.variant = variant
        self.n = 0
        self.a0 = 0
        self.theta = 1
        self.A = []
        self.B = []
        self.last = 0
        self.last_s = False
        if method == 'levin':
            self.factor = self.factor_levin
        elif method == 'sidi':
            self.factor = self.factor_sidi
        else:
            raise ValueError('levin: unknown method "%s"' % method)

    def factor_levin(self, i):
        return (self.theta + i) * (self.theta + self.n - 1) ** (self.n - i - 2) / self.ctx.mpf(self.theta + self.n) ** (self.n - i - 1)

    def factor_sidi(self, i):
        return (self.theta + self.n - 1) * (self.theta + self.n - 2) / self.ctx.mpf((self.theta + 2 * self.n - i - 2) * (self.theta + 2 * self.n - i - 3))

    def run(self, s, a0, a1=0):
        if self.variant == 't':
            w = a0
        elif self.variant == 'u':
            w = a0 * (self.theta + self.n)
        elif self.variant == 'v':
            w = a0 * a1 / (a0 - a1)
        else:
            assert False, 'unknown variant'
        if w == 0:
            raise ValueError('levin: zero weight')
        self.A.append(s / w)
        self.B.append(1 / w)
        for i in range(self.n - 1, -1, -1):
            if i == self.n - 1:
                f = 1
            else:
                f = self.factor(i)
            self.A[i] = self.A[i + 1] - f * self.A[i]
            self.B[i] = self.B[i + 1] - f * self.B[i]
        self.n += 1

    def update_psum(self, S):
        if self.variant != 'v':
            if self.n == 0:
                self.run(S[0], S[0])
            while self.n < len(S):
                self.run(S[self.n], S[self.n] - S[self.n - 1])
        else:
            if len(S) == 1:
                self.last = 0
                return (S[0], abs(S[0]))
            if self.n == 0:
                self.a1 = S[1] - S[0]
                self.run(S[0], S[0], self.a1)
            while self.n < len(S) - 1:
                na1 = S[self.n + 1] - S[self.n]
                self.run(S[self.n], self.a1, na1)
                self.a1 = na1
        value = self.A[0] / self.B[0]
        err = abs(value - self.last)
        self.last = value
        return (value, err)

    def update(self, X):
        if self.variant != 'v':
            if self.n == 0:
                self.s = X[0]
                self.run(self.s, X[0])
            while self.n < len(X):
                self.s += X[self.n]
                self.run(self.s, X[self.n])
        else:
            if len(X) == 1:
                self.last = 0
                return (X[0], abs(X[0]))
            if self.n == 0:
                self.s = X[0]
                self.run(self.s, X[0], X[1])
            while self.n < len(X) - 1:
                self.s += X[self.n]
                self.run(self.s, X[self.n], X[self.n + 1])
        value = self.A[0] / self.B[0]
        err = abs(value - self.last)
        self.last = value
        return (value, err)

    def step_psum(self, s):
        if self.variant != 'v':
            if self.n == 0:
                self.last_s = s
                self.run(s, s)
            else:
                self.run(s, s - self.last_s)
                self.last_s = s
        else:
            if isinstance(self.last_s, bool):
                self.last_s = s
                self.last_w = s
                self.last = 0
                return (s, abs(s))
            na1 = s - self.last_s
            self.run(self.last_s, self.last_w, na1)
            self.last_w = na1
            self.last_s = s
        value = self.A[0] / self.B[0]
        err = abs(value - self.last)
        self.last = value
        return (value, err)

    def step(self, x):
        if self.variant != 'v':
            if self.n == 0:
                self.s = x
                self.run(self.s, x)
            else:
                self.s += x
                self.run(self.s, x)
        else:
            if isinstance(self.last_s, bool):
                self.last_s = x
                self.s = 0
                self.last = 0
                return (x, abs(x))
            self.s += self.last_s
            self.run(self.s, self.last_s, x)
            self.last_s = x
        value = self.A[0] / self.B[0]
        err = abs(value - self.last)
        self.last = value
        return (value, err)

def levin(ctx, method='levin', variant='u'):
    L = levin_class(method=method, variant=variant)
    L.ctx = ctx
    return L
