@defun
def elliprg(ctx, x, y, z):
    x = ctx.convert(x)
    y = ctx.convert(y)
    z = ctx.convert(z)
    zeros = (not x) + (not y) + (not z)
    if zeros == 3:
        return (x + y + z) * 0
    if zeros == 2:
        if x:
            return 0.5 * ctx.sqrt(x)
        if y:
            return 0.5 * ctx.sqrt(y)
        return 0.5 * ctx.sqrt(z)
    if zeros == 1:
        if not z:
            x, z = (z, x)

    def terms():
        T1 = 0.5 * z * ctx.elliprf(x, y, z)
        T2 = -0.5 * (x - z) * (y - z) * ctx.elliprd(x, y, z) / 3
        T3 = 0.5 * ctx.sqrt(x) * ctx.sqrt(y) / ctx.sqrt(z)
        return (T1, T2, T3)
    return ctx.sum_accurately(terms)

@defun_wrapped
def ellipf(ctx, phi, m):
    z = phi
    if not (ctx.isnormal(z) and ctx.isnormal(m)):
        if m == 0:
            return z + m
        if z == 0:
            return z * m
        if m == ctx.inf or m == ctx.ninf:
            return z / m
        raise ValueError
    x = z.real
    ctx.prec += max(0, ctx.mag(x))
    pi = +ctx.pi
    away = abs(x) > pi / 2
    if m == 1:
        if away:
            return ctx.inf
    if away:
        d = ctx.nint(x / pi)
        z = z - pi * d
        P = 2 * d * ctx.ellipk(m)
    else:
        P = 0
    c, s = ctx.cos_sin(z)
    return s * ctx.elliprf(c ** 2, 1 - m * s ** 2, 1) + P

@defun_wrapped
def ellipe(ctx, *args):
    if len(args) == 1:
        return ctx._ellipe(args[0])
    else:
        phi, m = args
    z = phi
    if not (ctx.isnormal(z) and ctx.isnormal(m)):
        if m == 0:
            return z + m
        if z == 0:
            return z * m
        if m == ctx.inf or m == ctx.ninf:
            return ctx.inf
        raise ValueError
    x = z.real
    ctx.prec += max(0, ctx.mag(x))
    pi = +ctx.pi
    away = abs(x) > pi / 2
    if away:
        d = ctx.nint(x / pi)
        z = z - pi * d
        P = 2 * d * ctx.ellipe(m)
    else:
        P = 0

    def terms():
        c, s = ctx.cos_sin(z)
        x = c ** 2
        y = 1 - m * s ** 2
        RF = ctx.elliprf(x, y, 1)
        RD = ctx.elliprd(x, y, 1)
        return (s * RF, -m * s ** 3 * RD / 3)
    return ctx.sum_accurately(terms) + P

@defun_wrapped
def ellippi(ctx, *args):
    if len(args) == 2:
        n, m = args
        complete = True
        z = phi = ctx.pi / 2
    else:
        n, phi, m = args
        complete = False
        z = phi
    if not (ctx.isnormal(n) and ctx.isnormal(z) and ctx.isnormal(m)):
        if ctx.isnan(n) or ctx.isnan(z) or ctx.isnan(m):
            raise ValueError
        if complete:
            if m == 0:
                if n == 1:
                    return ctx.inf
                return ctx.pi / (2 * ctx.sqrt(1 - n))
            if n == 0:
                return ctx.ellipk(m)
            if ctx.isinf(n) or ctx.isinf(m):
                return ctx.zero
        else:
            if z == 0:
                return z
            if ctx.isinf(n):
                return ctx.zero
            if ctx.isinf(m):
                return ctx.zero
        if ctx.isinf(n) or ctx.isinf(z) or ctx.isinf(m):
            raise ValueError
    if complete:
        if m == 1:
            if n == 1:
                return ctx.inf
            return -ctx.inf / ctx.sign(n - 1)
        away = False
    else:
        x = z.real
        ctx.prec += max(0, ctx.mag(x))
        pi = +ctx.pi
        away = abs(x) > pi / 2
    if away:
        d = ctx.nint(x / pi)
        z = z - pi * d
        P = 2 * d * ctx.ellippi(n, m)
        if ctx.isinf(P):
            return ctx.inf
    else:
        P = 0

    def terms():
        if complete:
            c, s = (ctx.zero, ctx.one)
        else:
            c, s = ctx.cos_sin(z)
        x = c ** 2
        y = 1 - m * s ** 2
        RF = ctx.elliprf(x, y, 1)
        RJ = ctx.elliprj(x, y, 1, 1 - n * s ** 2)
        return (s * RF, n * s ** 3 * RJ / 3)
    return ctx.sum_accurately(terms) + P

