    zreal = ctx._re(z)
    zimag = ctx._im(z)
    if zimag > 0:
        v += ctx.pi * 0.5j
    elif zimag < 0:
        v -= ctx.pi * 0.5j
    elif zreal < 0:
        v += ctx.pi * 1j
    return v

@defun_wrapped
def shi(ctx, z):
