@defun
def spherharm(ctx, l, m, theta, phi, **kwargs):
    l = ctx.convert(l)
    m = ctx.convert(m)
    theta = ctx.convert(theta)
    phi = ctx.convert(phi)
    l_isint = ctx.isint(l)
    l_natural = l_isint and l >= 0
    m_isint = ctx.isint(m)
    if l_isint and l < 0 and m_isint:
        return ctx.spherharm(-(l + 1), m, theta, phi, **kwargs)
    if theta == 0 and m_isint and (m < 0):
        return ctx.zero * 1j
    if l_natural and m_isint:
        if abs(m) > l:
            return ctx.zero * 1j

        def h(l, m):
            absm = abs(m)
            C = [-1, ctx.expj(m * phi), (2 * l + 1) * ctx.fac(l + absm) / ctx.pi / ctx.fac(l - absm), ctx.sin(theta) ** 2, ctx.fac(absm), 2]
