from .functions import defun, defun_wrapped

@defun
def qp(ctx, a, q=None, n=None, **kwargs):
    a = ctx.convert(a)
    if n is None:
        n = ctx.inf
    else:
        n = ctx.convert(n)
    if n < 0:
        raise ValueError('n cannot be negative')
    if q is None:
        q = a
    else:
        q = ctx.convert(q)
    if n == 0:
        return ctx.one + 0 * (a + q)
    infinite = n == ctx.inf
    same = a == q
    if infinite:
        if abs(q) >= 1:
            if same and (q == -1 or q == 1):
                return ctx.zero * q
            raise ValueError('q-function only defined for |q| < 1')
        elif q == 0:
            return ctx.one - a
    maxterms = kwargs.get('maxterms', 50 * ctx.prec)
    if infinite and same:

        def terms():
            t = 1
            yield t
            k = 1
            x1 = q
            x2 = q ** 2
            while 1:
                yield ((-1) ** k * x1)
                yield ((-1) ** k * x2)
                x1 *= q ** (3 * k + 1)
                x2 *= q ** (3 * k + 2)
                k += 1
                if k > maxterms:
                    raise ctx.NoConvergence
        return ctx.sum_accurately(terms)

    def factors():
        k = 0
        r = ctx.one
        while 1:
            yield (1 - a * r)
            r *= q
            k += 1
            if k >= n:
                return
            if k > maxterms:
                raise ctx.NoConvergence
    return ctx.mul_accurately(factors)

@defun_wrapped
def qgamma(ctx, z, q, **kwargs):
    if abs(q) > 1:
        return ctx.qgamma(z, 1 / q) * q ** ((z - 2) * (z - 1) * 0.5)
    return ctx.qp(q, q, None, **kwargs) / ctx.qp(q ** z, q, None, **kwargs) * (1 - q) ** (1 - z)

@defun_wrapped
def qfac(ctx, z, q, **kwargs):
    if ctx.isint(z) and ctx._re(z) > 0:
        n = int(ctx._re(z))
        return ctx.qp(q, q, n, **kwargs) / (1 - q) ** n
    return ctx.qgamma(z + 1, q, **kwargs)

@defun
def qhyper(ctx, a_s, b_s, q, z, **kwargs):
    a_s = [ctx.convert(a) for a in a_s]
    b_s = [ctx.convert(b) for b in b_s]
    q = ctx.convert(q)
    z = ctx.convert(z)
    r = len(a_s)
    s = len(b_s)
    d = 1 + s - r
    maxterms = kwargs.get('maxterms', 50 * ctx.prec)

    def terms():
        t = ctx.one
        yield t
        qk = 1
        k = 0
        x = 1
        while 1:
            for a in a_s:
                p = 1 - a * qk
                t *= p
            for b in b_s:
                p = 1 - b * qk
                if not p:
                    raise ValueError
                t /= p
            t *= z
            x *= (-1) ** d * qk ** d
            qk *= q
            t /= 1 - qk
            k += 1
            yield (t * x)
            if k > maxterms:
                raise ctx.NoConvergence
    return ctx.sum_accurately(terms)

