            raise ComplexResult('acos(x) is real only for -1 <= x <= 1')
        if x == fnone:
            return mpf_pi(prec, rnd)
    wp = prec + 15
    a = mpf_mul(x, x)
    b = mpf_sqrt(mpf_sub(fone, a, wp), wp)
    c = mpf_div(b, mpf_add(fone, x, wp), wp)
    return mpf_shift(mpf_atan(c, prec, rnd), 1)

def mpf_asinh(x, prec, rnd=round_fast):
    wp = prec + 20
    sign, man, exp, bc = x
    mag = exp + bc
    if mag < -8:
        if mag < -wp:
            return mpf_perturb(x, 1 - sign, prec, rnd)
        wp += -mag
    q = mpf_sqrt(mpf_add(mpf_mul(x, x), fone, wp), wp)
    q = mpf_add(mpf_abs(x), q, wp)
    if sign:
        return mpf_neg(mpf_log(q, prec, negative_rnd[rnd]))
    else:
        return mpf_log(q, prec, rnd)

def mpf_acosh(x, prec, rnd=round_fast):
    wp = prec + 15
    if mpf_cmp(x, fone) == -1:
        raise ComplexResult('acosh(x) is real only for x >= 1')
    q = mpf_sqrt(mpf_add(mpf_mul(x, x), fnone, wp), wp)
    return mpf_log(mpf_add(x, q, wp), prec, rnd)

def mpf_atanh(x, prec, rnd=round_fast):
    sign, man, exp, bc = x
    if not man and exp:
        if x in (fzero, fnan):
            return x
        raise ComplexResult('atanh(x) is real only for -1 <= x <= 1')
    mag = bc + exp
    if mag > 0:
        if mag == 1 and man == 1:
            return [finf, fninf][sign]
        raise ComplexResult('atanh(x) is real only for -1 <= x <= 1')
    wp = prec + 15
    if mag < -8:
        if mag < -wp:
            return mpf_perturb(x, sign, prec, rnd)
        wp += -mag
    a = mpf_add(x, fone, wp)
    b = mpf_sub(fone, x, wp)
    return mpf_shift(mpf_log(mpf_div(a, b, wp), prec, rnd), -1)

def mpf_fibonacci(x, prec, rnd=round_fast):
    sign, man, exp, bc = x
    if not man:
        if x == fninf:
            return fnan
        return x
    size = abs(exp + bc)
    if exp >= 0:
        if size < 10 or size <= bitcount(prec):
            return from_int(ifib(to_int(x)), prec, rnd)
    wp = prec + size + 20
    a = mpf_phi(wp)
    b = mpf_add(mpf_shift(a, 1), fnone, wp)
    u = mpf_pow(a, x, wp)
    v = mpf_cos_pi(x, wp)
    v = mpf_div(v, u, wp)
    u = mpf_sub(u, v, wp)
    u = mpf_div(u, b, prec, rnd)
    return u

def exponential_series(x, prec, type=0):
    if x < 0:
        x = -x
        sign = 1
    else:
        sign = 0
    r = int(0.5 * prec ** 0.5)
    xmag = bitcount(x) - prec
    r = max(0, xmag + r)
    extra = 10 + 2 * max(r, -xmag)
    wp = prec + extra
    x <<= extra - r
    one = MPZ_ONE << wp
    alt = type == 2
    if prec < EXP_SERIES_U_CUTOFF:
        x2 = a = x * x >> wp
        x4 = x2 * x2 >> wp
        s0 = s1 = MPZ_ZERO
        k = 2
        while a:
            a //= (k - 1) * k
            s0 += a
            k += 2
            a //= (k - 1) * k
            s1 += a
            k += 2
            a = a * x4 >> wp
        s1 = x2 * s1 >> wp
        if alt:
            c = s1 - s0 + one
        else:
            c = s1 + s0 + one
    else:
        u = int(0.3 * prec ** 0.35)
        x2 = a = x * x >> wp
        xpowers = [one, x2]
        for i in xrange(1, u):
            xpowers.append(xpowers[-1] * x2 >> wp)
        sums = [MPZ_ZERO] * u
        k = 2
        while a:
            for i in xrange(u):
                a //= (k - 1) * k
                if alt and k & 2:
                    sums[i] -= a
                else:
                    sums[i] += a
                k += 2
            a = a * xpowers[-1] >> wp
        for i in xrange(1, u):
            sums[i] = sums[i] * xpowers[i] >> wp
        c = sum(sums) + one
    if type == 0:
        s = isqrt_fast(c * c - (one << wp))
        if sign:
            v = c - s
        else:
            v = c + s
        for i in xrange(r):
            v = v * v >> wp
        return v >> extra
    else:
        pshift = wp - 1
        for i in xrange(r):
            c = (c * c >> pshift) - one
        s = isqrt_fast(abs((one << wp) - c * c))
        if sign:
            s = -s
        return (c >> extra, s >> extra)

def exp_basecase(x, prec):
    if prec > EXP_COSH_CUTOFF:
        return exponential_series(x, prec, 0)
    r = int(prec ** 0.5)
    prec += r
    s0 = s1 = MPZ_ONE << prec
    k = 2
    a = x2 = x * x >> prec
    while a:
        a //= k
        s0 += a
        k += 1
        a //= k
        s1 += a
        k += 1
        a = a * x2 >> prec
    s1 = s1 * x >> prec
    s = s0 + s1
    u = r
    while r:
        s = s * s >> prec
        r -= 1
    return s >> u

def exp_expneg_basecase(x, prec):
    if prec > EXP_COSH_CUTOFF:
        cosh, sinh = exponential_series(x, prec, 1)
        return (cosh + sinh, cosh - sinh)
    a = exp_basecase(x, prec)
    b = (MPZ_ONE << prec + prec) // a
    return (a, b)

def cos_sin_basecase(x, prec):
    if prec > COS_SIN_CACHE_PREC:
        return exponential_series(x, prec, 2)
    precs = prec - COS_SIN_CACHE_STEP
    t = x >> precs
    n = int(t)
    if n not in cos_sin_cache:
        w = t << 10 + COS_SIN_CACHE_PREC - COS_SIN_CACHE_STEP
        cos_t, sin_t = exponential_series(w, 10 + COS_SIN_CACHE_PREC, 2)
        cos_sin_cache[n] = (cos_t >> 10, sin_t >> 10)
    cos_t, sin_t = cos_sin_cache[n]
    offset = COS_SIN_CACHE_PREC - prec
    cos_t >>= offset
    sin_t >>= offset
    x -= t << precs
    cos = MPZ_ONE << prec
    sin = x
    k = 2
    a = -(x * x >> prec)
    while a:
        a //= k
        cos += a
        k += 1
        a = a * x >> prec
        a //= k
        sin += a
        k += 1
        a = -(a * x >> prec)
    return (cos * cos_t - sin * sin_t >> prec, sin * cos_t + cos * sin_t >> prec)

def mpf_exp(x, prec, rnd=round_fast):
    sign, man, exp, bc = x
    if man:
        mag = bc + exp
        wp = prec + 14
        if sign:
            man = -man
        if prec > 600 and exp >= 0:
            e = mpf_e(wp + int(1.45 * mag))
            return mpf_pow_int(e, man << exp, prec, rnd)
        if mag < -wp:
            return mpf_perturb(fone, sign, prec, rnd)
        if mag > 1:
            wpmod = wp + mag
            offset = exp + wpmod
            if offset >= 0:
                t = man << offset
            else:
                t = man >> -offset
            lg2 = ln2_fixed(wpmod)
            n, t = divmod(t, lg2)
            n = int(n)
            t >>= mag
        else:
            offset = exp + wp
            if offset >= 0:
                t = man << offset
            else:
                t = man >> -offset
            n = 0
        man = exp_basecase(t, wp)
        return from_man_exp(man, n - wp, prec, rnd)
    if not exp:
        return fone
    if x == fninf:
        return fzero
    return x

def mpf_cosh_sinh(x, prec, rnd=round_fast, tanh=0):
    sign, man, exp, bc = x
    if not man and exp:
        if tanh:
            if x == finf:
                return fone
            if x == fninf:
                return fnone
            return fnan
        if x == finf:
            return (finf, finf)
        if x == fninf:
            return (finf, fninf)
        return (fnan, fnan)
    mag = exp + bc
    wp = prec + 14
    if mag < -4:
        if mag < -wp:
            if tanh:
                return mpf_perturb(x, 1 - sign, prec, rnd)
            cosh = mpf_perturb(fone, 0, prec, rnd)
            sinh = mpf_perturb(x, sign, prec, rnd)
            return (cosh, sinh)
        wp += -mag
    if mag > 10:
        if 3 * (1 << mag - 1) > wp:
            if tanh:
                return mpf_perturb([fone, fnone][sign], 1 - sign, prec, rnd)
            c = s = mpf_shift(mpf_exp(mpf_abs(x), prec, rnd), -1)
            if sign:
                s = mpf_neg(s)
            return (c, s)
    if mag > 1:
        wpmod = wp + mag
        offset = exp + wpmod
        if offset >= 0:
            t = man << offset
        else:
            t = man >> -offset
        lg2 = ln2_fixed(wpmod)
        n, t = divmod(t, lg2)
        n = int(n)
        t >>= mag
    else:
        offset = exp + wp
        if offset >= 0:
            t = man << offset
        else:
            t = man >> -offset
        n = 0
    a, b = exp_expneg_basecase(t, wp)
    cosh = a + (b >> 2 * n)
    sinh = a - (b >> 2 * n)
    if sign:
        sinh = -sinh
    if tanh:
        man = (sinh << wp) // cosh
        return from_man_exp(man, -wp, prec, rnd)
    else:
        cosh = from_man_exp(cosh, n - wp - 1, prec, rnd)
        sinh = from_man_exp(sinh, n - wp - 1, prec, rnd)
        return (cosh, sinh)

def mod_pi2(man, exp, mag, wp):
    if mag > 0:
        i = 0
        while 1:
            cancellation_prec = 20 << i
            wpmod = wp + mag + cancellation_prec
            pi2 = pi_fixed(wpmod - 1)
            pi4 = pi2 >> 1
            offset = wpmod + exp
            if offset >= 0:
                t = man << offset
            else:
                t = man >> -offset
            n, y = divmod(t, pi2)
            if y > pi4:
                small = pi2 - y
            else:
                small = y
            if small >> wp + mag - 10:
                n = int(n)
                t = y >> mag
                wp = wpmod - mag
                break
            i += 1
    else:
        wp += -mag
        offset = exp + wp
        if offset >= 0:
            t = man << offset
        else:
            t = man >> -offset
        n = 0
    return (t, n, wp)

def mpf_cos_sin(x, prec, rnd=round_fast, which=0, pi=False):
    sign, man, exp, bc = x
    if not man:
        if exp:
            c, s = (fnan, fnan)
        else:
            c, s = (fone, fzero)
        if which == 0:
            return (c, s)
        if which == 1:
            return c
        if which == 2:
            return s
        if which == 3:
            return s
    mag = bc + exp
    wp = prec + 10
    if mag < 0:
        if mag < -wp:
            if pi:
                x = mpf_mul(x, mpf_pi(wp))
            c = mpf_perturb(fone, 1, prec, rnd)
            s = mpf_perturb(x, 1 - sign, prec, rnd)
            if which == 0:
                return (c, s)
            if which == 1:
                return c
            if which == 2:
                return s
            if which == 3:
                return mpf_perturb(x, sign, prec, rnd)
    if pi:
        if exp >= -1:
            if exp == -1:
                c = fzero
                s = (fone, fnone)[bool(man & 2) ^ sign]
            elif exp == 0:
                c, s = (fnone, fzero)
            else:
                c, s = (fone, fzero)
            if which == 0:
                return (c, s)
            if which == 1:
                return c
            if which == 2:
                return s
            if which == 3:
                return mpf_div(s, c, prec, rnd)
        n = (man >> -exp - 2) + 1 >> 1
        man = man - (n << -exp - 1)
        mag2 = bitcount(man) + exp
        wp = prec + 10 - mag2
        offset = exp + wp
        if offset >= 0:
            t = man << offset
        else:
            t = man >> -offset
        t = t * pi_fixed(wp) >> wp
    else:
        t, n, wp = mod_pi2(man, exp, mag, wp)
    c, s = cos_sin_basecase(t, wp)
    m = n & 3
    if m == 1:
        c, s = (-s, c)
    elif m == 2:
        c, s = (-c, -s)
    elif m == 3:
        c, s = (s, -c)
    if sign:
        s = -s
    if which == 0:
        c = from_man_exp(c, -wp, prec, rnd)
        s = from_man_exp(s, -wp, prec, rnd)
        return (c, s)
    if which == 1:
        return from_man_exp(c, -wp, prec, rnd)
    if which == 2:
        return from_man_exp(s, -wp, prec, rnd)
    if which == 3:
        return from_rational(s, c, prec, rnd)

def mpf_cos(x, prec, rnd=round_fast):
    return mpf_cos_sin(x, prec, rnd, 1)

def mpf_sin(x, prec, rnd=round_fast):
    return mpf_cos_sin(x, prec, rnd, 2)

def mpf_tan(x, prec, rnd=round_fast):
    return mpf_cos_sin(x, prec, rnd, 3)

def mpf_cos_sin_pi(x, prec, rnd=round_fast):
    return mpf_cos_sin(x, prec, rnd, 0, 1)

def mpf_cos_pi(x, prec, rnd=round_fast):
    return mpf_cos_sin(x, prec, rnd, 1, 1)

def mpf_sin_pi(x, prec, rnd=round_fast):
    return mpf_cos_sin(x, prec, rnd, 2, 1)

def mpf_cosh(x, prec, rnd=round_fast):
    return mpf_cosh_sinh(x, prec, rnd)[0]

def mpf_sinh(x, prec, rnd=round_fast):
    return mpf_cosh_sinh(x, prec, rnd)[1]

def mpf_tanh(x, prec, rnd=round_fast):
    return mpf_cosh_sinh(x, prec, rnd, tanh=1)

def cos_sin_fixed(x, prec, pi2=None):
    if pi2 is None:
        pi2 = pi_fixed(prec - 1)
    n, t = divmod(x, pi2)
    n = int(n)
    c, s = cos_sin_basecase(t, prec)
    m = n & 3
    if m == 0:
        return (c, s)
    if m == 1:
        return (-s, c)
    if m == 2:
        return (-c, -s)
    if m == 3:
        return (s, -c)

def exp_fixed(x, prec, ln2=None):
    if ln2 is None:
        ln2 = ln2_fixed(prec)
    n, t = divmod(x, ln2)
    n = int(n)
    v = exp_basecase(t, prec)
    if n >= 0:
        return v << n
    else:
        return v >> -n
