def complex_int_pow(a, b, n):
    wre = 1
    wim = 0
    while n:
        if n & 1:
            wre, wim = (wre * a - wim * b, wim * a + wre * b)
            n -= 1
        a, b = (a * a - b * b, 2 * a * b)
        n //= 2
    return (wre, wim)

