        u = mpf_shift(t, -1)
        re = mpf_sqrt(u, prec, rnd)
        v = mpf_shift(t, 1)
        w = mpf_sqrt(v, wp)
        im = mpf_div(b, w, prec, rnd)
    else:
        t = mpf_sub(mpc_abs((a, b), wp), a, wp)
        u = mpf_shift(t, -1)
        im = mpf_sqrt(u, prec, rnd)
        v = mpf_shift(t, 1)
        w = mpf_sqrt(v, wp)
