            if man and exp >= 0:
                return mpci_pow_int(x, (-1) ** sign * int(man << exp), prec)
            if yb == fzero:
                return mpci_pow_int(x, 0, prec)
    wp = prec + 20
    return mpci_exp(mpci_mul(y, mpci_log(x, wp), wp), prec)

