from ..libmp.backend import xrange

class MatrixCalculusMethods(object):

    def _exp_pade(ctx, a):

        def eps_pade(p):
            return ctx.mpf(2) ** (3 - 2 * p) * ctx.factorial(p) ** 2 / (ctx.factorial(2 * p) ** 2 * (2 * p + 1))
        q = 4
        extraq = 8
        while 1:
            if eps_pade(q) < ctx.eps:
                break
            q += 1
        q += extraq
        j = int(max(1, ctx.mag(ctx.mnorm(a, 'inf'))))
        extra = q
        prec = ctx.prec
        ctx.dps += extra + 3
        try:
            a = a / 2 ** j
            na = a.rows
            den = ctx.eye(na)
            num = ctx.eye(na)
            x = ctx.eye(na)
            c = ctx.mpf(1)
            for k in range(1, q + 1):
                c *= ctx.mpf(q - k + 1) / ((2 * q - k + 1) * k)
                x = a * x
                cx = c * x
                num += cx
                den += (-1) ** k * cx
            f = ctx.lu_solve_mat(den, num)
            for k in range(j):
                f = f * f
        finally:
            ctx.prec = prec
        return f * 1

    def expm(ctx, A, method='taylor'):
        if method == 'pade':
            prec = ctx.prec
            try:
                A = ctx.matrix(A)
                ctx.prec += 2 * A.rows
                res = ctx._exp_pade(A)
            finally:
                ctx.prec = prec
            return res
        A = ctx.matrix(A)
        prec = ctx.prec
        j = int(max(1, ctx.mag(ctx.mnorm(A, 'inf'))))
        j += int(0.5 * prec ** 0.5)
        try:
            ctx.prec += 10 + 2 * j
            tol = +ctx.eps
            A = A / 2 ** j
            T = A
            Y = A ** 0 + A
            k = 2
            while 1:
                T *= A * (1 / ctx.mpf(k))
                if ctx.mnorm(T, 'inf') < tol:
                    break
                Y += T
                k += 1
            for k in xrange(j):
                Y = Y * Y
        finally:
            ctx.prec = prec
        Y *= 1
        return Y

    def cosm(ctx, A):
        B = 0.5 * (ctx.expm(A * ctx.j) + ctx.expm(A * -ctx.j))
        if not sum(A.apply(ctx.im).apply(abs)):
            B = B.apply(ctx.re)
        return B

    def sinm(ctx, A):
        B = -0.5j * (ctx.expm(A * ctx.j) - ctx.expm(A * -ctx.j))
        if not sum(A.apply(ctx.im).apply(abs)):
            B = B.apply(ctx.re)
        return B

    def _sqrtm_rot(ctx, A, _may_rotate):
        u = ctx.j ** 0.3
        return ctx.sqrtm(u * A, _may_rotate) / ctx.sqrt(u)

    def sqrtm(ctx, A, _may_rotate=2):
        A = ctx.matrix(A)
        if A * 0 == A:
            return A
        prec = ctx.prec
        if _may_rotate:
            d = ctx.det(A)
            if abs(ctx.im(d)) < 16 * ctx.eps and ctx.re(d) < 0:
                return ctx._sqrtm_rot(A, _may_rotate - 1)
        try:
            ctx.prec += 10
            tol = ctx.eps * 128
            Y = A
            Z = I = A ** 0
            k = 0
            while 1:
                Yprev = Y
                try:
                    Y, Z = (0.5 * (Y + ctx.inverse(Z)), 0.5 * (Z + ctx.inverse(Y)))
                except ZeroDivisionError:
                    if _may_rotate:
                        Y = ctx._sqrtm_rot(A, _may_rotate - 1)
                        break
                    else:
                        raise
                mag1 = ctx.mnorm(Y - Yprev, 'inf')
                mag2 = ctx.mnorm(Y, 'inf')
                if mag1 <= mag2 * tol:
                    break
                if _may_rotate and k > 6 and (not mag1 < mag2 * 0.001):
                    return ctx._sqrtm_rot(A, _may_rotate - 1)
                k += 1
                if k > ctx.prec:
                    raise ctx.NoConvergence
        finally:
            ctx.prec = prec
        Y *= 1
        return Y

    def logm(ctx, A):
        A = ctx.matrix(A)
        prec = ctx.prec
        try:
            ctx.prec += 10
            tol = ctx.eps * 128
            I = A ** 0
            B = A
            n = 0
            while 1:
                B = ctx.sqrtm(B)
                n += 1
                if ctx.mnorm(B - I, 'inf') < 0.125:
                    break
            T = X = B - I
            L = X * 0
            k = 1
            while 1:
                if k & 1:
                    L += T / k
                else:
                    L -= T / k
                T *= X
                if ctx.mnorm(T, 'inf') < tol:
                    break
                k += 1
                if k > ctx.prec:
                    raise ctx.NoConvergence
        finally:
            ctx.prec = prec
        L *= 2 ** n
        return L

    def powm(ctx, A, r):
        A = ctx.matrix(A)
        r = ctx.convert(r)
        prec = ctx.prec
        try:
            ctx.prec += 10
            if ctx.isint(r):
                v = A ** int(r)
            elif ctx.isint(r * 2):
                y = int(r * 2)
                v = ctx.sqrtm(A) ** y
            else:
                v = ctx.expm(r * ctx.logm(A))
        finally:
            ctx.prec = prec
        v *= 1
        return v

