from ..libmp.backend import xrange

class Eigen(object):
    pass

def defun(f):
    setattr(Eigen, f.__name__, f)
    return f

def hessenberg_reduce_0(ctx, A, T):
    n = A.rows
    if n <= 2:
        return
    for i in xrange(n - 1, 1, -1):
        scale = 0
        for k in xrange(0, i):
            scale += abs(ctx.re(A[i, k])) + abs(ctx.im(A[i, k]))
        scale_inv = 0
        if scale != 0:
            scale_inv = 1 / scale
        if scale == 0 or ctx.isinf(scale_inv):
            T[i] = 0
            A[i, i - 1] = 0
            continue
        H = 0
        for k in xrange(0, i):
            A[i, k] *= scale_inv
            rr = ctx.re(A[i, k])
            ii = ctx.im(A[i, k])
            H += rr * rr + ii * ii
        F = A[i, i - 1]
        f = abs(F)
        G = ctx.sqrt(H)
        A[i, i - 1] = -G * scale
        if f == 0:
            T[i] = G
        else:
            ff = F / f
            T[i] = F + G * ff
            A[i, i - 1] *= ff
        H += G * f
        H = 1 / ctx.sqrt(H)
        T[i] *= H
        for k in xrange(0, i - 1):
            A[i, k] *= H
        for j in xrange(0, i):
            G = ctx.conj(T[i]) * A[j, i - 1]
            for k in xrange(0, i - 1):
                G += ctx.conj(A[i, k]) * A[j, k]
            A[j, i - 1] -= G * T[i]
            for k in xrange(0, i - 1):
                A[j, k] -= G * A[i, k]
        for j in xrange(0, n):
            G = T[i] * A[i - 1, j]
            for k in xrange(0, i - 1):
                G += A[i, k] * A[k, j]
            A[i - 1, j] -= G * ctx.conj(T[i])
            for k in xrange(0, i - 1):
                A[k, j] -= G * ctx.conj(A[i, k])

def hessenberg_reduce_1(ctx, A, T):
    n = A.rows
    if n == 1:
        A[0, 0] = 1
        return
    A[0, 0] = A[1, 1] = 1
    A[0, 1] = A[1, 0] = 0
    for i in xrange(2, n):
        if T[i] != 0:
            for j in xrange(0, i):
                G = T[i] * A[i - 1, j]
                for k in xrange(0, i - 1):
                    G += A[i, k] * A[k, j]
                A[i - 1, j] -= G * ctx.conj(T[i])
                for k in xrange(0, i - 1):
                    A[k, j] -= G * ctx.conj(A[i, k])
        A[i, i] = 1
        for j in xrange(0, i):
            A[j, i] = A[i, j] = 0

@defun
def hessenberg(ctx, A, overwrite_a=False):
    n = A.rows
    if n == 1:
        return (ctx.matrix([[1]]), A)
    if not overwrite_a:
        A = A.copy()
    T = ctx.matrix(n, 1)
    hessenberg_reduce_0(ctx, A, T)
    Q = A.copy()
    hessenberg_reduce_1(ctx, Q, T)
    for x in xrange(n):
        for y in xrange(x + 2, n):
            A[y, x] = 0
    return (Q, A)

def qr_step(ctx, n0, n1, A, Q, shift):
    n = A.rows
    c = A[n0, n0] - shift
    s = A[n0 + 1, n0]
    v = ctx.hypot(ctx.hypot(ctx.re(c), ctx.im(c)), ctx.hypot(ctx.re(s), ctx.im(s)))
    if v == 0:
        v = 1
        c = 1
        s = 0
    else:
        c /= v
        s /= v
    cc = ctx.conj(c)
    cs = ctx.conj(s)
    for k in xrange(n0, n):
        x = A[n0, k]
        y = A[n0 + 1, k]
        A[n0, k] = cc * x + cs * y
        A[n0 + 1, k] = c * y - s * x
    for k in xrange(min(n1, n0 + 3)):
        x = A[k, n0]
        y = A[k, n0 + 1]
        A[k, n0] = c * x + s * y
        A[k, n0 + 1] = cc * y - cs * x
    if not isinstance(Q, bool):
        for k in xrange(n):
            x = Q[k, n0]
            y = Q[k, n0 + 1]
            Q[k, n0] = c * x + s * y
            Q[k, n0 + 1] = cc * y - cs * x
    for j in xrange(n0, n1 - 2):
        c = A[j + 1, j]
        s = A[j + 2, j]
        v = ctx.hypot(ctx.hypot(ctx.re(c), ctx.im(c)), ctx.hypot(ctx.re(s), ctx.im(s)))
        if v == 0:
            A[j + 1, j] = 0
            v = 1
            c = 1
            s = 0
        else:
            A[j + 1, j] = v
            c /= v
            s /= v
        A[j + 2, j] = 0
        cc = ctx.conj(c)
        cs = ctx.conj(s)
        for k in xrange(j + 1, n):
            x = A[j + 1, k]
            y = A[j + 2, k]
            A[j + 1, k] = cc * x + cs * y
            A[j + 2, k] = c * y - s * x
        for k in xrange(0, min(n1, j + 4)):
            x = A[k, j + 1]
            y = A[k, j + 2]
            A[k, j + 1] = c * x + s * y
            A[k, j + 2] = cc * y - cs * x
        if not isinstance(Q, bool):
            for k in xrange(0, n):
                x = Q[k, j + 1]
                y = Q[k, j + 2]
                Q[k, j + 1] = c * x + s * y
                Q[k, j + 2] = cc * y - cs * x

def hessenberg_qr(ctx, A, Q):
    n = A.rows
    norm = 0
    for x in xrange(n):
        for y in xrange(min(x + 2, n)):
            norm += ctx.re(A[y, x]) ** 2 + ctx.im(A[y, x]) ** 2
    norm = ctx.sqrt(norm) / n
    if norm == 0:
        return
    n0 = 0
    n1 = n
    eps = ctx.eps / (100 * n)
    maxits = ctx.dps * 4
    its = totalits = 0
    while 1:
        k = n0
        while k + 1 < n1:
            s = abs(ctx.re(A[k, k])) + abs(ctx.im(A[k, k])) + abs(ctx.re(A[k + 1, k + 1])) + abs(ctx.im(A[k + 1, k + 1]))
            if s < eps * norm:
                s = norm
            if abs(A[k + 1, k]) < eps * s:
                break
            k += 1
        if k + 1 < n1:
            A[k + 1, k] = 0
            n0 = k + 1
            its = 0
            if n0 + 1 >= n1:
                n0 = 0
                n1 = k + 1
                if n1 < 2:
                    return
        else:
            if its % 30 == 10:
                shift = A[n1 - 1, n1 - 2]
            elif its % 30 == 20:
                shift = abs(A[n1 - 1, n1 - 2])
            elif its % 30 == 29:
                shift = norm
            else:
                t = A[n1 - 2, n1 - 2] + A[n1 - 1, n1 - 1]
                s = (A[n1 - 1, n1 - 1] - A[n1 - 2, n1 - 2]) ** 2 + 4 * A[n1 - 1, n1 - 2] * A[n1 - 2, n1 - 1]
                if ctx.re(s) > 0:
                    s = ctx.sqrt(s)
                else:
                    s = ctx.sqrt(-s) * 1j
                a = (t + s) / 2
                b = (t - s) / 2
                if abs(A[n1 - 1, n1 - 1] - a) > abs(A[n1 - 1, n1 - 1] - b):
                    shift = b
                else:
                    shift = a
            its += 1
            totalits += 1
            qr_step(ctx, n0, n1, A, Q, shift)
            if its > maxits:
                raise RuntimeError('qr: failed to converge after %d steps' % its)

@defun
def schur(ctx, A, overwrite_a=False):
    n = A.rows
    if n == 1:
        return (ctx.matrix([[1]]), A)
    if not overwrite_a:
        A = A.copy()
    T = ctx.matrix(n, 1)
    hessenberg_reduce_0(ctx, A, T)
    Q = A.copy()
    hessenberg_reduce_1(ctx, Q, T)
    for x in xrange(n):
        for y in xrange(x + 2, n):
            A[y, x] = 0
    hessenberg_qr(ctx, A, Q)
    return (Q, A)

def eig_tr_r(ctx, A):
    n = A.rows
    ER = ctx.eye(n)
    eps = ctx.eps
    unfl = ctx.ldexp(ctx.one, -ctx.prec * 30)
    smlnum = unfl * (n / eps)
    simin = 1 / ctx.sqrt(eps)
    rmax = 1
    for i in xrange(1, n):
        s = A[i, i]
        smin = max(eps * abs(s), smlnum)
        for j in xrange(i - 1, -1, -1):
            r = 0
            for k in xrange(j + 1, i + 1):
                r += A[j, k] * ER[k, i]
            t = A[j, j] - s
            if abs(t) < smin:
                t = smin
            r = -r / t
            ER[j, i] = r
            rmax = max(rmax, abs(r))
            if rmax > simin:
                for k in xrange(j, i + 1):
                    ER[k, i] /= rmax
                rmax = 1
        if rmax != 1:
            for k in xrange(0, i + 1):
                ER[k, i] /= rmax
    return ER

def eig_tr_l(ctx, A):
    n = A.rows
    EL = ctx.eye(n)
    eps = ctx.eps
    unfl = ctx.ldexp(ctx.one, -ctx.prec * 30)
    smlnum = unfl * (n / eps)
    simin = 1 / ctx.sqrt(eps)
    rmax = 1
    for i in xrange(0, n - 1):
        s = A[i, i]
        smin = max(eps * abs(s), smlnum)
        for j in xrange(i + 1, n):
            r = 0
            for k in xrange(i, j):
                r += EL[i, k] * A[k, j]
            t = A[j, j] - s
            if abs(t) < smin:
                t = smin
            r = -r / t
            EL[i, j] = r
            rmax = max(rmax, abs(r))
            if rmax > simin:
                for k in xrange(i, j + 1):
                    EL[i, k] /= rmax
                rmax = 1
        if rmax != 1:
            for k in xrange(i, n):
                EL[i, k] /= rmax
    return EL

@defun
def eig(ctx, A, left=False, right=True, overwrite_a=False):
    n = A.rows
    if n == 1:
        if left and (not right):
            return ([A[0]], ctx.matrix([[1]]))
        if right and (not left):
            return ([A[0]], ctx.matrix([[1]]))
        return ([A[0]], ctx.matrix([[1]]), ctx.matrix([[1]]))
    if not overwrite_a:
        A = A.copy()
    T = ctx.zeros(n, 1)
    hessenberg_reduce_0(ctx, A, T)
    if left or right:
        Q = A.copy()
        hessenberg_reduce_1(ctx, Q, T)
    else:
        Q = False
    for x in xrange(n):
        for y in xrange(x + 2, n):
            A[y, x] = 0
    hessenberg_qr(ctx, A, Q)
    E = [0 for i in xrange(n)]
    for i in xrange(n):
        E[i] = A[i, i]
    if not (left or right):
        return E
    if left:
        EL = eig_tr_l(ctx, A)
        EL = EL * Q.transpose_conj()
    if right:
        ER = eig_tr_r(ctx, A)
        ER = Q * ER
    if left and (not right):
        return (E, EL)
    if right and (not left):
        return (E, ER)
    return (E, EL, ER)

@defun
def eig_sort(ctx, E, EL=False, ER=False, f='real'):
    if isinstance(f, str):
        if f == 'real':
            f = ctx.re
        elif f == 'imag':
            f = ctx.im
        elif f == 'abs':
            f = abs
        else:
            raise RuntimeError('unknown function %s' % f)
    n = len(E)
    for i in xrange(n):
        imax = i
        s = f(E[i])
        for j in xrange(i + 1, n):
            c = f(E[j])
            if c < s:
                s = c
                imax = j
        if imax != i:
            z = E[i]
            E[i] = E[imax]
            E[imax] = z
            if not isinstance(EL, bool):
                for j in xrange(n):
                    z = EL[i, j]
                    EL[i, j] = EL[imax, j]
                    EL[imax, j] = z
            if not isinstance(ER, bool):
                for j in xrange(n):
                    z = ER[j, i]
                    ER[j, i] = ER[j, imax]
                    ER[j, imax] = z
    if isinstance(EL, bool) and isinstance(ER, bool):
        return E
    if isinstance(EL, bool) and (not isinstance(ER, bool)):
        return (E, ER)
    if isinstance(ER, bool) and (not isinstance(EL, bool)):
        return (E, EL)
    return (E, EL, ER)

