from ..libmp.backend import xrange
from .eigen import defun

def r_sy_tridiag(ctx, A, D, E, calc_ev=True):
    n = A.rows
    for i in xrange(n - 1, 0, -1):
        scale = 0
        for k in xrange(0, i):
            scale += abs(A[k, i])
        scale_inv = 0
        if scale != 0:
            scale_inv = 1 / scale
        if i == 1 or scale == 0 or ctx.isinf(scale_inv):
            E[i] = A[i - 1, i]
            D[i] = 0
            continue
        H = 0
        for k in xrange(0, i):
            A[k, i] *= scale_inv
            H += A[k, i] * A[k, i]
        F = A[i - 1, i]
        G = ctx.sqrt(H)
        if F > 0:
            G = -G
        E[i] = scale * G
        H -= F * G
        A[i - 1, i] = F - G
        F = 0
        for j in xrange(0, i):
            if calc_ev:
                A[i, j] = A[j, i] / H
            G = 0
            for k in xrange(0, j + 1):
                G += A[k, j] * A[k, i]
            for k in xrange(j + 1, i):
                G += A[j, k] * A[k, i]
            E[j] = G / H
            F += E[j] * A[j, i]
        HH = F / (2 * H)
        for j in xrange(0, i):
            F = A[j, i]
            G = E[j] - HH * F
            E[j] = G
            for k in xrange(0, j + 1):
                A[k, j] -= F * E[k] + G * A[k, i]
        D[i] = H
    for i in xrange(1, n):
        E[i - 1] = E[i]
    E[n - 1] = 0
    if calc_ev:
        D[0] = 0
        for i in xrange(0, n):
            if D[i] != 0:
                for j in xrange(0, i):
                    G = 0
                    for k in xrange(0, i):
                        G += A[i, k] * A[k, j]
                    for k in xrange(0, i):
                        A[k, j] -= G * A[k, i]
            D[i] = A[i, i]
            A[i, i] = 1
            for j in xrange(0, i):
                A[j, i] = A[i, j] = 0
    else:
        for i in xrange(0, n):
            D[i] = A[i, i]

def c_he_tridiag_0(ctx, A, D, E, T):
    n = A.rows
    T[n - 1] = 1
    for i in xrange(n - 1, 0, -1):
        scale = 0
        for k in xrange(0, i):
            scale += abs(ctx.re(A[k, i])) + abs(ctx.im(A[k, i]))
        scale_inv = 0
        if scale != 0:
            scale_inv = 1 / scale
        if scale == 0 or ctx.isinf(scale_inv):
            E[i] = 0
            D[i] = 0
            T[i - 1] = 1
            continue
        if i == 1:
            F = A[i - 1, i]
            f = abs(F)
            E[i] = f
            D[i] = 0
            if f != 0:
                T[i - 1] = T[i] * F / f
            else:
                T[i - 1] = T[i]
            continue
        H = 0
        for k in xrange(0, i):
            A[k, i] *= scale_inv
            rr = ctx.re(A[k, i])
            ii = ctx.im(A[k, i])
            H += rr * rr + ii * ii
        F = A[i - 1, i]
        f = abs(F)
        G = ctx.sqrt(H)
        H += G * f
        E[i] = scale * G
        if f != 0:
            F = F / f
            TZ = -T[i] * F
            G *= F
        else:
            TZ = -T[i]
        A[i - 1, i] += G
        F = 0
        for j in xrange(0, i):
            A[i, j] = A[j, i] / H
            G = 0
            for k in xrange(0, j + 1):
                G += ctx.conj(A[k, j]) * A[k, i]
            for k in xrange(j + 1, i):
                G += A[j, k] * A[k, i]
            T[j] = G / H
            F += ctx.conj(T[j]) * A[j, i]
        HH = F / (2 * H)
        for j in xrange(0, i):
            F = A[j, i]
            G = T[j] - HH * F
            T[j] = G
            for k in xrange(0, j + 1):
                A[k, j] -= ctx.conj(F) * T[k] + ctx.conj(G) * A[k, i]
        T[i - 1] = TZ
        D[i] = H
    for i in xrange(1, n):
        E[i - 1] = E[i]
    E[n - 1] = 0
    D[0] = 0
    for i in xrange(0, n):
        zw = D[i]
        D[i] = ctx.re(A[i, i])
        A[i, i] = zw

def c_he_tridiag_1(ctx, A, T):
    n = A.rows
    for i in xrange(0, n):
        if A[i, i] != 0:
            for j in xrange(0, i):
                G = 0
                for k in xrange(0, i):
                    G += ctx.conj(A[i, k]) * A[k, j]
                for k in xrange(0, i):
                    A[k, j] -= G * A[k, i]
        A[i, i] = 1
        for j in xrange(0, i):
            A[j, i] = A[i, j] = 0
    for i in xrange(0, n):
        for k in xrange(0, n):
            A[i, k] *= T[k]

def c_he_tridiag_2(ctx, A, T, B):
    n = A.rows
    for i in xrange(0, n):
        for k in xrange(0, n):
            B[k, i] *= T[k]
    for i in xrange(0, n):
        if A[i, i] != 0:
            for j in xrange(0, n):
                G = 0
                for k in xrange(0, i):
                    G += ctx.conj(A[i, k]) * B[k, j]
                for k in xrange(0, i):
                    B[k, j] -= G * A[k, i]

def tridiag_eigen(ctx, d, e, z=False):
    n = len(d)
    e[n - 1] = 0
    iterlim = 2 * ctx.dps
    for l in xrange(n):
        j = 0
        while 1:
            m = l
            while 1:
                if m + 1 == n:
                    break
                if abs(e[m]) <= ctx.eps * (abs(d[m]) + abs(d[m + 1])):
                    break
                m = m + 1
            if m == l:
                break
            if j >= iterlim:
                raise RuntimeError('tridiag_eigen: no convergence to an eigenvalue after %d iterations' % iterlim)
            j += 1
            p = d[l]
            g = (d[l + 1] - p) / (2 * e[l])
            r = ctx.hypot(g, 1)
            if g < 0:
                s = g - r
            else:
                s = g + r
            g = d[m] - p + e[l] / s
            s, c, p = (1, 1, 0)
            for i in xrange(m - 1, l - 1, -1):
                f = s * e[i]
                b = c * e[i]
                if abs(f) > abs(g):
                    c = g / f
                    r = ctx.hypot(c, 1)
                    e[i + 1] = f * r
                    s = 1 / r
                    c = c * s
                else:
                    s = f / g
                    r = ctx.hypot(s, 1)
                    e[i + 1] = g * r
                    c = 1 / r
                    s = s * c
                g = d[i + 1] - p
                r = (d[i] - g) * s + 2 * c * b
                p = s * r
                d[i + 1] = g + p
                g = c * r - b
                if not isinstance(z, bool):
                    for w in xrange(z.rows):
                        f = z[w, i + 1]
                        z[w, i + 1] = s * z[w, i] + c * f
                        z[w, i] = c * z[w, i] - s * f
            d[l] = d[l] - p
            e[l] = g
            e[m] = 0
    for ii in xrange(1, n):
        i = ii - 1
        k = i
        p = d[i]
        for j in xrange(ii, n):
            if d[j] >= p:
                continue
            k = j
            p = d[k]
        if k == i:
            continue
        d[k] = d[i]
        d[i] = p
        if not isinstance(z, bool):
            for w in xrange(z.rows):
                p = z[w, i]
                z[w, i] = z[w, k]
                z[w, k] = p

@defun
def eigsy(ctx, A, eigvals_only=False, overwrite_a=False):
    if not overwrite_a:
        A = A.copy()
    d = ctx.zeros(A.rows, 1)
    e = ctx.zeros(A.rows, 1)
    if eigvals_only:
        r_sy_tridiag(ctx, A, d, e, calc_ev=False)
        tridiag_eigen(ctx, d, e, False)
        return d
    else:
        r_sy_tridiag(ctx, A, d, e, calc_ev=True)
        tridiag_eigen(ctx, d, e, A)
        return (d, A)

@defun
def eighe(ctx, A, eigvals_only=False, overwrite_a=False):
    if not overwrite_a:
        A = A.copy()
    d = ctx.zeros(A.rows, 1)
    e = ctx.zeros(A.rows, 1)
    t = ctx.zeros(A.rows, 1)
    if eigvals_only:
        c_he_tridiag_0(ctx, A, d, e, t)
        tridiag_eigen(ctx, d, e, False)
        return d
    else:
        c_he_tridiag_0(ctx, A, d, e, t)
        B = ctx.eye(A.rows)
        tridiag_eigen(ctx, d, e, B)
        c_he_tridiag_2(ctx, A, t, B)
        return (d, B)

@defun
def eigh(ctx, A, eigvals_only=False, overwrite_a=False):
    iscomplex = any((type(x) is ctx.mpc for x in A))
    if iscomplex:
        return ctx.eighe(A, eigvals_only=eigvals_only, overwrite_a=overwrite_a)
    else:
        return ctx.eigsy(A, eigvals_only=eigvals_only, overwrite_a=overwrite_a)

@defun
def gauss_quadrature(ctx, n, qtype='legendre', alpha=0, beta=0):
    d = ctx.zeros(n, 1)
    e = ctx.zeros(n, 1)
    z = ctx.zeros(1, n)
    z[0, 0] = 1
    if qtype == 'legendre':
        w = 2
        for i in xrange(n):
            j = i + 1
            e[i] = ctx.sqrt(j * j / (4 * j * j - ctx.mpf(1)))
    elif qtype == 'legendre01':
        w = 1
        for i in xrange(n):
            d[i] = 1 / ctx.mpf(2)
            j = i + 1
            e[i] = ctx.sqrt(j * j / (16 * j * j - ctx.mpf(4)))
    elif qtype == 'hermite':
        w = ctx.sqrt(ctx.pi)
        for i in xrange(n):
            j = i + 1
            e[i] = ctx.sqrt(j / ctx.mpf(2))
    elif qtype == 'laguerre':
        w = 1
        for i in xrange(n):
            j = i + 1
            d[i] = 2 * j - 1
            e[i] = j
    elif qtype == 'chebyshev1':
        w = ctx.pi
        for i in xrange(n):
            e[i] = 1 / ctx.mpf(2)
        e[0] = ctx.sqrt(1 / ctx.mpf(2))
    elif qtype == 'chebyshev2':
        w = ctx.pi / 2
        for i in xrange(n):
            e[i] = 1 / ctx.mpf(2)
    elif qtype == 'glaguerre':
        w = ctx.gamma(1 + alpha)
        for i in xrange(n):
            j = i + 1
            d[i] = 2 * j - 1 + alpha
            e[i] = ctx.sqrt(j * (j + alpha))
    elif qtype == 'jacobi':
        alpha = ctx.mpf(alpha)
        beta = ctx.mpf(beta)
        ab = alpha + beta
        abi = ab + 2
        w = 2 ** (ab + 1) * ctx.gamma(alpha + 1) * ctx.gamma(beta + 1) / ctx.gamma(abi)
        d[0] = (beta - alpha) / abi
        e[0] = ctx.sqrt(4 * (1 + alpha) * (1 + beta) / ((abi + 1) * (abi * abi)))
        a2b2 = beta * beta - alpha * alpha
        for i in xrange(1, n):
            j = i + 1
            abi = 2 * j + ab
            d[i] = a2b2 / ((abi - 2) * abi)
            e[i] = ctx.sqrt(4 * j * (j + alpha) * (j + beta) * (j + ab) / ((abi * abi - 1) * abi * abi))
