@defun
def svd_r(ctx, A, full_matrices=False, compute_uv=True, overwrite_a=False):
    m, n = (A.rows, A.cols)
    if not compute_uv:
        if not overwrite_a:
            A = A.copy()
        S = svd_r_raw(ctx, A, V=False, calc_u=False)
        S = S[:min(m, n)]
        return S
    if full_matrices and n < m:
        V = ctx.zeros(m, m)
        A0 = ctx.zeros(m, m)
        A0[:, :n] = A
        S = svd_r_raw(ctx, A0, V, calc_u=True)
        S = S[:n]
        V = V[:n, :n]
        return (A0, S, V)
    else:
        if not overwrite_a:
            A = A.copy()
        V = ctx.zeros(n, n)
        S = svd_r_raw(ctx, A, V, calc_u=True)
        if n > m:
            if full_matrices == False:
                V = V[:m, :]
            S = S[:m]
            A = A[:, :m]
        return (A, S, V)

