from copy import copy
from ..libmp.backend import xrange

class LinearAlgebraMethods(object):

    def LU_decomp(ctx, A, overwrite=False, use_cache=True):
        if not A.rows == A.cols:
            raise ValueError('need n*n matrix')
        if use_cache and isinstance(A, ctx.matrix) and A._LU:
            return A._LU
        if not overwrite:
            orig = A
            A = A.copy()
        tol = ctx.absmin(ctx.mnorm(A, 1) * ctx.eps)
        n = A.rows
        p = [None] * (n - 1)
        for j in xrange(n - 1):
            biggest = 0
            for k in xrange(j, n):
                s = ctx.fsum([ctx.absmin(A[k, l]) for l in xrange(j, n)])
                if ctx.absmin(s) <= tol:
                    raise ZeroDivisionError('matrix is numerically singular')
                current = 1 / s * ctx.absmin(A[k, j])
                if current > biggest:
                    biggest = current
                    p[j] = k
            ctx.swap_row(A, j, p[j])
            if ctx.absmin(A[j, j]) <= tol:
                raise ZeroDivisionError('matrix is numerically singular')
            for i in xrange(j + 1, n):
                A[i, j] /= A[j, j]
                for k in xrange(j + 1, n):
                    A[i, k] -= A[i, j] * A[j, k]
        if ctx.absmin(A[n - 1, n - 1]) <= tol:
            raise ZeroDivisionError('matrix is numerically singular')
        if not overwrite and isinstance(orig, ctx.matrix):
            orig._LU = (A, p)
        return (A, p)

    def L_solve(ctx, L, b, p=None):
        if L.rows != L.cols:
            raise RuntimeError('need n*n matrix')
        n = L.rows
        if len(b) != n:
            raise ValueError('Value should be equal to n')
        b = copy(b)
        if p:
            for k in xrange(0, len(p)):
                ctx.swap_row(b, k, p[k])
        for i in xrange(1, n):
            for j in xrange(i):
                b[i] -= L[i, j] * b[j]
        return b

    def U_solve(ctx, U, y):
        if U.rows != U.cols:
            raise RuntimeError('need n*n matrix')
        n = U.rows
        if len(y) != n:
            raise ValueError('Value should be equal to n')
        x = copy(y)
        for i in xrange(n - 1, -1, -1):
            for j in xrange(i + 1, n):
                x[i] -= U[i, j] * x[j]
            x[i] /= U[i, i]
        return x

    def lu_solve(ctx, A, b, **kwargs):
        prec = ctx.prec
        try:
            ctx.prec += 10
            A, b = (ctx.matrix(A, **kwargs).copy(), ctx.matrix(b, **kwargs).copy())
            if A.rows < A.cols:
                raise ValueError('cannot solve underdetermined system')
            if A.rows > A.cols:
                AH = A.H
                A = AH * A
                b = AH * b
                if kwargs.get('real', False) or not sum((type(i) is ctx.mpc for i in A)):
                    x = ctx.cholesky_solve(A, b)
                else:
                    x = ctx.lu_solve(A, b)
            else:
                A, p = ctx.LU_decomp(A)
                b = ctx.L_solve(A, b, p)
                x = ctx.U_solve(A, b)
        finally:
            ctx.prec = prec
        return x

    def improve_solution(ctx, A, x, b, maxsteps=1):
        if A.rows != A.cols:
            raise RuntimeError('need n*n matrix')
        for _ in xrange(maxsteps):
            r = ctx.residual(A, x, b)
            if ctx.norm(r, 2) < 10 * ctx.eps:
                break
            dx = ctx.lu_solve(A, -r)
            x += dx
        return x

    def lu(ctx, A):
        A, p = ctx.LU_decomp(A)
        n = A.rows
        L = ctx.matrix(n)
        U = ctx.matrix(n)
        for i in xrange(n):
            for j in xrange(n):
                if i > j:
                    L[i, j] = A[i, j]
                elif i == j:
                    L[i, j] = 1
                    U[i, j] = A[i, j]
                else:
                    U[i, j] = A[i, j]
        P = ctx.eye(n)
        for k in xrange(len(p)):
            ctx.swap_row(P, k, p[k])
        return (P, L, U)

    def unitvector(ctx, n, i):
        assert 0 < i <= n, 'this unit vector does not exist'
        return [ctx.zero] * (i - 1) + [ctx.one] + [ctx.zero] * (n - i)

    def inverse(ctx, A, **kwargs):
        prec = ctx.prec
        try:
            ctx.prec += 10
            A = ctx.matrix(A, **kwargs).copy()
            n = A.rows
            A, p = ctx.LU_decomp(A)
            cols = []
            for i in xrange(1, n + 1):
                e = ctx.unitvector(n, i)
                y = ctx.L_solve(A, e, p)
                cols.append(ctx.U_solve(A, y))
            inv = []
            for i in xrange(n):
                row = []
                for j in xrange(n):
                    row.append(cols[j][i])
                inv.append(row)
            result = ctx.matrix(inv, **kwargs)
        finally:
            ctx.prec = prec
        return result

    def householder(ctx, A):
        if not isinstance(A, ctx.matrix):
            raise TypeError('A should be a type of ctx.matrix')
        m = A.rows
        n = A.cols
        if m < n - 1:
            raise RuntimeError('Columns should not be less than rows')
        p = []
        for j in xrange(0, n - 1):
            s = ctx.fsum((abs(A[i, j]) ** 2 for i in xrange(j, m)))
            if not abs(s) > ctx.eps:
                raise ValueError('matrix is numerically singular')
            p.append(-ctx.sign(ctx.re(A[j, j])) * ctx.sqrt(s))
            kappa = ctx.one / (s - p[j] * A[j, j])
            A[j, j] -= p[j]
            for k in xrange(j + 1, n):
                y = ctx.fsum((ctx.conj(A[i, j]) * A[i, k] for i in xrange(j, m))) * kappa
                for i in xrange(j, m):
                    A[i, k] -= A[i, j] * y
        x = [A[i, n - 1] for i in xrange(n - 1)]
        for i in xrange(n - 2, -1, -1):
            x[i] -= ctx.fsum((A[i, j] * x[j] for j in xrange(i + 1, n - 1)))
            x[i] /= p[i]
        if not m == n - 1:
            r = [A[m - 1 - i, n - 1] for i in xrange(m - n + 1)]
        else:
            r = [0] * m
        return (A, p, x, r)

    def residual(ctx, A, x, b, **kwargs):
        oldprec = ctx.prec
        try:
            ctx.prec *= 2
            A, x, b = (ctx.matrix(A, **kwargs), ctx.matrix(x, **kwargs), ctx.matrix(b, **kwargs))
            return A * x - b
        finally:
            ctx.prec = oldprec

    def qr_solve(ctx, A, b, norm=None, **kwargs):
        if norm is None:
            norm = ctx.norm
        prec = ctx.prec
        try:
            ctx.prec += 10
            A, b = (ctx.matrix(A, **kwargs).copy(), ctx.matrix(b, **kwargs).copy())
            if A.rows < A.cols:
                raise ValueError('cannot solve underdetermined system')
            H, p, x, r = ctx.householder(ctx.extend(A, b))
            res = ctx.norm(r)
            if res == 0:
                res = ctx.norm(ctx.residual(A, x, b))
            return (ctx.matrix(x, **kwargs), res)
        finally:
            ctx.prec = prec

    def cholesky(ctx, A, tol=None):
        if not isinstance(A, ctx.matrix):
            raise RuntimeError('A should be a type of ctx.matrix')
        if not A.rows == A.cols:
            raise ValueError('need n*n matrix')
        if tol is None:
            tol = +ctx.eps
        n = A.rows
        L = ctx.matrix(n)
        for j in xrange(n):
            c = ctx.re(A[j, j])
            if abs(c - A[j, j]) > tol:
                raise ValueError('matrix is not Hermitian')
            s = c - ctx.fsum((L[j, k] for k in xrange(j)), absolute=True, squared=True)
            if s < tol:
                raise ValueError('matrix is not positive-definite')
            L[j, j] = ctx.sqrt(s)
            for i in xrange(j, n):
                it1 = (L[i, k] for k in xrange(j))
                it2 = (L[j, k] for k in xrange(j))
                t = ctx.fdot(it1, it2, conjugate=True)
                L[i, j] = (A[i, j] - t) / L[j, j]
        return L

    def cholesky_solve(ctx, A, b, **kwargs):
        prec = ctx.prec
        try:
            ctx.prec += 10
            A, b = (ctx.matrix(A, **kwargs).copy(), ctx.matrix(b, **kwargs).copy())
            if A.rows != A.cols:
                raise ValueError('can only solve determined system')
            L = ctx.cholesky(A)
            n = L.rows
            if len(b) != n:
                raise ValueError('Value should be equal to n')
            for i in xrange(n):
                b[i] -= ctx.fsum((L[i, j] * b[j] for j in xrange(i)))
                b[i] /= L[i, i]
            x = ctx.U_solve(L.T, b)
            return x
        finally:
            ctx.prec = prec

    def det(ctx, A):
        prec = ctx.prec
        try:
            A = ctx.matrix(A).copy()
            try:
                R, p = ctx.LU_decomp(A)
            except ZeroDivisionError:
                return 0
            z = 1
            for i, e in enumerate(p):
                if i != e:
                    z *= -1
            for i in xrange(A.rows):
                z *= R[i, i]
            return z
        finally:
            ctx.prec = prec

    def cond(ctx, A, norm=None):
        if norm is None:
            norm = lambda x: ctx.mnorm(x, 1)
        return norm(A) * norm(ctx.inverse(A))

    def lu_solve_mat(ctx, a, b):
        r = ctx.matrix(a.rows, b.cols)
        for i in range(b.cols):
            c = ctx.lu_solve(a, b.column(i))
            for j in range(len(c)):
                r[j, i] = c[j]
        return r

    def qr(ctx, A, mode='full', edps=10):
        assert isinstance(A, ctx.matrix)
        m = A.rows
        n = A.cols
        assert n >= 0
        assert m >= n
        assert edps >= 0
        cmplx = any((type(x) is ctx.mpc for x in A))
        with ctx.extradps(edps):
            tau = ctx.matrix(n, 1)
            A = A.copy()
            if cmplx:
                one = ctx.mpc('1.0', '0.0')
                zero = ctx.mpc('0.0', '0.0')
                rzero = ctx.mpf('0.0')
                for j in xrange(0, n):
                    alpha = A[j, j]
                    alphr = ctx.re(alpha)
                    alphi = ctx.im(alpha)
                    if m - j >= 2:
                        xnorm = ctx.fsum((A[i, j] * ctx.conj(A[i, j]) for i in xrange(j + 1, m)))
                        xnorm = ctx.re(ctx.sqrt(xnorm))
                    else:
                        xnorm = rzero
                    if xnorm == rzero and alphi == rzero:
                        tau[j] = zero
                        continue
                    if alphr < rzero:
                        beta = ctx.sqrt(alphr ** 2 + alphi ** 2 + xnorm ** 2)
                    else:
                        beta = -ctx.sqrt(alphr ** 2 + alphi ** 2 + xnorm ** 2)
                    tau[j] = ctx.mpc((beta - alphr) / beta, -alphi / beta)
                    t = -ctx.conj(tau[j])
                    za = one / (alpha - beta)
                    for i in xrange(j + 1, m):
                        A[i, j] *= za
                    A[j, j] = one
                    for k in xrange(j + 1, n):
                        y = ctx.fsum((A[i, j] * ctx.conj(A[i, k]) for i in xrange(j, m)))
                        temp = t * ctx.conj(y)
                        for i in xrange(j, m):
                            A[i, k] += A[i, j] * temp
                    A[j, j] = ctx.mpc(beta, '0.0')
            else:
                one = ctx.mpf('1.0')
                zero = ctx.mpf('0.0')
                for j in xrange(0, n):
                    alpha = A[j, j]
                    if m - j > 2:
                        xnorm = ctx.fsum((A[i, j] ** 2 for i in xrange(j + 1, m)))
                        xnorm = ctx.sqrt(xnorm)
                    elif m - j == 2:
                        xnorm = abs(A[m - 1, j])
                    else:
                        xnorm = zero
                    if xnorm == zero:
                        tau[j] = zero
                        continue
                    if alpha < zero:
                        beta = ctx.sqrt(alpha ** 2 + xnorm ** 2)
                    else:
                        beta = -ctx.sqrt(alpha ** 2 + xnorm ** 2)
                    tau[j] = (beta - alpha) / beta
                    t = -tau[j]
                    da = one / (alpha - beta)
                    for i in xrange(j + 1, m):
                        A[i, j] *= da
                    A[j, j] = one
                    for k in xrange(j + 1, n):
                        y = ctx.fsum((A[i, j] * A[i, k] for i in xrange(j, m)))
                        temp = t * y
                        for i in xrange(j, m):
                            A[i, k] += A[i, j] * temp
                    A[j, j] = beta
            if mode == 'raw' or mode == 'RAW':
                return (A, tau)
            R = A.copy()
            for j in xrange(0, n):
                for i in xrange(j + 1, m):
                    R[i, j] = zero
            p = m
            if mode == 'skinny' or mode == 'SKINNY':
                p = n
            A.cols += p - n
            for j in xrange(0, p):
                A[j, j] = one
                for i in xrange(0, j):
                    A[i, j] = zero
            for j in xrange(n - 1, -1, -1):
                t = -tau[j]
                A[j, j] += t
                for k in xrange(j + 1, p):
                    if cmplx:
                        y = ctx.fsum((A[i, j] * ctx.conj(A[i, k]) for i in xrange(j + 1, m)))
                        temp = t * ctx.conj(y)
                    else:
                        y = ctx.fsum((A[i, j] * A[i, k] for i in xrange(j + 1, m)))
                        temp = t * y
                    A[j, k] = temp
                    for i in xrange(j + 1, m):
                        A[i, k] += A[i, j] * temp
                for i in xrange(j + 1, m):
                    A[i, j] *= t
            return (A, R[0:p, 0:n])

