from ..libmp.backend import xrange
import warnings
rowsep = '\n'
colsep = '  '

class _matrix(object):

    def __init__(self, *args, **kwargs):
        self.__data = {}
        self._LU = None
        if 'force_type' in kwargs:
            warnings.warn('The force_type argument was removed, it did not work properly anyway. If you want to force floating-point or interval computations, use the respective methods from `fp` or `mp` instead, e.g., `fp.matrix()` or `iv.matrix()`. If you want to truncate values to integer, use .apply(int) instead.')
        if isinstance(args[0], (list, tuple)):
            if isinstance(args[0][0], (list, tuple)):
                A = args[0]
                self.__rows = len(A)
                self.__cols = len(A[0])
                for i, row in enumerate(A):
                    for j, a in enumerate(row):
                        self[i, j] = a
            else:
                v = args[0]
                self.__rows = len(v)
                self.__cols = 1
                for i, e in enumerate(v):
                    self[i, 0] = e
        elif isinstance(args[0], int):
            if len(args) == 1:
                self.__rows = self.__cols = args[0]
            else:
                if not isinstance(args[1], int):
                    raise TypeError('expected int')
                self.__rows = args[0]
                self.__cols = args[1]
        elif isinstance(args[0], _matrix):
            A = args[0]
            self.__rows = A._matrix__rows
            self.__cols = A._matrix__cols
            for i in xrange(A.__rows):
                for j in xrange(A.__cols):
                    self[i, j] = A[i, j]
        elif hasattr(args[0], 'tolist'):
            A = self.ctx.matrix(args[0].tolist())
            self.__data = A._matrix__data
            self.__rows = A._matrix__rows
            self.__cols = A._matrix__cols
        else:
            raise TypeError('could not interpret given arguments')

    def apply(self, f):
        new = self.ctx.matrix(self.__rows, self.__cols)
        for i in xrange(self.__rows):
            for j in xrange(self.__cols):
                new[i, j] = f(self[i, j])
        return new

    def __nstr__(self, n=None, **kwargs):
        res = []
        maxlen = [0] * self.cols
        for i in range(self.rows):
            res.append([])
            for j in range(self.cols):
                if n:
                    string = self.ctx.nstr(self[i, j], n, **kwargs)
                else:
                    string = str(self[i, j])
                res[-1].append(string)
                maxlen[j] = max(len(string), maxlen[j])
        for i, row in enumerate(res):
            for j, elem in enumerate(row):
                row[j] = elem.rjust(maxlen[j])
            res[i] = '[' + colsep.join(row) + ']'
        return rowsep.join(res)

    def __str__(self):
        return self.__nstr__()

    def _toliststr(self, avoid_type=False):
        typ = self.ctx.mpf
        s = '['
        for i in xrange(self.__rows):
            s += '['
            for j in xrange(self.__cols):
                if not avoid_type or not isinstance(self[i, j], typ):
                    a = repr(self[i, j])
                else:
                    a = "'" + str(self[i, j]) + "'"
                s += a + ', '
            s = s[:-2]
            s += '],\n '
        s = s[:-3]
        s += ']'
        return s

    def tolist(self):
        return [[self[i, j] for j in range(self.__cols)] for i in range(self.__rows)]

    def __repr__(self):
        if self.ctx.pretty:
            return self.__str__()
        s = 'matrix(\n'
        s += self._toliststr(avoid_type=True) + ')'
        return s

    def __get_element(self, key):
        if key in self.__data:
            return self.__data[key]
        else:
            return self.ctx.zero

    def __set_element(self, key, value):
        if value:
            self.__data[key] = value
        elif key in self.__data:
            del self.__data[key]

    def __getitem__(self, key):
        if isinstance(key, int) or isinstance(key, slice):
            if self.__rows == 1:
                key = (0, key)
            elif self.__cols == 1:
                key = (key, 0)
            else:
                raise IndexError('insufficient indices for matrix')
        if isinstance(key[0], slice) or isinstance(key[1], slice):
            if isinstance(key[0], slice):
                if (key[0].start is None or key[0].start >= 0) and (key[0].stop is None or key[0].stop <= self.__rows + 1):
                    rows = xrange(*key[0].indices(self.__rows))
                else:
                    raise IndexError('Row index out of bounds')
            else:
                rows = [key[0]]
            if isinstance(key[1], slice):
                if (key[1].start is None or key[1].start >= 0) and (key[1].stop is None or key[1].stop <= self.__cols + 1):
                    columns = xrange(*key[1].indices(self.__cols))
                else:
                    raise IndexError('Column index out of bounds')
            else:
                columns = [key[1]]
            m = self.ctx.matrix(len(rows), len(columns))
            for i, x in enumerate(rows):
                for j, y in enumerate(columns):
                    m.__set_element((i, j), self.__get_element((x, y)))
