    def eye(ctx, n, **kwargs):
        A = ctx.matrix(n, **kwargs)
        for i in xrange(n):
            A[i, i] = 1
        return A

    def diag(ctx, diagonal, **kwargs):
        A = ctx.matrix(len(diagonal), **kwargs)
        for i in xrange(len(diagonal)):
            A[i, i] = diagonal[i]
        return A

    def zeros(ctx, *args, **kwargs):
