        if p == 1:
            return max((ctx.fsum((A[i, j] for i in xrange(m)), absolute=1) for j in xrange(n)))
        elif p == ctx.inf:
            return max((ctx.fsum((A[i, j] for j in xrange(n)), absolute=1) for i in xrange(m)))
