class AskHandler:

    def __new__(cls, *args, **kwargs):
        sympy_deprecation_warning('\n            The AskHandler system is deprecated. The AskHandler class should\n            be replaced with the multipledispatch handler of Predicate\n            ', deprecated_since_version='1.8', active_deprecations_target='deprecated-askhandler')
        return super().__new__(cls, *args, **kwargs)

class CommonHandler(AskHandler):

    @staticmethod
    def AlwaysTrue(expr, assumptions):
        return True

    @staticmethod
    def AlwaysFalse(expr, assumptions):
        return False

    @staticmethod
    def AlwaysNone(expr, assumptions):
        return None
    NaN = AlwaysFalse

@CommutativePredicate.register(Symbol)
def _(expr, assumptions):
    assumps = conjuncts(assumptions)
    if expr.is_commutative is not None:
        return expr.is_commutative and (not ~Q.commutative(expr) in assumps)
    if Q.commutative(expr) in assumps:
        return True
    elif ~Q.commutative(expr) in assumps:
        return False
    return True

@CommutativePredicate.register(Basic)
def _(expr, assumptions):
    for arg in expr.args:
        if not ask(Q.commutative(arg), assumptions):
            return False
    return True

@CommutativePredicate.register(Number)
def _(expr, assumptions):
    return True

@CommutativePredicate.register(NaN)
def _(expr, assumptions):
    return True

@IsTruePredicate.register(bool)
