    return [Permutation([[i - 1 for i in xi] for xi in x], size=48) for x in a]

def rubik(n):
    if n < 2:
        raise ValueError('dimension of cube must be > 1')

    def getr(f, i):
        return faces[f].col(n - i)

    def getl(f, i):
        return faces[f].col(i - 1)

    def getu(f, i):
        return faces[f].row(i - 1)

    def getd(f, i):
