            t = faces[U]
            cw(L)
            faces[U] = faces[L]
            cw(D)
            faces[L] = faces[D]
            cw(R)
            faces[D] = faces[R]
            faces[R] = t

    def FCCW():
        FCW(3)

    def UCW(r=1):
        for _ in range(r):
            cw(U)
            ccw(D)
            t = faces[F]
            faces[F] = faces[R]
            faces[R] = faces[B]
            faces[B] = faces[L]
            faces[L] = t

    def UCCW():
        UCW(3)
    U, F, R, B, L, D = names = symbols('U, F, R, B, L, D')
    faces = {}
    count = 0
    for fi in range(6):
        f = []
        for a in range(n ** 2):
            f.append(count)
            count += 1
        faces[names[fi]] = Matrix(n, n, f)

    def perm(show=0):
        p = []
        for f in names:
            p.extend(faces[f])
        if show:
            return p
        g.append(Permutation(p))
    g = []
    I = list(range(6 * n ** 2))
    for i in range(n - 1):
        fcw(i)
        perm()
        fccw(i)
    assert perm(1) == I
    UCW()
    for i in range(n - 1):
        fcw(i)
