        self._degree = self._generators[0].size
        self._base = []
        self._strong_gens = []
        self._strong_gens_slp = []
        self._basic_orbits = []
        self._transversals = []
        self._transversal_slp = []
        self._random_gens = []
        self._fp_presentation = None

    def __getitem__(self, i):
