def _merge(arr, temp, left, mid, right):
    i = k = left
    j = mid
    inv_count = 0
    while i < mid and j <= right:
        if arr[i] < arr[j]:
            temp[k] = arr[i]
            k += 1
            i += 1
        else:
            temp[k] = arr[j]
            k += 1
            j += 1
            inv_count += mid - i
    while i < mid:
        temp[k] = arr[i]
        k += 1
        i += 1
    if j <= right:
        k += right - j + 1
        j += right - j + 1
        arr[left:k + 1] = temp[left:k + 1]
    else:
        arr[left:right + 1] = temp[left:right + 1]
    return inv_count
Perm = Permutation
_af_new = Perm._af_new

class AppliedPermutation(Expr):

    def __new__(cls, perm, x, evaluate=None):
        if evaluate is None:
            evaluate = global_parameters.evaluate
        perm = _sympify(perm)
        x = _sympify(x)
        if not isinstance(perm, Permutation):
            raise ValueError('{} must be a Permutation instance.'.format(perm))
        if evaluate:
            if x.is_Integer:
                return perm.apply(x)
        obj = super().__new__(cls, perm, x)
        return obj

@dispatch(Permutation, Permutation)
def _eval_is_eq(lhs, rhs):
    if lhs._size != rhs._size:
        return None
    return lhs._array_form == rhs._array_form

