                b, e = o.as_base_exp()
                if b.is_Number and (e.is_Integer or (e.is_Rational and e.is_negative)):
                    seq.append(b ** e)
                    continue
                c, s = (S.One, o)
            else:
                c = S.One
                s = o
            if s in terms:
                terms[s] += c
                if terms[s] is S.NaN and (not extra):
                    return ([S.NaN], [], None)
            else:
                terms[s] = c
        newseq = []
        noncommutative = False
        for s, c in terms.items():
            if c.is_zero:
                continue
            elif c is S.One:
                newseq.append(s)
            elif s.is_Mul:
                cs = s._new_rawargs(*(c,) + s.args)
                newseq.append(cs)
            elif s.is_Add:
                newseq.append(Mul(c, s, evaluate=False))
