                old_set = set(args_old)
                if old_set < self_set:
                    ret_set = self_set - old_set
                    return self.func(new, coeff_self, -coeff_old, *[s._subs(old, new) for s in ret_set])
                args_old = self.func.make_args(-terms_old)
                old_set = set(args_old)
