INF = float(mpmath_inf)
MINUS_INF = float(-mpmath_inf)
DEFAULT_MAXPREC = 333

class PrecisionExhausted(ArithmeticError):
    pass
'\nAn mpf value tuple is a tuple of integers (sign, man, exp, bc)\nrepresenting a floating-point number: [1, -1][sign]*man*2**exp where\nsign is 0 or 1 and bc should correspond to the number of bits used to\nrepresent the mantissa (man) in binary notation, e.g.\n'
MPF_TUP = tTuple[int, int, int, int]
'\nExplanation\n===========\n\n>>> from sympy.core.evalf import bitcount\n>>> sign, man, exp, bc = 0, 5, 1, 3\n>>> n = [1, -1][sign]*man*2**exp\n>>> n, bitcount(man)\n(10, 3)\n\nA temporary result is a tuple (re, im, re_acc, im_acc) where\nre and im are nonzero mpf value tuples representing approximate\nnumbers, or None to denote exact zeros.\n\nre_acc, im_acc are integers denoting log2(e) where e is the estimated\nrelative accuracy of the respective complex part, but may be anything\nif the corresponding complex part is None.\n\n'
TMP_RES = Any
OPT_DICT = tDict[str, Any]

def fastlog(x: Optional[MPF_TUP]) -> tUnion[int, Any]:
    if not x or x == fzero:
        return MINUS_INF
    return x[2] + x[3]

def pure_complex(v: 'Expr', or_real=False) -> tuple['Number', 'Number'] | None:
    h, t = v.as_coeff_Add()
    if t:
        c, i = t.as_coeff_Mul()
        if i is S.ImaginaryUnit:
            return (h, c)
    elif or_real:
        return (h, S.Zero)
    return None
SCALED_ZERO_TUP = tTuple[List[int], int, int, int]

@overload
def scaled_zero(mag: SCALED_ZERO_TUP, sign=1) -> MPF_TUP:
    ...

@overload
def scaled_zero(mag: int, sign=1) -> tTuple[SCALED_ZERO_TUP, int]:
    ...

def scaled_zero(mag: tUnion[SCALED_ZERO_TUP, int], sign=1) -> tUnion[MPF_TUP, tTuple[SCALED_ZERO_TUP, int]]:
    if isinstance(mag, tuple) and len(mag) == 4 and iszero(mag, scaled=True):
        return (mag[0][0],) + mag[1:]
    elif isinstance(mag, SYMPY_INTS):
        if sign not in [-1, 1]:
            raise ValueError('sign must be +/-1')
        rv, p = (mpf_shift(fone, mag), -1)
        s = 0 if sign == 1 else 1
        rv = ([s],) + rv[1:]
        return (rv, p)
    else:
        raise ValueError('scaled zero expects int or scaled_zero tuple.')

def iszero(mpf: tUnion[MPF_TUP, SCALED_ZERO_TUP, None], scaled=False) -> Optional[bool]:
    if not scaled:
        return not mpf or (not mpf[1] and (not mpf[-1]))
    return mpf and isinstance(mpf[0], list) and (mpf[1] == mpf[-1] == 1)

def complex_accuracy(result: TMP_RES) -> tUnion[int, Any]:
    if result is S.ComplexInfinity:
        return INF
    re, im, re_acc, im_acc = result
    if not im:
        if not re:
            return INF
        return re_acc
    if not re:
        return im_acc
    re_size = fastlog(re)
    im_size = fastlog(im)
    absolute_error = max(re_size - re_acc, im_size - im_acc)
    relative_error = absolute_error - max(re_size, im_size)
    return -relative_error

def get_abs(expr: 'Expr', prec: int, options: OPT_DICT) -> TMP_RES:
    result = evalf(expr, prec + 2, options)
    if result is S.ComplexInfinity:
        return (finf, None, prec, None)
    re, im, re_acc, im_acc = result
    if not re:
        re, re_acc, im, im_acc = (im, im_acc, re, re_acc)
    if im:
        if expr.is_number:
            abs_expr, _, acc, _ = evalf(abs(N(expr, prec + 2)), prec + 2, options)
            return (abs_expr, None, acc, None)
        else:
            if 'subs' in options:
                return (libmp.mpc_abs((re, im), prec), None, re_acc, None)
            return (abs(expr), None, prec, None)
    elif re:
        return (mpf_abs(re), None, re_acc, None)
    else:
        return (None, None, None, None)

def get_complex_part(expr: 'Expr', no: int, prec: int, options: OPT_DICT) -> TMP_RES:
    workprec = prec
    i = 0
    while 1:
        res = evalf(expr, workprec, options)
        if res is S.ComplexInfinity:
            return (fnan, None, prec, None)
        value, accuracy = res[no::2]
        if not value or accuracy >= prec or -value[2] > prec:
            return (value, None, accuracy, None)
        workprec += max(30, 2 ** i)
        i += 1

