def num_digits(n, base=10):
    if base < 0:
        raise ValueError('base must be int greater than 1')
    if not n:
        return 1
    e, t = integer_log(abs(n), base)
    return 1 + e

def integer_log(n, b):
    n = as_int(n)
    b = as_int(b)
    if b < 0:
        e, t = integer_log(abs(n), -b)
        t = t and e % 2 == (n < 0)
        return (e, t)
    if b <= 1:
        raise ValueError('base must be 2 or more')
    if n < 0:
        if b != 2:
            return (0, False)
        e, t = integer_log(-n, b)
        return (e, False)
    if n == 0:
        raise ValueError('n cannot be 0')
    if n < b:
        return (0, n == 1)
    if b == 2:
        e = n.bit_length() - 1
        return (e, trailing(n) == e)
    t = trailing(b)
    if 2 ** t == b:
        e = int(n.bit_length() - 1) // t
        n_ = 1 << t * e
        return (e, n_ == n)
    d = math.floor(math.log10(n) / math.log10(b))
    n_ = b ** d
    while n_ <= n:
        d += 1
        n_ *= b
    return (d - (n_ > n), n_ == n or n_ // b == n)

def trailing(n):
    if not n:
        return 0
    return bit_scan1(int(n))

