def igcd_lehmer(a, b):
    a, b = (abs(as_int(a)), abs(as_int(b)))
    if a < b:
        a, b = (b, a)
    nbits = 2 * sys.int_info.bits_per_digit
    while a.bit_length() > nbits and b != 0:
        n = a.bit_length() - nbits
        x, y = (int(a >> n), int(b >> n))
        A, B, C, D = (1, 0, 0, 1)
        while True:
            if y + C <= 0:
                break
            q = (x + A) // (y + C)
            x_qy, B_qD = (x - q * y, B - q * D)
            if x_qy + B_qD < 0:
                break
            x, y = (y, x_qy)
            A, B, C, D = (C, D, A - q * C, B_qD)
            if y + D <= 0:
                break
            q = (x + B) // (y + D)
            x_qy, A_qC = (x - q * y, A - q * C)
            if x_qy + A_qC < 0:
                break
            x, y = (y, x_qy)
            A, B, C, D = (C, D, A_qC, B - q * D)
        if B == 0:
            a, b = (b, a % b)
            continue
        a, b = (A * a + B * b, C * a + D * b)
    while b:
        a, b = (b, a % b)
    return a

