        signature = tuple(sys1.symbols)
        return [inv_results[s] for s in signature]

    @classmethod
    @cacheit
    def _indirect_transformation(cls, sys1, sys2):
        rel = sys1.relations
        path = cls._dijkstra(sys1, sys2)
        transforms = []
        for s1, s2 in zip(path, path[1:]):
