import sys
import math
import mpmath.libmp as mlib
_small_trailing = [0] * 256
for j in range(1, 8):
    _small_trailing[1 << j::1 << j + 1] = [j] * (1 << 7 - j)

def bit_scan1(x, n=0):
    if not x:
        return
    x = abs(x >> n)
    low_byte = x & 255
    if low_byte:
        return _small_trailing[low_byte] + n
    t = 8 + n
    x >>= 8
    z = x.bit_length() - 1
    if x == 1 << z:
        return z + t
    if z < 300:
        while not x & 255:
            x >>= 8
            t += 8
    else:
        p = z >> 1
        while not x & 255:
            while x & (1 << p) - 1:
                p >>= 1
            x >>= p
            t += p
    return t + _small_trailing[x & 255]

def bit_scan0(x, n=0):
    return bit_scan1(x + (1 << n), n)

def remove(x, f):
    if f < 2:
        raise ValueError('factor must be > 1')
    if x == 0:
        return (0, 0)
    if f == 2:
        b = bit_scan1(x)
        return (x >> b, b)
    m = 0
    y, rem = divmod(x, f)
    while not rem:
        x = y
        m += 1
        if m > 5:
            pow_list = [f ** 2]
            while pow_list:
                _f = pow_list[-1]
                y, rem = divmod(x, _f)
                if not rem:
                    m += 1 << len(pow_list)
                    x = y
                    pow_list.append(_f ** 2)
                else:
                    pow_list.pop()
        y, rem = divmod(x, f)
    return (x, m)

def factorial(x):
    return int(mlib.ifac(int(x)))

def sqrt(x):
    return int(mlib.isqrt(int(x)))

def sqrtrem(x):
    s, r = mlib.sqrtrem(int(x))
