        return reduce(lambda x, y: x * y // math.gcd(x, y), args, 1)

def _sign(n):
    if n < 0:
        return (-1, -n)
    return (1, n)

def gcdext(a, b):
    if not a or not b:
        g = abs(a) or abs(b)
        if not g:
            return (0, 0, 0)
        return (g, a // g, b // g)
    x_sign, a = _sign(a)
    y_sign, b = _sign(b)
    x, r = (1, 0)
