def _peeloff_ipi(arg):
    ipi = pi * I
    for a in Add.make_args(arg):
        if a == ipi:
            K = S.One
            break
        elif a.is_Mul:
            K, p = a.as_two_terms()
            if p == ipi and K.is_Rational:
                break
    else:
        return (arg, S.Zero)
    m1 = K % S.Half
    m2 = K - m1
    return (arg - m2 * ipi, m2)

