            z = arg.args[0]
            if z.is_real:
                return z
            r, i = match_real_imag(z)
            if r is not None and i is not None:
                f = floor((i + pi / 2) / pi)
                m = z - I * pi * f
                even = f.is_even
                if even is True:
                    return m
                elif even is False:
                    return -m

