        if arg.is_number:
            cst_table = _acosh_table()
            if arg in cst_table:
                if arg.is_extended_real:
                    return cst_table[arg] * I
                return cst_table[arg]
        if arg is S.ComplexInfinity:
            return S.ComplexInfinity
        if arg == I * S.Infinity:
            return S.Infinity + I * pi / 2
        if arg == -I * S.Infinity:
            return S.Infinity - I * pi / 2
        if arg.is_zero:
            return pi * I * S.Half
        if isinstance(arg, cosh) and arg.args[0].is_number:
            z = arg.args[0]
            if z.is_real:
                return Abs(z)
            r, i = match_real_imag(z)
            if r is not None and i is not None:
                f = floor(i / pi)
                m = z - I * pi * f
                even = f.is_even
                if even is True:
                    if r.is_nonnegative:
                        return m
                    elif r.is_negative:
                        return -m
                elif even is False:
                    m -= I * pi
                    if r.is_nonpositive:
                        return -m
                    elif r.is_positive:
                        return m

    @staticmethod
    @cacheit
    def taylor_term(n, x, *previous_terms):
        if n == 0:
            return I * pi / 2
        elif n < 0 or n % 2 == 0:
