def _peeloff_pi(arg):
    pi_coeff = S.Zero
    rest_terms = []
    for a in Add.make_args(arg):
        K = a.coeff(pi)
        if K and K.is_rational:
            pi_coeff += K
        else:
            rest_terms.append(a)
    if pi_coeff is S.Zero:
        return (arg, S.Zero)
    m1 = pi_coeff % S.Half
    m2 = pi_coeff - m1
    if m2.is_integer or ((2 * m2).is_integer and m2.is_even is False):
        return (Add(*rest_terms + [m1 * pi]), m2)
    return (arg, S.Zero)

def _pi_coeff(arg: Expr, cycles: int=1) -> tUnion[Expr, None]:
    if arg is pi:
        return S.One
    elif not arg:
        return S.Zero
    elif arg.is_Mul:
        cx = arg.coeff(pi)
        if cx:
            c, x = cx.as_coeff_Mul()
            if c.is_Float:
                f = abs(c) % 1
                if f != 0:
                    p = -int(round(log(f, 2).evalf()))
                    m = 2 ** p
                    cm = c * m
                    i = int(cm)
                    if equal_valued(i, cm):
                        c = Rational(i, m)
                        cx = c * x
                else:
                    c = Rational(int(c))
                    cx = c * x
            if x.is_integer:
                c2 = c % 2
                if c2 == 1:
                    return x
                elif not c2:
                    if x.is_even is not None:
                        return S.Zero
                    return Integer(2)
                else:
                    return c2 * x
            return cx
    elif arg.is_zero:
        return S.Zero
    return None

