class ReciprocalTrigonometricFunction(TrigonometricFunction):
    _reciprocal_of = None
    _singularities = (S.ComplexInfinity,)
    _is_even: FuzzyBool = None
    _is_odd: FuzzyBool = None

    @classmethod
    def eval(cls, arg):
        if arg.could_extract_minus_sign():
            if cls._is_even:
                return cls(-arg)
            if cls._is_odd:
                return -cls(-arg)
        pi_coeff = _pi_coeff(arg)
        if pi_coeff is not None and (not (2 * pi_coeff).is_integer) and pi_coeff.is_Rational:
            q = pi_coeff.q
            p = pi_coeff.p % (2 * q)
            if p > q:
                narg = (pi_coeff - 1) * pi
                return -cls(narg)
            if 2 * p > q:
                narg = (1 - pi_coeff) * pi
                if cls._is_odd:
                    return cls(narg)
                elif cls._is_even:
                    return -cls(narg)
        if hasattr(arg, 'inverse') and arg.inverse() == cls:
            return arg.args[0]
        t = cls._reciprocal_of.eval(arg)
        if t is None:
            return t
        elif any((isinstance(i, cos) for i in (t, -t))):
            return (1 / t).rewrite(sec)
        elif any((isinstance(i, sin) for i in (t, -t))):
            return (1 / t).rewrite(csc)
        else:
            return 1 / t

