class _erfs(Function):

    @classmethod
    def eval(cls, arg):
        if arg.is_zero:
            return S.One

    def _eval_aseries(self, n, args0, x, logx):
        from sympy.series.order import Order
        point = args0[0]
        if point is S.Infinity:
            z = self.args[0]
            l = [1 / sqrt(pi) * factorial(2 * k) * (-S(4)) ** (-k) / factorial(k) * (1 / z) ** (2 * k + 1) for k in range(n)]
            o = Order(1 / z ** (2 * n + 1), x)
            return Add(*l)._eval_nseries(x, n, logx) + o
        t = point.extract_multiplicatively(I)
        if t is S.Infinity:
            z = self.args[0]
            l = [1 / sqrt(pi) * factorial(2 * k) * (-S(4)) ** (-k) / factorial(k) * (1 / z) ** (2 * k + 1) for k in range(n)]
            o = Order(1 / z ** (2 * n + 1), x)
            return Add(*l)._eval_nseries(x, n, logx) + o
        return super()._eval_aseries(n, args0, x, logx)

    def fdiff(self, argindex=1):
        if argindex == 1:
            z = self.args[0]
            return -2 / sqrt(pi) + 2 * z * _erfs(z)
        else:
            raise ArgumentIndexError(self, argindex)

    def _eval_rewrite_as_intractable(self, z, **kwargs):
        return (S.One - erf(z)) * exp(z ** 2)

class _eis(Function):

    def _eval_aseries(self, n, args0, x, logx):
        from sympy.series.order import Order
        if args0[0] != S.Infinity:
            return super(_erfs, self)._eval_aseries(n, args0, x, logx)
        z = self.args[0]
        l = [factorial(k) * (1 / z) ** (k + 1) for k in range(n)]
        o = Order(1 / z ** (n + 1), x)
        return Add(*l)._eval_nseries(x, n, logx) + o

    def fdiff(self, argindex=1):
        if argindex == 1:
            z = self.args[0]
            return S.One / z - _eis(z)
        else:
            raise ArgumentIndexError(self, argindex)

    def _eval_rewrite_as_intractable(self, z, **kwargs):
        return exp(-z) * Ei(z)

    def _eval_as_leading_term(self, x, logx=None, cdir=0):
        x0 = self.args[0].limit(x, 0)
        if x0.is_zero:
            f = self._eval_rewrite_as_intractable(*self.args)
            return f._eval_as_leading_term(x, logx=logx, cdir=cdir)
        return super()._eval_as_leading_term(x, logx=logx, cdir=cdir)

    def _eval_nseries(self, x, n, logx, cdir=0):
        x0 = self.args[0].limit(x, 0)
        if x0.is_zero:
            f = self._eval_rewrite_as_intractable(*self.args)
            return f._eval_nseries(x, n, logx)
        return super()._eval_nseries(x, n, logx)

from math import prod
from sympy.core import Add, S, Dummy, expand_func
from sympy.core.expr import Expr
from sympy.core.function import Function, ArgumentIndexError, PoleError
