            p, q = z.as_numer_denom()
            part_1 = -S.EulerGamma - pi * cot(p * pi / q) / 2 - log(q) + Add(*[cos(2 * k * pi * p / q) * log(2 * sin(k * pi / q)) for k in range(1, q)])
