                return part_1 + Add(*[1 / (z0 + k) for k in range(n)])
            elif z < 0:
                n = floor(1 - z)
                z0 = z + n
                return part_1 - Add(*[1 / (z0 - 1 - k) for k in range(n)])
        if n == -1:
            return loggamma(z) - log(2 * pi) / 2
        if n.is_integer is False or n.is_nonnegative is False:
            s = Dummy('s')
