            return lcm(*(x.q for x in l))
        beta = compute(self.bm)
        alpha = compute(self.an)
        p, q = (len(self.ap), len(self.bq))
        if p == q:
            if oo in (alpha, beta):
                return oo
            return 2 * pi * lcm(alpha, beta)
        elif p < q:
            return 2 * pi * beta
        else:
            return 2 * pi * alpha

