            return S.NegativeOne ** m * exp(-2 * I * m * phi) * Ynm(n, m, theta, phi)
        if theta.could_extract_minus_sign():
            theta = -theta
            return Ynm(n, m, theta, phi)
        if phi.could_extract_minus_sign():
            phi = -phi
            return exp(-2 * I * m * phi) * Ynm(n, m, theta, phi)

