        dy = y - self.center.y
        if _slope is not None:
            L = (dy - _slope * dx) ** 2
            l = (_slope * dy + dx) ** 2
            h = 1 + _slope ** 2
            b = h * self.major ** 2
            a = h * self.minor ** 2
            return l / b + L / a - 1
