            dydx = idiff(eq, y, x)
            slope = Line(p, Point(x, y)).slope
            tangent_points = solve([slope - dydx, eq], [x, y])
            if len(tangent_points) == 1:
                if tangent_points[0][0] == p.x or tangent_points[0][1] == p.y:
