    @property
    def bounds(self):
        verts = self.points
        xs = [p.x for p in verts]
        ys = [p.y for p in verts]
        return (min(xs), min(ys), max(xs), max(ys))

    def perpendicular_line(self, p):
        p = Point(p, dim=self.ambient_dimension)
        return Line(p, p + self.direction.orthogonal_direction)

