    return d * pi / 180

def deg(r):
    return r / pi * 180

def _slope(d):
    rv = tan(rad(d))
    return rv

def _asa(d1, l, d2):
    xy = Line((0, 0), slope=_slope(d1)).intersection(Line((l, 0), slope=_slope(180 - d2)))[0]
    return Triangle((0, 0), (l, 0), xy)

def _sss(l1, l2, l3):
    c1 = Circle((0, 0), l3)
    c2 = Circle((l1, 0), l2)
    inter = [a for a in c1.intersection(c2) if a.y.is_nonnegative]
