def centroid(*args):
    from .line import Segment
    from .polygon import Polygon
    if args:
        if all((isinstance(g, Point) for g in args)):
            c = Point(0, 0)
            for g in args:
                c += g
            den = len(args)
        elif all((isinstance(g, Segment) for g in args)):
            c = Point(0, 0)
            L = 0
            for g in args:
                l = g.length
                c += g.midpoint * l
                L += l
            den = L
        elif all((isinstance(g, Polygon) for g in args)):
            c = Point(0, 0)
            A = 0
            for g in args:
                a = g.area
                c += g.centroid * a
