            a = Wild('a', exclude=[x])
            b = Wild('b', exclude=[x])
            c = Wild('c', exclude=[x])
            for g in set(terms):
                if g.is_Function:
                    if isinstance(g, li):
                        M = g.args[0].match(a * x ** b)
                        if M is not None:
                            terms.add(x * (li(M[a] * x ** M[b]) - (M[a] * x ** M[b]) ** (-1 / M[b]) * Ei((M[b] + 1) * log(M[a] * x ** M[b]) / M[b])))
                    elif isinstance(g, exp):
                        M = g.args[0].match(a * x ** 2)
                        if M is not None:
                            if M[a].is_positive:
