def integration_reduction_dynamic(facets, index, a, b, expr, degree, dims, x_index, y_index, max_index, x0, monomial_values, monom_index, vertices=None, hp_param=None):
    value = S.Zero
    m = len(facets)
    if expr == S.Zero:
