def DEBUG_WRAP(func):

    def wrap(*args, **kwargs):
        from sympy import SYMPY_DEBUG
        global _LT_level
        if not SYMPY_DEBUG:
            return func(*args, **kwargs)
        if _LT_level == 0:
            print('\n' + '-' * 78, file=sys.stderr)
