        else:
            result = func(*args, **kwargs)
        _LT_level -= 1
        print('-LT- %s---> %s' % ('  ' * _LT_level, result), file=sys.stderr)
        if _LT_level == 0:
            print('-' * 78 + '\n', file=sys.stderr)
