@DEBUG_WRAP
def _piecewise_to_heaviside(f, t):
    if not t.is_real:
        r = Dummy('r', real=True)
        return _piecewise_to_heaviside(f.xreplace({t: r}), r).xreplace({r: t})
    x = piecewise_exclusive(f)
    r = []
    for fn, cond in x.args:
        if isinstance(cond, Relational) and t in cond.args:
            if isinstance(cond, (Eq, Ne)):
                return f
            else:
                r.append(Heaviside(cond.gts - cond.lts) * fn)
        elif isinstance(cond, Or) and len(cond.args) == 2:
            for c2 in cond.args:
                if c2.lhs == t:
                    r.append(Heaviside(c2.gts - c2.lts) * fn)
                else:
                    return f
        elif isinstance(cond, And) and len(cond.args) == 2:
            c0, c1 = cond.args
            if c0.lhs == t and c1.lhs == t:
                if '>' in c0.rel_op:
                    c0, c1 = (c1, c0)
                r.append((Heaviside(c1.gts - c1.lts) - Heaviside(c0.lts - c0.gts)) * fn)
            else:
                return f
        else:
            return f
    return Add(*r)

def laplace_correspondence(f, fdict, /):
    p = Wild('p')
    s = Wild('s')
    t = Wild('t')
    a = Wild('a')
    if not isinstance(f, Expr) or (not f.has(LaplaceTransform) and (not f.has(InverseLaplaceTransform))):
        return f
    for y, Y in fdict.items():
        if (m := f.match(LaplaceTransform(y(a), t, s))) is not None and m[a] == m[t]:
            return Y(m[s])
        if (m := f.match(InverseLaplaceTransform(Y(a), s, t, p))) is not None and m[a] == m[s]:
            return y(m[t])
    func = f.func
    args = [laplace_correspondence(arg, fdict) for arg in f.args]
    return func(*args)

def laplace_initial_conds(f, t, fdict, /):
    for y, ic in fdict.items():
        for k in range(len(ic)):
            if k == 0:
                f = f.replace(y(0), ic[0])
            elif k == 1:
                f = f.replace(Subs(Derivative(y(t), t), t, 0), ic[1])
            else:
                f = f.replace(Subs(Derivative(y(t), (t, k)), t, 0), ic[k])
    return f

@DEBUG_WRAP
def _laplace_transform(fn, t_, s_, *, simplify):
    terms_t = Add.make_args(fn)
    terms_s = []
    terms = []
    planes = []
    conditions = []
    for ff in terms_t:
        k, ft = ff.as_independent(t_, as_Add=False)
        if ft.has(SingularityFunction):
            _terms = Add.make_args(ft.rewrite(Heaviside))
            for _term in _terms:
                k1, f1 = _term.as_independent(t_, as_Add=False)
                terms.append((k * k1, f1))
        elif ft.func == Piecewise and (not ft.has(DiracDelta(t_))):
            _terms = Add.make_args(_piecewise_to_heaviside(ft, t_))
            for _term in _terms:
                k1, f1 = _term.as_independent(t_, as_Add=False)
                terms.append((k * k1, f1))
        else:
            terms.append((k, ft))
    for k, ft in terms:
        if ft.has(SingularityFunction):
            r = (LaplaceTransform(ft, t_, s_), S.NegativeInfinity, True)
        else:
            if ft.has(Heaviside(t_)) and (not ft.has(DiracDelta(t_))):
                ft = ft.subs(Heaviside(t_), 1)
            if (r := _laplace_apply_simple_rules(ft, t_, s_)) is not None or (r := _laplace_apply_prog_rules(ft, t_, s_)) is not None or (r := _laplace_expand(ft, t_, s_)) is not None:
                pass
            elif any((undef.has(t_) for undef in ft.atoms(AppliedUndef))):
                r = (LaplaceTransform(ft, t_, s_), S.NegativeInfinity, True)
            elif (r := _laplace_transform_integration(ft, t_, s_, simplify=simplify)) is not None:
                pass
            else:
                r = (LaplaceTransform(ft, t_, s_), S.NegativeInfinity, True)
        ri_, pi_, ci_ = r
        terms_s.append(k * ri_)
        planes.append(pi_)
        conditions.append(ci_)
    result = Add(*terms_s)
    if simplify:
        result = result.simplify(doit=False)
    plane = Max(*planes)
    condition = And(*conditions)
    return (result, plane, condition)

class LaplaceTransform(IntegralTransform):
    _name = 'Laplace'

    def _compute_transform(self, f, t, s, **hints):
        _simplify = hints.get('simplify', False)
        LT = _laplace_transform_integration(f, t, s, simplify=_simplify)
        return LT

    def _as_integral(self, f, t, s):
        return Integral(f * exp(-s * t), (t, S.Zero, S.Infinity))

    def doit(self, **hints):
        _noconds = hints.get('noconds', True)
        _simplify = hints.get('simplify', False)
        debugf('[LT doit] (%s, %s, %s)', (self.function, self.function_variable, self.transform_variable))
        t_ = self.function_variable
        s_ = self.transform_variable
        fn = self.function
        r = _laplace_transform(fn, t_, s_, simplify=_simplify)
        if _noconds:
            return r[0]
        else:
            return r

def laplace_transform(f, t, s, legacy_matrix=True, **hints):
    _noconds = hints.get('noconds', False)
    _simplify = hints.get('simplify', False)
    if isinstance(f, MatrixBase) and hasattr(f, 'applyfunc'):
        conds = not hints.get('noconds', False)
        if conds and legacy_matrix:
            adt = 'deprecated-laplace-transform-matrix'
            sympy_deprecation_warning('\nCalling laplace_transform() on a Matrix with noconds=False (the default) is\ndeprecated. Either noconds=True or use legacy_matrix=False to get the new\nbehavior.\n                ', deprecated_since_version='1.9', active_deprecations_target=adt)
            with ignore_warnings(SymPyDeprecationWarning):
                return f.applyfunc(lambda fij: laplace_transform(fij, t, s, **hints))
        else:
            elements_trans = [laplace_transform(fij, t, s, **hints) for fij in f]
            if conds:
                elements, avals, conditions = zip(*elements_trans)
                f_laplace = type(f)(*f.shape, elements)
                return (f_laplace, Max(*avals), And(*conditions))
            else:
                return type(f)(*f.shape, elements_trans)
    LT, p, c = LaplaceTransform(f, t, s).doit(noconds=False, simplify=_simplify)
    if not _noconds:
        return (LT, p, c)
    else:
        return LT

@DEBUG_WRAP
def _inverse_laplace_transform_integration(F, s, t_, plane, *, simplify):
    from sympy.integrals.meijerint import meijerint_inversion, _get_coeff_exp
    from sympy.integrals.transforms import inverse_mellin_transform
    t = Dummy('t', real=True)

    def pw_simp(*args):
        if len(args) != 3:
            return Piecewise(*args)
        arg = args[2].args[0].argument
        coeff, exponent = _get_coeff_exp(arg, t)
        e1 = args[0].args[0]
        e2 = args[1].args[0]
        return Heaviside(1 / Abs(coeff) - t ** exponent) * e1 + Heaviside(t ** exponent - 1 / Abs(coeff)) * e2
    if F.is_rational_function(s):
        F = F.apart(s)
    if F.is_Add:
        f = Add(*[_inverse_laplace_transform_integration(X, s, t, plane, simplify) for X in F.args])
        return (_simplify(f.subs(t, t_), simplify), True)
    try:
        f, cond = inverse_mellin_transform(F, s, exp(-t), (None, S.Infinity), needeval=True, noconds=False)
    except IntegralTransformError:
        f = None
    if f is None:
        f = meijerint_inversion(F, s, t)
        if f is None:
            return None
        if f.is_Piecewise:
            f, cond = f.args[0]
            if f.has(Integral):
                return None
        else:
            cond = S.true
        f = f.replace(Piecewise, pw_simp)
    if f.is_Piecewise:
        return (f.subs(t, t_), cond)
    u = Dummy('u')

    def simp_heaviside(arg, H0=S.Half):
        a = arg.subs(exp(-t), u)
        if a.has(t):
            return Heaviside(arg, H0)
        from sympy.solvers.inequalities import _solve_inequality
        rel = _solve_inequality(a > 0, u)
        if rel.lts == u:
            k = log(rel.gts)
            return Heaviside(t + k, H0)
        else:
            k = log(rel.lts)
            return Heaviside(-(t + k), H0)
    f = f.replace(Heaviside, simp_heaviside)

    def simp_exp(arg):
        return expand_complex(exp(arg))
    f = f.replace(exp, simp_exp)
    return (_simplify(f.subs(t, t_), simplify), cond)

@DEBUG_WRAP
def _complete_the_square_in_denom(f, s):
    from sympy.simplify.radsimp import fraction
    [n, d] = fraction(f)
    if d.is_polynomial(s):
        cf = d.as_poly(s).all_coeffs()
        if len(cf) == 3:
            a, b, c = cf
            d = a * ((s + b / (2 * a)) ** 2 + c / a - (b / (2 * a)) ** 2)
    return n / d

@cacheit
def _inverse_laplace_build_rules():
    s = Dummy('s')
    t = Dummy('t')
    a = Wild('a', exclude=[s])
    b = Wild('b', exclude=[s])
    c = Wild('c', exclude=[s])
    _debug('_inverse_laplace_build_rules is building rules')

    def _frac(f, s):
        try:
            return f.factor(s)
        except PolynomialError:
            return f

    def same(f):
        return f
    _ILT_rules = [(a / s, a, S.true, same, 1), (b * (s + a) ** (-c), t ** (c - 1) * exp(-a * t) / gamma(c), S.true, same, 1), (1 / (s ** 2 + a ** 2) ** 2, (sin(a * t) - a * t * cos(a * t)) / (2 * a ** 3), S.true, same, 1), (1 / s ** b, t ** (b - 1) / gamma(b), S.true, same, 1), (1 / (s * (s + a) ** b), lowergamma(b, a * t) / (a ** b * gamma(b)), S.true, same, 1)]
    return (_ILT_rules, s, t)

