                _debug('     rule 5.3.19')
    elif len(poles) == 3 and len(zeros) == 0:
        if poles[0][n] == -1 and poles[0][b] == 0 and (poles[0][m] == 1) and (poles[1][n] == -1) and (poles[1][m] == 1) and (poles[2][n] == -S.Half) and (poles[2][m] == 1):
            a_ = -poles[1][b] / poles[1][a]
            k_ = 1 / poles[0][a] / poles[1][a] / sqrt(poles[2][a]) * constants
            if a_.is_positive:
                result = k_ * (a_ ** (-S(3) / 2) * exp(a_ * t) * erf(sqrt(a_) * sqrt(t)) - 2 / a_ / sqrt(pi) * sqrt(t))
                _debug('     rule 5.3.2')
        elif poles[0][n] == -1 and poles[0][m] == 1 and (poles[1][n] == -1) and (poles[1][m] == S.Half) and (poles[2][n] == -S.Half) and (poles[2][m] == 1) and (poles[2][b] == 0):
