@DEBUG_WRAP
def _inverse_laplace_rational(fn, s, t, plane, *, simplify):
    x_ = symbols('x_')
    f = fn.apart(s)
    terms = Add.make_args(f)
    terms_t = []
    conditions = [S.true]
    for term in terms:
        [n, d] = term.as_numer_denom()
        dc = d.as_poly(s).all_coeffs()
        dc_lead = dc[0]
        dc = [x / dc_lead for x in dc]
        nc = [x / dc_lead for x in n.as_poly(s).all_coeffs()]
        if len(dc) == 1:
            r = nc[0] * DiracDelta(t)
            terms_t.append(r)
        elif len(dc) == 2:
            r = nc[0] * exp(-dc[1] * t)
            terms_t.append(Heaviside(t) * r)
        elif len(dc) == 3:
            a = dc[1] / 2
            b = (dc[2] - a ** 2).factor()
            if len(nc) == 1:
                nc = [S.Zero] + nc
            l, m = tuple(nc)
            if b == 0:
                r = (m * t + l * (1 - a * t)) * exp(-a * t)
            else:
                hyp = False
                if b.is_negative:
                    b = -b
                    hyp = True
                b2 = list(roots(x_ ** 2 - b, x_).keys())[0]
                bs = sqrt(b).simplify()
                if hyp:
                    r = l * exp(-a * t) * cosh(b2 * t) + (m - a * l) / bs * exp(-a * t) * sinh(bs * t)
                else:
                    r = l * exp(-a * t) * cos(b2 * t) + (m - a * l) / bs * exp(-a * t) * sin(bs * t)
            terms_t.append(Heaviside(t) * r)
        else:
            ft, cond = _inverse_laplace_transform(term, s, t, plane, simplify=simplify, dorational=False)
            terms_t.append(ft)
            conditions.append(cond)
    result = Add(*terms_t)
    if simplify:
        result = result.simplify(doit=False)
    return (result, And(*conditions))

@DEBUG_WRAP
def _inverse_laplace_transform(fn, s_, t_, plane, *, simplify, dorational):
    terms = Add.make_args(fn)
    terms_t = []
    conditions = []
    for term in terms:
        if term.has(exp):
            term = term.subs(s_, -s_).together().subs(s_, -s_)
        k, f = term.as_independent(s_, as_Add=False)
        if dorational and term.is_rational_function(s_) and ((r := _inverse_laplace_rational(f, s_, t_, plane, simplify=simplify)) is not None) or (r := _inverse_laplace_apply_simple_rules(f, s_, t_)) is not None or (r := _inverse_laplace_early_prog_rules(f, s_, t_, plane)) is not None or ((r := _inverse_laplace_expand(f, s_, t_, plane)) is not None) or ((r := _inverse_laplace_apply_prog_rules(f, s_, t_, plane)) is not None):
            pass
        elif any((undef.has(s_) for undef in f.atoms(AppliedUndef))):
            r = (InverseLaplaceTransform(f, s_, t_, plane), S.true)
        elif (r := _inverse_laplace_transform_integration(f, s_, t_, plane, simplify=simplify)) is not None:
            pass
        else:
            r = (InverseLaplaceTransform(f, s_, t_, plane), S.true)
        ri_, ci_ = r
        terms_t.append(k * ri_)
        conditions.append(ci_)
    result = Add(*terms_t)
    if simplify:
        result = result.simplify(doit=False)
    condition = And(*conditions)
    return (result, condition)

class InverseLaplaceTransform(IntegralTransform):
    _name = 'Inverse Laplace'
    _none_sentinel = Dummy('None')
    _c = Dummy('c')

    def __new__(cls, F, s, x, plane, **opts):
        if plane is None:
            plane = InverseLaplaceTransform._none_sentinel
        return IntegralTransform.__new__(cls, F, s, x, plane, **opts)

    @property
    def fundamental_plane(self):
        plane = self.args[3]
        if plane is InverseLaplaceTransform._none_sentinel:
            plane = None
        return plane

    def _compute_transform(self, F, s, t, **hints):
        return _inverse_laplace_transform_integration(F, s, t, self.fundamental_plane, **hints)

    def _as_integral(self, F, s, t):
        c = self.__class__._c
        return Integral(exp(s * t) * F, (s, c - S.ImaginaryUnit * S.Infinity, c + S.ImaginaryUnit * S.Infinity)) / (2 * S.Pi * S.ImaginaryUnit)

    def doit(self, **hints):
        _noconds = hints.get('noconds', True)
        _simplify = hints.get('simplify', False)
        debugf('[ILT doit] (%s, %s, %s)', (self.function, self.function_variable, self.transform_variable))
        s_ = self.function_variable
        t_ = self.transform_variable
        fn = self.function
        plane = self.fundamental_plane
        r = _inverse_laplace_transform(fn, s_, t_, plane, simplify=_simplify, dorational=True)
        if _noconds:
            return r[0]
        else:
            return r

def inverse_laplace_transform(F, s, t, plane=None, **hints):
    _noconds = hints.get('noconds', True)
    _simplify = hints.get('simplify', False)
    if isinstance(F, MatrixBase) and hasattr(F, 'applyfunc'):
        return F.applyfunc(lambda Fij: inverse_laplace_transform(Fij, s, t, plane, **hints))
    r, c = InverseLaplaceTransform(F, s, t, plane).doit(noconds=False, simplify=_simplify)
    if _noconds:
        return r
    else:
        return (r, c)

def _fast_inverse_laplace(e, s, t):
    a, b, n = symbols('a, b, n', cls=Wild, exclude=[s])

    def _ilt(e):
        if not e.has(s):
            return e
        elif e.is_Add:
            return _ilt_add(e)
        elif e.is_Mul:
            return _ilt_mul(e)
        elif e.is_Pow:
            return _ilt_pow(e)
        elif isinstance(e, RootSum):
            return _ilt_rootsum(e)
        else:
            raise NotImplementedError

    def _ilt_add(e):
        return e.func(*map(_ilt, e.args))

    def _ilt_mul(e):
        coeff, expr = e.as_independent(s)
        if expr.is_Mul:
            raise NotImplementedError
        return coeff * _ilt(expr)

    def _ilt_pow(e):
        match = e.match((a * s + b) ** n)
        if match is not None:
            nm, am, bm = (match[n], match[a], match[b])
            if nm.is_Integer and nm < 0:
                return t ** (-nm - 1) * exp(-(bm / am) * t) / (am ** (-nm) * gamma(-nm))
            if nm == 1:
                return exp(-(bm / am) * t) / am
        raise NotImplementedError

    def _ilt_rootsum(e):
        expr = e.fun.expr
        [variable] = e.fun.variables
        return RootSum(e.poly, Lambda(variable, together(_ilt(expr))))
    return _ilt(e)

