    def zeros(kls, rows, cols=None, **kwargs):
        if cols is None:
            cols = rows
        if rows < 0 or cols < 0:
            raise ValueError('Cannot create a {} x {} matrix. Both dimensions must be positive'.format(rows, cols))
        klass = kwargs.get('cls', kls)
