        if not self.is_square:
            return False
        rows, cols = self.shape

        def test_row(i):
            summation = self.zero
            for j in range(cols):
                if i != j:
                    summation += Abs(self[i, j])
            return (Abs(self[i, i]) - summation).is_positive
        return fuzzy_and((test_row(i) for i in range(rows)))

