        op, row, k, row1, row2 = self._normalize_op_args(op, row, k, row1, row2, 'row')
        if op == 'n->kn':
            return self._eval_row_op_multiply_row_by_const(row, k)
        if op == 'n<->m':
            return self._eval_row_op_swap(row1, row2)
        if op == 'n->n+km':
