            num, num2 = (num2, num2 ** 2)
        self._list += _array('L', self._primerange(num, n + 1))

    def _primerange(self, a, b):
        if b % 2:
            b -= 1
        while a < b:
            block_size = min(self.sieve_interval, (b - a) // 2)
            block = [True] * block_size
