        n1 = (d2 * e * n + (k2 ** 2 - 1) // d1) * pow(e * k2 * k2 * d2, _totient[k1] - 1, k1) % k1
        n2 = (d1 * e * n + (k1 ** 2 - 1) // d2) * pow(e * k1 * k1 * d1, _totient[k2] - 1, k2) % k2
        return mpf_mul(_a(n1, k1, prec), _a(n2, k2, prec), prec)
    if e == 2:
        n1 = (8 * n + 5) * pow(128, _totient[k1] - 1, k1) % k1
        n2 = (4 + (n - 2 - (k1 ** 2 - 1) // 8) * k1 ** 2 % 4) % 4
        return mpf_mul(mpf_mul(from_int(-1), _a(n1, k1, prec), prec), _a(n2, k2, prec))
    n1 = (8 * n + 1) * pow(32, _totient[k1] - 1, k1) % k1
    n2 = (2 + (n - (k1 ** 2 - 1) // 8) % 2) % 2
    return mpf_mul(_a(n1, k1, prec), _a(n2, k2, prec), prec)

def _d(n, j, prec, sq23pi, sqrt8):
    j = from_int(j)
    pi = mpf_pi(prec)
    a = mpf_div(sq23pi, j, prec)
    b = mpf_sub(from_int(n), from_rational(1, 24, prec), prec)
    c = mpf_sqrt(b, prec)
    ch, sh = mpf_cosh_sinh(mpf_mul(a, c), prec)
    D = mpf_div(mpf_sqrt(j, prec), mpf_mul(mpf_mul(sqrt8, b), pi), prec)
    E = mpf_sub(mpf_mul(a, ch), mpf_div(sh, c, prec), prec)
    return mpf_mul(D, E)

@recurrence_memo([1, 1])
def _partition_rec(n: int, prev) -> int:
    v = 0
    penta = 0
    for i in count():
        penta += 3 * i + 1
        np = n - penta
        if np < 0:
            break
        s = prev[np]
        np -= i + 1
        if 0 <= np:
            s += prev[np]
        v += -s if i % 2 else s
    return v

def _partition(n: int) -> int:
    if n < 0:
        return 0
    if n <= 200000 and n - _partition_rec.cache_length() < 70 or (_partition_rec.cache_length() == 2 and n < 14400):
        return _partition_rec(n)
    if '_factor' not in globals():
        _pre()
    pbits = int((math.pi * (2 * n / 3.0) ** 0.5 - math.log(4 * n)) / math.log(10) + 1) * math.log2(10)
    prec = p = int(pbits * 1.1 + 100)
    c1 = 44 * math.pi ** 2 / (225 * math.sqrt(3))
    c2 = math.pi * math.sqrt(2) / 75
    c3 = math.pi * math.sqrt(2 / 3)

    def _M(n, N):
        sqrt = math.sqrt
        return c1 / sqrt(N) + c2 * sqrt(N / (n - 1)) * math.sinh(c3 * sqrt(n) / N)
    big = max(9, math.ceil(n ** 0.5))
    assert _M(n, big) < 0.5
    while big > 40 and _M(n, big) < 0.5:
        big //= 2
    small = big
    big = small * 2
    while big - small > 1:
        N = (big + small) // 2
        if (er := _M(n, N)) < 0.5:
            big = N
        elif er >= 0.5:
            small = N
    M = big
    if M > 10 ** 5:
        raise ValueError('Input too big')
    s = fzero
    sq23pi = mpf_mul(mpf_sqrt(from_rational(2, 3, p), p), mpf_pi(p), p)
    sqrt8 = mpf_sqrt(from_int(8), p)
    for q in range(1, M):
        a = _a(n, q, p)
        d = _d(n, q, p, sq23pi, sqrt8)
        s = mpf_add(s, mpf_mul(a, d), prec)
        p = bitcount(abs(to_int(d))) + 50
    return int(to_int(mpf_add(s, fhalf, prec)))

