def is_extra_strong_lucas_prp(n):
    n = as_int(n)
    if n == 2:
        return True
    if n < 2 or n % 2 == 0:
        return False
    if gmpy_is_square(n):
        return False
    D, P, Q = _lucas_extrastrong_params(n)
    if D == 0:
        return False
    s = bit_scan1(n + 1)
    k = n + 1 >> s
    U, V, _ = _lucas_sequence(n, P, Q, k)
    if U == 0 and (V == 2 or V == n - 2):
        return True
    for _ in range(1, s):
        if V == 0:
            return True
        V = (V * V - 2) % n
    return False

def proth_test(n):
    n = as_int(n)
    if n < 3:
        raise ValueError('n is not Proth number')
    m = bit_scan1(n - 1)
    k = n >> m
    if m < k.bit_length():
        raise ValueError('n is not Proth number')
    if n % 3 == 0:
        return n == 3
    if k % 3:
        return pow(3, n >> 1, n) == n - 1
    if gmpy_is_square(n):
        return False
    for a in range(5, n):
        j = jacobi(a, n)
        if j == -1:
            return pow(a, n >> 1, n) == n - 1
        if j == 0:
            return False

def _lucas_lehmer_primality_test(p):
    v = 4
    m = 2 ** p - 1
    for _ in range(p - 2):
        v = pow(v, 2, m) - 2
    return v == 0

def is_mersenne_prime(n):
