from sympy.core.add import Add
from sympy.core.mul import Mul
from sympy.core.numbers import I
from sympy.core.power import Pow
from sympy.core.symbol import Symbol
from sympy.physics.quantum import TensorProduct
__all__ = ['evaluate_pauli_product']

def delta(i, j):
    if i == j:
        return 1
    else:
        return 0

def epsilon(i, j, k):
    if (i, j, k) in ((1, 2, 3), (2, 3, 1), (3, 1, 2)):
        return 1
    elif (i, j, k) in ((1, 3, 2), (3, 2, 1), (2, 1, 3)):
        return -1
    else:
        return 0

class Pauli(Symbol):
    __slots__ = ('i', 'label')

    def __new__(cls, i, label='sigma'):
        if i not in [1, 2, 3]:
            raise IndexError('Invalid Pauli index')
        obj = Symbol.__new__(cls, '%s%d' % (label, i), commutative=False, hermitian=True)
        obj.i = i
        obj.label = label
        return obj

    def __getnewargs_ex__(self):
        return ((self.i, self.label), {})

    def _hashable_content(self):
        return (self.i, self.label)

    def __mul__(self, other):
        if isinstance(other, Pauli):
            j = self.i
            k = other.i
            jlab = self.label
            klab = other.label
            if jlab == klab:
                return delta(j, k) + I * epsilon(j, k, 1) * Pauli(1, jlab) + I * epsilon(j, k, 2) * Pauli(2, jlab) + I * epsilon(j, k, 3) * Pauli(3, jlab)
        return super().__mul__(other)

    def _eval_power(b, e):
        if e.is_Integer and e.is_positive:
            return super().__pow__(int(e) % 2)

def evaluate_pauli_product(arg):
    start = arg
    end = arg
    if isinstance(arg, Pow) and isinstance(arg.args[0], Pauli):
        if arg.args[1].is_odd:
            return arg.args[0]
        else:
            return 1
    if isinstance(arg, Add):
        return Add(*[evaluate_pauli_product(part) for part in arg.args])
    if isinstance(arg, TensorProduct):
        return TensorProduct(*[evaluate_pauli_product(part) for part in arg.args])
    elif not isinstance(arg, Mul):
        return arg
    while not start == end or (start == arg and end == arg):
        start = end
        tmp = start.as_coeff_mul()
        sigma_product = 1
        com_product = 1
        keeper = 1
        for el in tmp[1]:
            if isinstance(el, Pauli):
                sigma_product *= el
            elif not el.is_commutative:
                if isinstance(el, Pow) and isinstance(el.args[0], Pauli):
                    if el.args[1].is_odd:
                        sigma_product *= el.args[0]
                elif isinstance(el, TensorProduct):
                    keeper = keeper * sigma_product * TensorProduct(*[evaluate_pauli_product(part) for part in el.args])
                    sigma_product = 1
                else:
                    keeper = keeper * sigma_product * el
                    sigma_product = 1
            else:
                com_product *= el
        end = tmp[0] * keeper * sigma_product * com_product
        if end == arg:
            break
    return end

