def wavefunction(n, x):
    n, x = (S(n), S(x))
    return exp(n * I * x) / sqrt(2 * pi)

def energy(n, m, r):
    n, m, r = (S(n), S(m), S(r))
    if n.is_integer:
        return n ** 2 * hbar ** 2 / (2 * m * r ** 2)
    else:
        raise ValueError("'n' must be integer")

