_Factlist = [1]

def _calc_factlist(nn):
    if nn >= len(_Factlist):
        for ii in range(len(_Factlist), int(nn + 1)):
            _Factlist.append(_Factlist[ii - 1] * ii)
    return _Factlist[:int(nn) + 1]

def _int_or_halfint(value):
    if isinstance(value, int):
        return value
    elif type(value) is float:
        if value.is_integer():
            return int(value)
        if (2 * value).is_integer():
            return value
    elif isinstance(value, Rational):
        if value.q == 2:
            return value.p / value.q
        elif value.q == 1:
            return value.p
    elif isinstance(value, Float):
        return _int_or_halfint(float(value))
    raise ValueError('expecting integer or half-integer, got %s' % value)

def wigner_3j(j_1, j_2, j_3, m_1, m_2, m_3):
    j_1, j_2, j_3, m_1, m_2, m_3 = map(_int_or_halfint, [j_1, j_2, j_3, m_1, m_2, m_3])
    if m_1 + m_2 + m_3 != 0:
        return S.Zero
    a1 = j_1 + j_2 - j_3
    if a1 < 0:
        return S.Zero
    a2 = j_1 - j_2 + j_3
    if a2 < 0:
        return S.Zero
    a3 = -j_1 + j_2 + j_3
    if a3 < 0:
        return S.Zero
    if abs(m_1) > j_1 or abs(m_2) > j_2 or abs(m_3) > j_3:
        return S.Zero
    if not (int_valued(j_1 - m_1) and int_valued(j_2 - m_2) and int_valued(j_3 - m_3)):
        return S.Zero
    maxfact = max(j_1 + j_2 + j_3 + 1, j_1 + abs(m_1), j_2 + abs(m_2), j_3 + abs(m_3))
    _calc_factlist(int(maxfact))
    argsqrt = Integer(_Factlist[int(j_1 + j_2 - j_3)] * _Factlist[int(j_1 - j_2 + j_3)] * _Factlist[int(-j_1 + j_2 + j_3)] * _Factlist[int(j_1 - m_1)] * _Factlist[int(j_1 + m_1)] * _Factlist[int(j_2 - m_2)] * _Factlist[int(j_2 + m_2)] * _Factlist[int(j_3 - m_3)] * _Factlist[int(j_3 + m_3)]) / _Factlist[int(j_1 + j_2 + j_3 + 1)]
    ressqrt = sqrt(argsqrt)
    if ressqrt.is_complex or ressqrt.is_infinite:
        ressqrt = ressqrt.as_real_imag()[0]
    imin = max(-j_3 + j_1 + m_2, -j_3 + j_2 - m_1, 0)
    imax = min(j_2 + m_2, j_1 - m_1, j_1 + j_2 - j_3)
    sumres = 0
    for ii in range(int(imin), int(imax) + 1):
        den = _Factlist[ii] * _Factlist[int(ii + j_3 - j_1 - m_2)] * _Factlist[int(j_2 + m_2 - ii)] * _Factlist[int(j_1 - ii - m_1)] * _Factlist[int(ii + j_3 - j_2 + m_1)] * _Factlist[int(j_1 + j_2 - j_3 - ii)]
        sumres = sumres + Integer((-1) ** ii) / den
    prefid = Integer((-1) ** int(j_1 - j_2 - m_3))
    res = ressqrt * sumres * prefid
    return res

def clebsch_gordan(j_1, j_2, j_3, m_1, m_2, m_3):
    j_1 = sympify(j_1)
    j_2 = sympify(j_2)
    j_3 = sympify(j_3)
    m_1 = sympify(m_1)
    m_2 = sympify(m_2)
    m_3 = sympify(m_3)
