def wigner_d(J, alpha, beta, gamma):
    d = wigner_d_small(J, beta)
    M = [J - i for i in range(2 * J + 1)]
    D = [[exp(I * Mi * alpha) * d[i, j] * exp(I * Mj * gamma) for j, Mj in enumerate(M)] for i, Mi in enumerate(M)]
    return ImmutableMatrix(D)

