from sympy.physics.biomechanics._mixin import _NamedMixin
from sympy.physics.mechanics import dynamicsymbols
__all__ = ['ActivationBase', 'FirstOrderActivationDeGroote2016', 'ZerothOrderActivation']

class ActivationBase(ABC, _NamedMixin):

    def __init__(self, name):
        self.name = str(name)
        self._e = dynamicsymbols(f'e_{name}')
        self._a = dynamicsymbols(f'a_{name}')

    @classmethod
    @abstractmethod
    def with_defaults(cls, name):
        pass

    @property
    def excitation(self):
        return self._e

    @property
    def e(self):
        return self._e

    @property
    def activation(self):
        return self._a

    @property
    def a(self):
        return self._a

    @property
    @abstractmethod
    def order(self):
        pass

    @property
    @abstractmethod
    def state_vars(self):
        pass

    @property
    @abstractmethod
    def x(self):
        pass

    @property
    @abstractmethod
    def input_vars(self):
        pass

    @property
    @abstractmethod
    def r(self):
        pass

    @property
    @abstractmethod
    def constants(self):
        pass

    @property
    @abstractmethod
    def p(self):
        pass

    @property
    @abstractmethod
    def M(self):
        pass

    @property
    @abstractmethod
    def F(self):
        pass

    @abstractmethod
    def rhs(self):
        pass

    def __eq__(self, other):
        if type(self) != type(other):
            return False
        if self.name != other.name:
            return False
        return True

    def __repr__(self):
        return f'{self.__class__.__name__}({self.name!r})'

class ZerothOrderActivation(ActivationBase):

    def __init__(self, name):
        super().__init__(name)
