    return _inertia_of_point_mass(mass, pos_vec, frame)

def linear_momentum(frame, *body):
    if not isinstance(frame, ReferenceFrame):
        raise TypeError('Please specify a valid ReferenceFrame')
    else:
        linear_momentum_sys = Vector(0)
        for e in body:
            if isinstance(e, (RigidBody, Particle)):
                linear_momentum_sys += e.linear_momentum(frame)
            else:
                raise TypeError('*body must have only Particle or RigidBody')
    return linear_momentum_sys

def angular_momentum(point, frame, *body):
    if not isinstance(frame, ReferenceFrame):
        raise TypeError('Please enter a valid ReferenceFrame')
    if not isinstance(point, Point):
        raise TypeError('Please specify a valid Point')
    else:
        angular_momentum_sys = Vector(0)
        for e in body:
            if isinstance(e, (RigidBody, Particle)):
                angular_momentum_sys += e.angular_momentum(point, frame)
            else:
                raise TypeError('*body must have only Particle or RigidBody')
    return angular_momentum_sys

def kinetic_energy(frame, *body):
    if not isinstance(frame, ReferenceFrame):
        raise TypeError('Please enter a valid ReferenceFrame')
    ke_sys = S.Zero
    for e in body:
        if isinstance(e, (RigidBody, Particle)):
            ke_sys += e.kinetic_energy(frame)
        else:
            raise TypeError('*body must have only Particle or RigidBody')
    return ke_sys

def potential_energy(*body):
    pe_sys = S.Zero
    for e in body:
        if isinstance(e, (RigidBody, Particle)):
            pe_sys += e.potential_energy
        else:
            raise TypeError('*body must have only Particle or RigidBody')
    return pe_sys

def gravity(acceleration, *bodies):
    from sympy.physics.mechanics.loads import gravity as _gravity
    sympy_deprecation_warning('\n        The gravity function has been moved.\n        Import it from "sympy.physics.mechanics.loads".\n        ', deprecated_since_version='1.13', active_deprecations_target='moved-mechanics-functions')
    return _gravity(acceleration, *bodies)

def center_of_mass(point, *bodies):
    if not bodies:
        raise TypeError('No bodies(instances of Particle or Rigidbody) were passed.')
    total_mass = 0
    vec = Vector(0)
    for i in bodies:
        total_mass += i.mass
        masscenter = getattr(i, 'masscenter', None)
        if masscenter is None:
            masscenter = i.point
        vec += i.mass * masscenter.pos_from(point)
    return vec / total_mass

def Lagrangian(frame, *body):
    if not isinstance(frame, ReferenceFrame):
        raise TypeError('Please supply a valid ReferenceFrame')
    for e in body:
        if not isinstance(e, (RigidBody, Particle)):
            raise TypeError('*body must have only Particle or RigidBody')
    return kinetic_energy(frame, *body) - potential_energy(*body)

def find_dynamicsymbols(expression, exclude=None, reference_frame=None):
    t_set = {dynamicsymbols._t}
    if exclude:
        if iterable(exclude):
            exclude_set = set(exclude)
        else:
            raise TypeError('exclude kwarg must be iterable')
    else:
        exclude_set = set()
    if isinstance(expression, Vector):
        if reference_frame is None:
            raise ValueError('You must provide reference_frame when passing a vector expression, got %s.' % reference_frame)
        else:
            expression = expression.to_matrix(reference_frame)
    return {i for i in expression.atoms(AppliedUndef, Derivative) if i.free_symbols == t_set} - exclude_set

def msubs(expr, *sub_dicts, smart=False, **kwargs):
    sub_dict = dict_merge(*sub_dicts)
    if smart:
        func = _smart_subs
    elif hasattr(expr, 'msubs'):
        return expr.msubs(sub_dict)
    else:
        func = lambda expr, sub_dict: _crawl(expr, _sub_func, sub_dict)
    if isinstance(expr, (Matrix, Vector, Dyadic)):
        return expr.applyfunc(lambda x: func(x, sub_dict))
    else:
        return func(expr, sub_dict)

def _crawl(expr, func, *args, **kwargs):
    val = func(expr, *args, **kwargs)
    if val is not None:
        return val
    new_args = (_crawl(arg, func, *args, **kwargs) for arg in expr.args)
    return expr.func(*new_args)

def _sub_func(expr, sub_dict):
    if expr in sub_dict:
        return sub_dict[expr]
    elif not expr.args or expr.is_Derivative:
        return expr

def _tan_repl_func(expr):
    if isinstance(expr, tan):
        return sin(*expr.args) / cos(*expr.args)
    elif not expr.args or expr.is_Derivative:
        return expr

def _smart_subs(expr, sub_dict):
    expr = _crawl(expr, _tan_repl_func)

    def _recurser(expr, sub_dict):
        num, den = _fraction_decomp(expr)
        if den != 1:
            denom_subbed = _recurser(den, sub_dict)
            if denom_subbed.evalf() == 0:
                expr = simplify(expr)
            else:
                num_subbed = _recurser(num, sub_dict)
                return num_subbed / denom_subbed
        val = _sub_func(expr, sub_dict)
        if val is not None:
            return val
        new_args = (_recurser(arg, sub_dict) for arg in expr.args)
        return expr.func(*new_args)
    return _recurser(expr, sub_dict)

def _fraction_decomp(expr):
    if not isinstance(expr, Mul):
        return (expr, 1)
    num = []
    den = []
    for a in expr.args:
        if a.is_Pow and a.args[1] < 0:
            den.append(1 / a)
        else:
            num.append(a)
    if not den:
        return (expr, 1)
    num = Mul(*num)
    den = Mul(*den)
    return (num, den)

def _f_list_parser(fl, ref_frame):

    def flist_iter():
        for pair in fl:
            obj, force = pair
            if isinstance(obj, ReferenceFrame):
                yield (obj.ang_vel_in(ref_frame), force)
            elif isinstance(obj, Point):
                yield (obj.vel(ref_frame), force)
            else:
                raise TypeError('First entry in each forcelist pair must be a point or frame.')
    if not fl:
        vel_list, f_list = ((), ())
    else:
        unzip = lambda l: list(zip(*l)) if l[0] else [(), ()]
        vel_list, f_list = unzip(list(flist_iter()))
    return (vel_list, f_list)

def _validate_coordinates(coordinates=None, speeds=None, check_duplicates=True, is_dynamicsymbols=True, u_auxiliary=None):
    t_set = {dynamicsymbols._t}
    if coordinates is None:
        coordinates = []
    elif not iterable(coordinates):
        coordinates = [coordinates]
    if speeds is None:
        speeds = []
    elif not iterable(speeds):
        speeds = [speeds]
    if u_auxiliary is None:
        u_auxiliary = []
    elif not iterable(u_auxiliary):
        u_auxiliary = [u_auxiliary]
    msgs = []
    if check_duplicates:
        seen = set()
        coord_duplicates = {x for x in coordinates if x in seen or seen.add(x)}
        seen = set()
        speed_duplicates = {x for x in speeds if x in seen or seen.add(x)}
        seen = set()
        aux_duplicates = {x for x in u_auxiliary if x in seen or seen.add(x)}
        overlap_coords = set(coordinates).intersection(speeds)
        overlap_aux = set(coordinates).union(speeds).intersection(u_auxiliary)
        if coord_duplicates:
            msgs.append(f'The generalized coordinates {coord_duplicates} are duplicated, all generalized coordinates should be unique.')
        if speed_duplicates:
            msgs.append(f'The generalized speeds {speed_duplicates} are duplicated, all generalized speeds should be unique.')
        if aux_duplicates:
            msgs.append(f'The auxiliary speeds {aux_duplicates} are duplicated, all auxiliary speeds should be unique.')
        if overlap_coords:
            msgs.append(f'{overlap_coords} are defined as both generalized coordinates and generalized speeds.')
        if overlap_aux:
            msgs.append(f'The auxiliary speeds {overlap_aux} are also defined as generalized coordinates or generalized speeds.')
    if is_dynamicsymbols:
        for coordinate in coordinates:
            if not (isinstance(coordinate, (AppliedUndef, Derivative)) and coordinate.free_symbols == t_set):
                msgs.append(f'Generalized coordinate "{coordinate}" is not a dynamicsymbol.')
        for speed in speeds:
            if not (isinstance(speed, (AppliedUndef, Derivative)) and speed.free_symbols == t_set):
                msgs.append(f'Generalized speed "{speed}" is not a dynamicsymbol.')
        for aux in u_auxiliary:
            if not (isinstance(aux, (AppliedUndef, Derivative)) and aux.free_symbols == t_set):
                msgs.append(f'Auxiliary speed "{aux}" is not a dynamicsymbol.')
    if msgs:
        raise ValueError('\n'.join(msgs))

def _parse_linear_solver(linear_solver):
    if callable(linear_solver):
        return linear_solver
    return lambda A, b: Matrix.solve(A, b, method=linear_solver)

