    @_reset_eom_method
    def u_aux(self, u_aux):
        self._u_aux = self._parse_coordinates(self._objects_to_list(u_aux), True, [], [], 'u_auxiliary')[0]

    @property
    def kdes(self):
        return self._kdes

    @kdes.setter
    @_reset_eom_method
    def kdes(self, kdes):
        kdes = self._objects_to_list(kdes)
        self._kdes = self._parse_expressions(kdes, [], 'kinematic differential equations')

    @property
    def holonomic_constraints(self):
        return self._hol_coneqs

    @holonomic_constraints.setter
    @_reset_eom_method
    def holonomic_constraints(self, constraints):
        constraints = self._objects_to_list(constraints)
        self._hol_coneqs = self._parse_expressions(constraints, [], 'holonomic constraints')

    @property
    def nonholonomic_constraints(self):
        return self._nonhol_coneqs

    @nonholonomic_constraints.setter
    @_reset_eom_method
    def nonholonomic_constraints(self, constraints):
        constraints = self._objects_to_list(constraints)
        self._nonhol_coneqs = self._parse_expressions(constraints, [], 'nonholonomic constraints')

    @property
    def velocity_constraints(self):
        if self._vel_constrs is None:
            return self.holonomic_constraints.diff(dynamicsymbols._t).col_join(self.nonholonomic_constraints)
        return self._vel_constrs

    @velocity_constraints.setter
    @_reset_eom_method
    def velocity_constraints(self, constraints):
        if constraints is None:
            self._vel_constrs = None
            return
        constraints = self._objects_to_list(constraints)
        self._vel_constrs = self._parse_expressions(constraints, [], 'velocity constraints')

    @property
    def eom_method(self):
        return self._eom_method

    @staticmethod
    def _objects_to_list(lst):
        if not iterable(lst):
            return [lst]
        return list(lst[:])

    @staticmethod
    def _check_objects(objects, obj_lst, expected_type, obj_name, type_name):
        seen = set(obj_lst)
        duplicates = set()
        wrong_types = set()
        for obj in objects:
            if not isinstance(obj, expected_type):
                wrong_types.add(obj)
            if obj in seen:
                duplicates.add(obj)
            else:
                seen.add(obj)
        if wrong_types:
            raise TypeError(f'{obj_name} {wrong_types} are not {type_name}.')
        if duplicates:
            raise ValueError(f'{obj_name} {duplicates} have already been added to the system.')

    def _parse_coordinates(self, new_coords, independent, old_coords_ind, old_coords_dep, coord_type='coordinates'):
        coords_ind, coords_dep = (old_coords_ind[:], old_coords_dep[:])
        if not iterable(independent):
            independent = [independent] * len(new_coords)
        for coord, indep in zip(new_coords, independent):
            if indep:
                coords_ind.append(coord)
            else:
                coords_dep.append(coord)
        current = {'coordinates': self.q_ind[:] + self.q_dep[:], 'speeds': self.u_ind[:] + self.u_dep[:], 'u_auxiliary': self._u_aux[:], coord_type: coords_ind + coords_dep}
        _validate_coordinates(**current)
        return (ImmutableMatrix(1, len(coords_ind), coords_ind).T, ImmutableMatrix(1, len(coords_dep), coords_dep).T)

    @staticmethod
    def _parse_expressions(new_expressions, old_expressions, name, check_negatives=False):
        old_expressions = old_expressions[:]
        new_expressions = list(new_expressions)
        if check_negatives:
            check_exprs = old_expressions + [-expr for expr in old_expressions]
        else:
            check_exprs = old_expressions
        System._check_objects(new_expressions, check_exprs, Basic, name, 'expressions')
        for expr in new_expressions:
            if expr == 0:
                raise ValueError(f'Parsed {name} are zero.')
        return ImmutableMatrix(1, len(old_expressions) + len(new_expressions), old_expressions + new_expressions).T

    @_reset_eom_method
    def add_coordinates(self, *coordinates, independent=True):
        self._q_ind, self._q_dep = self._parse_coordinates(coordinates, independent, self.q_ind, self.q_dep, 'coordinates')

    @_reset_eom_method
    def add_speeds(self, *speeds, independent=True):
        self._u_ind, self._u_dep = self._parse_coordinates(speeds, independent, self.u_ind, self.u_dep, 'speeds')

    @_reset_eom_method
    def add_auxiliary_speeds(self, *speeds):
        self._u_aux = self._parse_coordinates(speeds, True, self._u_aux, [], 'u_auxiliary')[0]

    @_reset_eom_method
    def add_kdes(self, *kdes):
        self._kdes = self._parse_expressions(kdes, self.kdes, 'kinematic differential equations', check_negatives=True)

    @_reset_eom_method
    def add_holonomic_constraints(self, *constraints):
        self._hol_coneqs = self._parse_expressions(constraints, self._hol_coneqs, 'holonomic constraints', check_negatives=True)

    @_reset_eom_method
    def add_nonholonomic_constraints(self, *constraints):
        self._nonhol_coneqs = self._parse_expressions(constraints, self._nonhol_coneqs, 'nonholonomic constraints', check_negatives=True)

    @_reset_eom_method
    def add_bodies(self, *bodies):
        self._check_objects(bodies, self.bodies, BodyBase, 'Bodies', 'bodies')
        self._bodies.extend(bodies)

    @_reset_eom_method
    def add_loads(self, *loads):
        loads = [_parse_load(load) for load in loads]
        self._loads.extend(loads)

    @_reset_eom_method
    def apply_uniform_gravity(self, acceleration):
        self.add_loads(*gravity(acceleration, *self.bodies))

    @_reset_eom_method
    def add_actuators(self, *actuators):
        self._check_objects(actuators, self.actuators, ActuatorBase, 'Actuators', 'actuators')
        self._actuators.extend(actuators)

    @_reset_eom_method
    def add_joints(self, *joints):
        self._check_objects(joints, self.joints, Joint, 'Joints', 'joints')
        self._joints.extend(joints)
        coordinates, speeds, kdes, bodies = (OrderedSet() for _ in range(4))
        for joint in joints:
            coordinates.update(joint.coordinates)
            speeds.update(joint.speeds)
            kdes.update(joint.kdes)
            bodies.update((joint.parent, joint.child))
        coordinates = coordinates.difference(self.q)
        speeds = speeds.difference(self.u)
        kdes = kdes.difference(self.kdes[:] + (-self.kdes)[:])
        bodies = bodies.difference(self.bodies)
        self.add_coordinates(*tuple(coordinates))
        self.add_speeds(*tuple(speeds))
        self.add_kdes(*(kde for kde in tuple(kdes) if not kde == 0))
        self.add_bodies(*tuple(bodies))

    def get_body(self, name):
        for body in self._bodies:
            if body.name == name:
                return body

    def get_joint(self, name):
        for joint in self._joints:
            if joint.name == name:
                return joint

    def _form_eoms(self):
        return self.form_eoms()

    def form_eoms(self, eom_method=KanesMethod, **kwargs):
        loads = self.loads + tuple((load for act in self.actuators for load in act.to_loads()))
        loads = loads if loads else None
        if issubclass(eom_method, KanesMethod):
            disallowed_kwargs = {'frame', 'q_ind', 'u_ind', 'kd_eqs', 'q_dependent', 'u_dependent', 'u_auxiliary', 'configuration_constraints', 'velocity_constraints', 'forcelist', 'bodies'}
            wrong_kwargs = disallowed_kwargs.intersection(kwargs)
            if wrong_kwargs:
                raise ValueError(f'The following keyword arguments are not allowed to be overwritten in {eom_method.__name__}: {wrong_kwargs}.')
            kwargs = {'frame': self.frame, 'q_ind': self.q_ind, 'u_ind': self.u_ind, 'kd_eqs': self.kdes, 'q_dependent': self.q_dep, 'u_dependent': self.u_dep, 'configuration_constraints': self.holonomic_constraints, 'velocity_constraints': self.velocity_constraints, 'u_auxiliary': self.u_aux, 'forcelist': loads, 'bodies': self.bodies, 'explicit_kinematics': False, **kwargs}
            self._eom_method = eom_method(**kwargs)
        elif issubclass(eom_method, LagrangesMethod):
            disallowed_kwargs = {'frame', 'qs', 'forcelist', 'bodies', 'hol_coneqs', 'nonhol_coneqs', 'Lagrangian'}
            wrong_kwargs = disallowed_kwargs.intersection(kwargs)
            if wrong_kwargs:
                raise ValueError(f'The following keyword arguments are not allowed to be overwritten in {eom_method.__name__}: {wrong_kwargs}.')
            kwargs = {'frame': self.frame, 'qs': self.q, 'forcelist': loads, 'bodies': self.bodies, 'hol_coneqs': self.holonomic_constraints, 'nonhol_coneqs': self.nonholonomic_constraints, **kwargs}
            if 'Lagrangian' not in kwargs:
                kwargs['Lagrangian'] = Lagrangian(kwargs['frame'], *kwargs['bodies'])
            self._eom_method = eom_method(**kwargs)
        else:
            raise NotImplementedError(f'{eom_method} has not been implemented.')
        return self.eom_method._form_eoms()

    def rhs(self, inv_method=None):
        return self.eom_method.rhs(inv_method=inv_method)

    @property
    def mass_matrix(self):
        return self.eom_method.mass_matrix

    @property
    def mass_matrix_full(self):
        return self.eom_method.mass_matrix_full

    @property
    def forcing(self):
        return self.eom_method.forcing

    @property
    def forcing_full(self):
        return self.eom_method.forcing_full

    def validate_system(self, eom_method=KanesMethod, check_duplicates=False):
        msgs = []
        n_hc = self.holonomic_constraints.shape[0]
        n_vc = self.velocity_constraints.shape[0]
        n_q_dep, n_u_dep = (self.q_dep.shape[0], self.u_dep.shape[0])
        q_set, u_set = (set(self.q), set(self.u))
        n_q, n_u = (len(q_set), len(u_set))
        if n_q_dep != n_hc:
            msgs.append(filldedent(f'\n            The number of dependent generalized coordinates {n_q_dep} should be\n            equal to the number of holonomic constraints {n_hc}.'))
        missing_q = set()
        for joint in self.joints:
            missing_q.update(set(joint.coordinates).difference(q_set))
        if missing_q:
            msgs.append(filldedent(f'\n            The generalized coordinates {missing_q} used in joints are not added\n            to the system.'))
        if issubclass(eom_method, KanesMethod):
            n_kdes = len(self.kdes)
            missing_kdes, missing_u = (set(), set())
            for joint in self.joints:
                missing_u.update(set(joint.speeds).difference(u_set))
                missing_kdes.update(set(joint.kdes).difference(self.kdes[:] + (-self.kdes)[:]))
            if missing_u:
                msgs.append(filldedent(f'\n                The generalized speeds {missing_u} used in joints are not added\n                to the system.'))
            if missing_kdes:
                msgs.append(filldedent(f'\n                The kinematic differential equations {missing_kdes} used in\n                joints are not added to the system.'))
            if n_u_dep != n_vc:
                msgs.append(filldedent(f'\n                The number of dependent generalized speeds {n_u_dep} should be\n                equal to the number of velocity constraints {n_vc}.'))
            if n_q > n_u:
                msgs.append(filldedent(f'\n                The number of generalized coordinates {n_q} should be less than\n                or equal to the number of generalized speeds {n_u}.'))
            if n_u != n_kdes:
                msgs.append(filldedent(f'\n                The number of generalized speeds {n_u} should be equal to the\n                number of kinematic differential equations {n_kdes}.'))
        elif issubclass(eom_method, LagrangesMethod):
            not_qdots = set(self.u).difference(self.q.diff(dynamicsymbols._t))
            for joint in self.joints:
                not_qdots.update(set(joint.speeds).difference(self.q.diff(dynamicsymbols._t)))
            if not_qdots:
                msgs.append(filldedent(f'\n                The generalized speeds {not_qdots} are not supported by this\n                method. Only derivatives of the generalized coordinates are\n                supported. If these symbols are used in your expressions, then\n                this will result in wrong equations of motion.'))
            if self.u_aux:
                msgs.append(filldedent(f'\n                This method does not support auxiliary speeds. If these symbols\n                are used in your expressions, then this will result in wrong\n                equations of motion. The auxiliary speeds are {self.u_aux}.'))
        else:
            raise NotImplementedError(f'{eom_method} has not been implemented.')
        if check_duplicates:
            duplicates_to_check = [('generalized coordinates', self.q), ('generalized speeds', self.u), ('auxiliary speeds', self.u_aux), ('bodies', self.bodies), ('joints', self.joints)]
            for name, lst in duplicates_to_check:
                seen = set()
                duplicates = {x for x in lst if x in seen or seen.add(x)}
                if duplicates:
                    msgs.append(filldedent(f'\n                    The {name} {duplicates} exist multiple times within the\n                    system.'))
        if msgs:
            raise ValueError('\n'.join(msgs))

class SymbolicSystem:

    def __init__(self, coord_states, right_hand_side, speeds=None, mass_matrix=None, coordinate_derivatives=None, alg_con=None, output_eqns={}, coord_idxs=None, speed_idxs=None, bodies=None, loads=None):
        if speeds is None:
            self._states = Matrix(coord_states)
            if coord_idxs is None:
                self._coordinates = None
            else:
                coords = [coord_states[i] for i in coord_idxs]
                self._coordinates = Matrix(coords)
            if speed_idxs is None:
                self._speeds = None
            else:
                speeds_inter = [coord_states[i] for i in speed_idxs]
                self._speeds = Matrix(speeds_inter)
        else:
            self._coordinates = Matrix(coord_states)
            self._speeds = Matrix(speeds)
            self._states = self._coordinates.col_join(self._speeds)
        if coordinate_derivatives is not None:
            self._kin_explicit_rhs = coordinate_derivatives
            self._dyn_implicit_rhs = right_hand_side
            self._dyn_implicit_mat = mass_matrix
            self._comb_implicit_rhs = None
            self._comb_implicit_mat = None
            self._comb_explicit_rhs = None
        elif mass_matrix is not None:
            self._kin_explicit_rhs = None
            self._dyn_implicit_rhs = None
            self._dyn_implicit_mat = None
            self._comb_implicit_rhs = right_hand_side
            self._comb_implicit_mat = mass_matrix
            self._comb_explicit_rhs = None
        else:
            self._kin_explicit_rhs = None
            self._dyn_implicit_rhs = None
            self._dyn_implicit_mat = None
            self._comb_implicit_rhs = None
            self._comb_implicit_mat = None
            self._comb_explicit_rhs = right_hand_side
        if alg_con is not None and coordinate_derivatives is not None:
            alg_con = [i + len(coordinate_derivatives) for i in alg_con]
        self._alg_con = alg_con
        self.output_eqns = output_eqns
        if not isinstance(bodies, tuple) and bodies is not None:
            bodies = tuple(bodies)
        if not isinstance(loads, tuple) and loads is not None:
            loads = tuple(loads)
        self._bodies = bodies
        self._loads = loads

    @property
    def coordinates(self):
        if self._coordinates is None:
            raise AttributeError('The coordinates were not specified.')
        else:
            return self._coordinates

    @property
    def speeds(self):
        if self._speeds is None:
            raise AttributeError('The speeds were not specified.')
        else:
            return self._speeds

    @property
    def states(self):
        return self._states

    @property
    def alg_con(self):
        return self._alg_con

    @property
    def dyn_implicit_mat(self):
        if self._dyn_implicit_mat is None:
            raise AttributeError('dyn_implicit_mat is not specified for equations of motion form [1] or [2].')
        else:
            return self._dyn_implicit_mat

    @property
    def dyn_implicit_rhs(self):
        if self._dyn_implicit_rhs is None:
            raise AttributeError('dyn_implicit_rhs is not specified for equations of motion form [1] or [2].')
        else:
            return self._dyn_implicit_rhs

    @property
    def comb_implicit_mat(self):
        if self._comb_implicit_mat is None:
            if self._dyn_implicit_mat is not None:
                num_kin_eqns = len(self._kin_explicit_rhs)
                num_dyn_eqns = len(self._dyn_implicit_rhs)
                zeros1 = zeros(num_kin_eqns, num_dyn_eqns)
                zeros2 = zeros(num_dyn_eqns, num_kin_eqns)
                inter1 = eye(num_kin_eqns).row_join(zeros1)
                inter2 = zeros2.row_join(self._dyn_implicit_mat)
                self._comb_implicit_mat = inter1.col_join(inter2)
                return self._comb_implicit_mat
            else:
                raise AttributeError('comb_implicit_mat is not specified for equations of motion form [1].')
        else:
            return self._comb_implicit_mat

    @property
    def comb_implicit_rhs(self):
        if self._comb_implicit_rhs is None:
            if self._dyn_implicit_rhs is not None:
                kin_inter = self._kin_explicit_rhs
                dyn_inter = self._dyn_implicit_rhs
                self._comb_implicit_rhs = kin_inter.col_join(dyn_inter)
                return self._comb_implicit_rhs
            else:
                raise AttributeError('comb_implicit_mat is not specified for equations of motion in form [1].')
        else:
            return self._comb_implicit_rhs

    def compute_explicit_form(self):
        if self._comb_explicit_rhs is not None:
            raise AttributeError('comb_explicit_rhs is already formed.')
        inter1 = getattr(self, 'kin_explicit_rhs', None)
        if inter1 is not None:
            inter2 = self._dyn_implicit_mat.LUsolve(self._dyn_implicit_rhs)
            out = inter1.col_join(inter2)
        else:
            out = self._comb_implicit_mat.LUsolve(self._comb_implicit_rhs)
        self._comb_explicit_rhs = out

    @property
    def comb_explicit_rhs(self):
        if self._comb_explicit_rhs is None:
            raise AttributeError('Please run .combute_explicit_form before attempting to access comb_explicit_rhs.')
        else:
            return self._comb_explicit_rhs

    @property
    def kin_explicit_rhs(self):
        if self._kin_explicit_rhs is None:
            raise AttributeError('kin_explicit_rhs is not specified for equations of motion form [1] or [2].')
        else:
            return self._kin_explicit_rhs

    def dynamic_symbols(self):
        if self._comb_explicit_rhs is None:
            eom_expressions = self.comb_implicit_mat[:] + self.comb_implicit_rhs[:]
        else:
            eom_expressions = self._comb_explicit_rhs[:]
        functions_of_time = set()
        for expr in eom_expressions:
            functions_of_time = functions_of_time.union(find_dynamicsymbols(expr))
        functions_of_time = functions_of_time.union(self._states)
        return tuple(functions_of_time)

    def constant_symbols(self):
        if self._comb_explicit_rhs is None:
            eom_expressions = self.comb_implicit_mat[:] + self.comb_implicit_rhs[:]
        else:
            eom_expressions = self._comb_explicit_rhs[:]
        constants = set()
        for expr in eom_expressions:
            constants = constants.union(expr.free_symbols)
        constants.remove(dynamicsymbols._t)
        return tuple(constants)

    @property
    def bodies(self):
        if self._bodies is None:
            raise AttributeError('bodies were not specified for the system.')
        else:
            return self._bodies

    @property
    def loads(self):
        if self._loads is None:
            raise AttributeError('loads were not specified for the system.')
        else:
            return self._loads

