    return CircuitPlot(c, nqubits, **kwargs)

def render_label(label, inits={}):
    init = inits.get(label)
    if init:
        return '$\\left|%s\\right\\rangle=\\left|%s\\right\\rangle$' % (label, init)
    return '$\\left|%s\\right\\rangle$' % label

def labeller(n, symbol='q'):
    return ['%s_%d' % (symbol, n - i - 1) for i in range(n)]

class Mz(OneQubitGate):
    measurement = True
    gate_name = 'Mz'
    gate_name_latex = 'M_z'

class Mx(OneQubitGate):
    measurement = True
    gate_name = 'Mx'
    gate_name_latex = 'M_x'

class CreateOneQubitGate(type):

    def __new__(mcl, name, latexname=None):
        if not latexname:
            latexname = name
        return type(name + 'Gate', (OneQubitGate,), {'gate_name': name, 'gate_name_latex': latexname})

def CreateCGate(name, latexname=None):
    if not latexname:
        latexname = name
    onequbitgate = CreateOneQubitGate(name, latexname)

    def ControlledGate(ctrls, target):
        return CGate(tuple(ctrls), onequbitgate(target))
    return ControlledGate

