def matrix_to_qubit(matrix):
    format = 'sympy'
    if isinstance(matrix, numpy_ndarray):
        format = 'numpy'
    if isinstance(matrix, scipy_sparse_matrix):
        format = 'scipy.sparse'
    if matrix.shape[0] == 1:
        mlistlen = matrix.shape[1]
        nqubits = log(mlistlen, 2)
        ket = False
        cls = QubitBra
    elif matrix.shape[1] == 1:
        mlistlen = matrix.shape[0]
        nqubits = log(mlistlen, 2)
        ket = True
        cls = Qubit
    else:
        raise QuantumError('Matrix must be a row/column vector, got %r' % matrix)
    if not isinstance(nqubits, Integer):
        raise QuantumError('Matrix must be a row/column vector of size 2**nqubits, got: %r' % matrix)
    result = 0
    for i in range(mlistlen):
        if ket:
            element = matrix[i, 0]
        else:
            element = matrix[0, i]
        if format in ('numpy', 'scipy.sparse'):
            element = complex(element)
        if element:
            qubit_array = [int(i & 1 << x != 0) for x in range(nqubits)]
            qubit_array.reverse()
            result = result + element * cls(*qubit_array)
    if isinstance(result, (Mul, Add, Pow)):
        result = result.expand()
    return result

def matrix_to_density(mat):
    from sympy.physics.quantum.density import Density
    eigen = mat.eigenvects()
    args = [[matrix_to_qubit(Matrix([vector])), x[0]] for x in eigen for vector in x[2] if x[0] != 0]
    if len(args) == 0:
        return S.Zero
    else:
        return Density(*args)

def qubit_to_matrix(qubit, format='sympy'):
    return represent(qubit, format=format)

def measure_all(qubit, format='sympy', normalize=True):
    m = qubit_to_matrix(qubit, format)
    if format == 'sympy':
        results = []
        if normalize:
            m = m.normalized()
        size = max(m.shape)
        nqubits = int(math.log(size) / math.log(2))
        for i in range(size):
            if m[i]:
                results.append((Qubit(IntQubit(i, nqubits=nqubits)), m[i] * conjugate(m[i])))
        return results
    else:
        raise NotImplementedError('This function cannot handle non-SymPy matrix formats yet')

def measure_partial(qubit, bits, format='sympy', normalize=True):
    m = qubit_to_matrix(qubit, format)
    if isinstance(bits, (SYMPY_INTS, Integer)):
        bits = (int(bits),)
    if format == 'sympy':
        if normalize:
            m = m.normalized()
        possible_outcomes = _get_possible_outcomes(m, bits)
        output = []
        for outcome in possible_outcomes:
            prob_of_outcome = 0
            prob_of_outcome += (outcome.H * outcome)[0]
            if prob_of_outcome != 0:
                if normalize:
                    next_matrix = matrix_to_qubit(outcome.normalized())
                else:
                    next_matrix = matrix_to_qubit(outcome)
                output.append((next_matrix, prob_of_outcome))
        return output
    else:
        raise NotImplementedError('This function cannot handle non-SymPy matrix formats yet')

def measure_partial_oneshot(qubit, bits, format='sympy'):
    import random
    m = qubit_to_matrix(qubit, format)
    if format == 'sympy':
        m = m.normalized()
        possible_outcomes = _get_possible_outcomes(m, bits)
        random_number = random.random()
        total_prob = 0
        for outcome in possible_outcomes:
            total_prob += (outcome.H * outcome)[0]
            if total_prob >= random_number:
                return matrix_to_qubit(outcome.normalized())
    else:
        raise NotImplementedError('This function cannot handle non-SymPy matrix formats yet')

def _get_possible_outcomes(m, bits):
    size = max(m.shape)
    nqubits = int(math.log2(size) + 0.1)
    output_matrices = []
    for i in range(1 << len(bits)):
        output_matrices.append(zeros(2 ** nqubits, 1))
    bit_masks = []
    for bit in bits:
        bit_masks.append(1 << bit)
    for i in range(2 ** nqubits):
        trueness = 0
        for j in range(len(bit_masks)):
            if i & bit_masks[j]:
                trueness += j + 1
        output_matrices[trueness][i] = m[i]
    return output_matrices

def measure_all_oneshot(qubit, format='sympy'):
    import random
    m = qubit_to_matrix(qubit)
    if format == 'sympy':
        m = m.normalized()
        random_number = random.random()
        total = 0
        result = 0
        for i in m:
            total += i * i.conjugate()
            if total > random_number:
                break
            result += 1
        return Qubit(IntQubit(result, int(math.log2(max(m.shape)) + 0.1)))
    else:
        raise NotImplementedError('This function cannot handle non-SymPy matrix formats yet')

