from sympy.core.add import Add
from sympy.core.containers import Tuple
from sympy.core.expr import Expr
from sympy.core.mul import Mul
from sympy.core.power import Pow
from sympy.core.sorting import default_sort_key
from sympy.core.sympify import sympify
from sympy.matrices import Matrix

def _is_scalar(e):
    e = sympify(e)
    if isinstance(e, Expr):
        if e.is_Integer or e.is_Float or e.is_Rational or e.is_Number or (e.is_Symbol and e.is_commutative):
            return True
    return False

def _cycle_permute(l):
    if len(l) == 1:
        return l
    min_item = min(l, key=default_sort_key)
    indices = [i for i, x in enumerate(l) if x == min_item]
    le = list(l)
    le.extend(l)
    indices.append(len(l) + indices[0])
    sublist = [[le[indices[i]:indices[i + 1]]] for i in range(len(indices) - 1)]
    idx = sublist.index(min(sublist))
    ordered_l = le[indices[idx]:indices[idx] + len(l)]
    return ordered_l

def _rearrange_args(l):
    if len(l) == 1:
        return l
    x = list(l[-1:])
    x.extend(l[0:-1])
    return Mul(*x).args

class Tr(Expr):

    def __new__(cls, *args):
        if len(args) == 2:
            if not isinstance(args[1], (list, Tuple, tuple)):
                indices = Tuple(args[1])
            else:
                indices = Tuple(*args[1])
            expr = args[0]
        elif len(args) == 1:
            indices = Tuple()
            expr = args[0]
        else:
            raise ValueError('Arguments to Tr should be of form (expr[, [indices]])')
        if isinstance(expr, Matrix):
            return expr.trace()
        elif hasattr(expr, 'trace') and callable(expr.trace):
            return expr.trace()
        elif isinstance(expr, Add):
            return Add(*[Tr(arg, indices) for arg in expr.args])
        elif isinstance(expr, Mul):
            c_part, nc_part = expr.args_cnc()
            if len(nc_part) == 0:
                return Mul(*c_part)
            else:
                obj = Expr.__new__(cls, Mul(*nc_part), indices)
                return Mul(*c_part) * obj if len(c_part) > 0 else obj
        elif isinstance(expr, Pow):
            if _is_scalar(expr.args[0]) and _is_scalar(expr.args[1]):
                return expr
            else:
                return Expr.__new__(cls, expr, indices)
        else:
