from sympy.printing.defaults import Printable
from mpmath.libmp.libmpf import prec_to_dps
__all__ = ['Dyadic']

class Dyadic(Printable, EvalfMixin):
    is_number = False

    def __init__(self, inlist):
        self.args = []
        if inlist == 0:
            inlist = []
        while len(inlist) != 0:
            added = 0
            for i, v in enumerate(self.args):
                if str(inlist[0][1]) == str(self.args[i][1]) and str(inlist[0][2]) == str(self.args[i][2]):
                    self.args[i] = (self.args[i][0] + inlist[0][0], inlist[0][1], inlist[0][2])
                    inlist.remove(inlist[0])
                    added = 1
                    break
            if added != 1:
                self.args.append(inlist[0])
                inlist.remove(inlist[0])
        i = 0
        while i < len(self.args):
            if (self.args[i][0] == 0) | (self.args[i][1] == 0) | (self.args[i][2] == 0):
                self.args.remove(self.args[i])
                i -= 1
            i += 1

    @property
    def func(self):
        return Dyadic

    def __add__(self, other):
        other = _check_dyadic(other)
        return Dyadic(self.args + other.args)
    __radd__ = __add__

    def __mul__(self, other):
        newlist = list(self.args)
        other = sympify(other)
        for i, v in enumerate(newlist):
            newlist[i] = (other * newlist[i][0], newlist[i][1], newlist[i][2])
        return Dyadic(newlist)
    __rmul__ = __mul__

    def dot(self, other):
        from sympy.physics.vector.vector import Vector, _check_vector
        if isinstance(other, Dyadic):
            other = _check_dyadic(other)
            ol = Dyadic(0)
            for v in self.args:
                for v2 in other.args:
                    ol += v[0] * v2[0] * v[2].dot(v2[1]) * v[1].outer(v2[2])
        else:
            other = _check_vector(other)
            ol = Vector(0)
            for v in self.args:
                ol += v[0] * v[1] * v[2].dot(other)
        return ol
    __and__ = dot

    def __truediv__(self, other):
        return self.__mul__(1 / other)

    def __eq__(self, other):
        if other == 0:
            other = Dyadic(0)
        other = _check_dyadic(other)
        if self.args == [] and other.args == []:
            return True
        elif self.args == [] or other.args == []:
            return False
        return set(self.args) == set(other.args)

    def __ne__(self, other):
        return not self == other

    def __neg__(self):
        return self * -1

    def _latex(self, printer):
        ar = self.args
        if len(ar) == 0:
            return str(0)
        ol = []
        for i, v in enumerate(ar):
            if ar[i][0] == 1:
                ol.append(' + ' + printer._print(ar[i][1]) + '\\otimes ' + printer._print(ar[i][2]))
            elif ar[i][0] == -1:
