from sympy.core.function import Derivative
from sympy.core.function import UndefinedFunction, AppliedUndef
from sympy.core.symbol import Symbol
from sympy.interactive.printing import init_printing
from sympy.printing.latex import LatexPrinter
from sympy.printing.pretty.pretty import PrettyPrinter
from sympy.printing.pretty.pretty_symbology import center_accent
from sympy.printing.str import StrPrinter
from sympy.printing.precedence import PRECEDENCE
__all__ = ['vprint', 'vsstrrepr', 'vsprint', 'vpprint', 'vlatex', 'init_vprinting']

class VectorStrPrinter(StrPrinter):

    def _print_Derivative(self, e):
        from sympy.physics.vector.functions import dynamicsymbols
        t = dynamicsymbols._t
        if bool(sum((i == t for i in e.variables))) & isinstance(type(e.args[0]), UndefinedFunction):
            ol = str(e.args[0].func)
            for i, v in enumerate(e.variables):
                ol += dynamicsymbols._str
            return ol
        else:
            return StrPrinter().doprint(e)

    def _print_Function(self, e):
        from sympy.physics.vector.functions import dynamicsymbols
        t = dynamicsymbols._t
        if isinstance(type(e), UndefinedFunction):
            return StrPrinter().doprint(e).replace('(%s)' % t, '')
        return e.func.__name__ + '(%s)' % self.stringify(e.args, ', ')

class VectorStrReprPrinter(VectorStrPrinter):

    def _print_str(self, s):
        return repr(s)

class VectorLatexPrinter(LatexPrinter):

    def _print_Function(self, expr, exp=None):
        from sympy.physics.vector.functions import dynamicsymbols
        func = expr.func.__name__
        t = dynamicsymbols._t
        if hasattr(self, '_print_' + func) and (not isinstance(type(expr), UndefinedFunction)):
            return getattr(self, '_print_' + func)(expr, exp)
        elif isinstance(type(expr), UndefinedFunction) and expr.args == (t,):
            expr = Symbol(func)
            if exp is not None:
                base = self.parenthesize(expr, PRECEDENCE['Pow'])
                base = self.parenthesize_super(base)
                return '%s^{%s}' % (base, exp)
            else:
                return super()._print(expr)
        else:
            return super()._print_Function(expr, exp)

    def _print_Derivative(self, der_expr):
        from sympy.physics.vector.functions import dynamicsymbols
        der_expr = der_expr.doit()
        if not isinstance(der_expr, Derivative):
            return '\\left(%s\\right)' % self.doprint(der_expr)
        t = dynamicsymbols._t
        expr = der_expr.expr
        red = expr.atoms(AppliedUndef)
        syms = der_expr.variables
        test1 = not all((True for i in red if i.free_symbols == {t}))
        test2 = not all((t == i for i in syms))
        if test1 or test2:
            return super()._print_Derivative(der_expr)
        dots = len(syms)
        base = self._print_Function(expr)
        base_split = base.split('_', 1)
        base = base_split[0]
        if dots == 1:
            base = '\\dot{%s}' % base
        elif dots == 2:
            base = '\\ddot{%s}' % base
        elif dots == 3:
            base = '\\dddot{%s}' % base
        elif dots == 4:
            base = '\\ddddot{%s}' % base
        else:
            return super()._print_Derivative(der_expr)
        if len(base_split) != 1:
            base += '_' + base_split[1]
        return base

class VectorPrettyPrinter(PrettyPrinter):

    def _print_Derivative(self, deriv):
        from sympy.physics.vector.functions import dynamicsymbols
        t = dynamicsymbols._t
        dot_i = 0
        syms = list(reversed(deriv.variables))
        while len(syms) > 0:
            if syms[-1] == t:
                syms.pop()
                dot_i += 1
            else:
                return super()._print_Derivative(deriv)
        if not (isinstance(type(deriv.expr), UndefinedFunction) and deriv.expr.args == (t,)):
            return super()._print_Derivative(deriv)
        else:
            pform = self._print_Function(deriv.expr)
        if len(pform.picture) > 1:
            return super()._print_Derivative(deriv)
        if dot_i >= 5:
            return super()._print_Derivative(deriv)
        dots = {0: '', 1: '̇', 2: '̈', 3: '⃛', 4: '⃜'}
        d = pform.__dict__
        if not self._use_unicode:
            apostrophes = ''
            for i in range(0, dot_i):
                apostrophes += "'"
            d['picture'][0] += apostrophes + '(t)'
        else:
            d['picture'] = [center_accent(d['picture'][0], dots[dot_i])]
        return pform

    def _print_Function(self, e):
        from sympy.physics.vector.functions import dynamicsymbols
        t = dynamicsymbols._t
        func = e.func
        args = e.args
        func_name = func.__name__
        pform = self._print_Symbol(Symbol(func_name))
        if not (isinstance(func, UndefinedFunction) and args == (t,)):
            return super()._print_Function(e)
        return pform

def vprint(expr, **settings):
    outstr = vsprint(expr, **settings)
    import builtins
    if outstr != 'None':
        builtins._ = outstr
        print(outstr)

def vsstrrepr(expr, **settings):
    p = VectorStrReprPrinter(settings)
    return p.doprint(expr)

def vsprint(expr, **settings):
    string_printer = VectorStrPrinter(settings)
    return string_printer.doprint(expr)

def vpprint(expr, **settings):
    pp = VectorPrettyPrinter(settings)
    use_unicode = pp._settings['use_unicode']
    from sympy.printing.pretty.pretty_symbology import pretty_use_unicode
    uflag = pretty_use_unicode(use_unicode)
    try:
        return pp.doprint(expr)
    finally:
        pretty_use_unicode(uflag)

def vlatex(expr, **settings):
    latex_printer = VectorLatexPrinter(settings)
    return latex_printer.doprint(expr)

def init_vprinting(**kwargs):
    kwargs['str_printer'] = vsstrrepr
    kwargs['pretty_printer'] = vpprint
    kwargs['latex_printer'] = vlatex
    init_printing(**kwargs)
params = init_printing.__doc__.split('Examples\n    ========')[0]
init_vprinting.__doc__ = init_vprinting.__doc__.format(params)

