class IntervalMathPrinter(PythonCodePrinter):

    def _print_And(self, expr):
        PREC = precedence(expr)
        return ' & '.join((self.parenthesize(a, PREC) for a in sorted(expr.args, key=default_sort_key)))

    def _print_Or(self, expr):
