        is_finite = lambda lim: all((getattr(i, 'is_finite', True) for i in lim))

        def check_and_set(t_name, t):
            if t:
                if not is_real(t):
                    raise ValueError('All numbers from {}={} must be real'.format(t_name, t))
                if not is_finite(t):
                    raise ValueError('All numbers from {}={} must be finite'.format(t_name, t))
                setattr(self, t_name, (float(t[0]), float(t[1])))
        self.xlim = None
        check_and_set('xlim', xlim)
        self.ylim = None
        check_and_set('ylim', ylim)
        self.size = None
        check_and_set('size', size)

