from pyglet.window import Window
from pyglet.clock import Clock
from threading import Thread, Lock
gl_lock = Lock()

class ManagedWindow(Window):
    fps_limit = 30
    default_win_args = {'width': 600, 'height': 500, 'vsync': False, 'resizable': True}

    def __init__(self, **win_args):
        if win_args.get('runfromdoctester', False):
            return
        self.win_args = dict(self.default_win_args, **win_args)
        self.Thread = Thread(target=self.__event_loop__)
        self.Thread.start()

    def __event_loop__(self, **win_args):
        gl_lock.acquire()
        try:
            try:
                super().__init__(**self.win_args)
                self.switch_to()
                self.setup()
            except Exception as e:
                print('Window initialization failed: %s' % str(e))
                self.has_exit = True
        finally:
            gl_lock.release()
        clock = Clock()
        clock.fps_limit = self.fps_limit
        while not self.has_exit:
            dt = clock.tick()
            gl_lock.acquire()
            try:
                try:
                    self.switch_to()
                    self.dispatch_events()
                    self.clear()
                    self.update(dt)
                    self.draw()
                    self.flip()
                except Exception as e:
                    print('Uncaught exception in event loop: %s' % str(e))
                    self.has_exit = True
            finally:
                gl_lock.release()
        super().close()

    def close(self):
        self.has_exit = True

    def setup(self):
        pass

    def update(self, dt):
        pass

    def draw(self):
        pass
if __name__ == '__main__':
    ManagedWindow()

