import random
ninf = float('-inf')

def poly_LC(f, K):
    if not f:
        return K.zero
    else:
        return f[0]

def poly_TC(f, K):
    if not f:
        return K.zero
    else:
        return f[-1]
dup_LC = dmp_LC = poly_LC
dup_TC = dmp_TC = poly_TC

def dmp_ground_LC(f, u, K):
    while u:
        f = dmp_LC(f, K)
        u -= 1
    return dup_LC(f, K)

def dmp_ground_TC(f, u, K):
    while u:
        f = dmp_TC(f, K)
        u -= 1
    return dup_TC(f, K)

