                g.append(c)
    elif K.is_FiniteField:
        pi = int(p)
        g = [K(int(c) % pi) for c in f]
    else:
        g = [c % p for c in f]
    return dup_strip(g)

def dmp_trunc(f, p, u, K):
    return dmp_strip([dmp_rem(c, p, u - 1, K) for c in f], u)

def dmp_ground_trunc(f, p, u, K):
    if not u:
        return dup_trunc(f, p, K)
    v = u - 1
    return dmp_strip([dmp_ground_trunc(c, p, v, K) for c in f], u)

def dup_monic(f, K):
    if not f:
        return f
    lc = dup_LC(f, K)
    if K.is_one(lc):
        return f
    else:
        return dup_exquo_ground(f, lc, K)

def dmp_ground_monic(f, u, K):
    if not u:
        return dup_monic(f, K)
    if dmp_zero_p(f, u):
        return f
    lc = dmp_ground_LC(f, u, K)
    if K.is_one(lc):
        return f
    else:
        return dmp_exquo_ground(f, lc, u, K)

def dup_content(f, K):
    from sympy.polys.domains import QQ
    if not f:
        return K.zero
    cont = K.zero
    if K == QQ:
        for c in f:
            cont = K.gcd(cont, c)
    else:
        for c in f:
            cont = K.gcd(cont, c)
            if K.is_one(cont):
                break
    return cont

def dmp_ground_content(f, u, K):
    from sympy.polys.domains import QQ
    if not u:
        return dup_content(f, K)
    if dmp_zero_p(f, u):
        return K.zero
    cont, v = (K.zero, u - 1)
    if K == QQ:
        for c in f:
            cont = K.gcd(cont, dmp_ground_content(c, v, K))
    else:
        for c in f:
            cont = K.gcd(cont, dmp_ground_content(c, v, K))
            if K.is_one(cont):
                break
    return cont

def dup_primitive(f, K):
    if not f:
        return (K.zero, f)
    cont = dup_content(f, K)
    if K.is_one(cont):
        return (cont, f)
    else:
        return (cont, dup_quo_ground(f, cont, K))

def dmp_ground_primitive(f, u, K):
    if not u:
        return dup_primitive(f, K)
    if dmp_zero_p(f, u):
        return (K.zero, f)
    cont = dmp_ground_content(f, u, K)
    if K.is_one(cont):
        return (cont, f)
    else:
        return (cont, dmp_quo_ground(f, cont, u, K))

def dup_extract(f, g, K):
    fc = dup_content(f, K)
    gc = dup_content(g, K)
    gcd = K.gcd(fc, gc)
    if not K.is_one(gcd):
        f = dup_quo_ground(f, gcd, K)
        g = dup_quo_ground(g, gcd, K)
    return (gcd, f, g)

def dmp_ground_extract(f, g, u, K):
    fc = dmp_ground_content(f, u, K)
    gc = dmp_ground_content(g, u, K)
    gcd = K.gcd(fc, gc)
    if not K.is_one(gcd):
        f = dmp_quo_ground(f, gcd, u, K)
        g = dmp_quo_ground(g, gcd, u, K)
    return (gcd, f, g)

def dup_real_imag(f, K):
    if not K.is_ZZ and (not K.is_QQ):
        raise DomainError('computing real and imaginary parts is not supported over %s' % K)
    f1 = dmp_zero(1)
    f2 = dmp_zero(1)
    if not f:
        return (f1, f2)
    g = [[[K.one, K.zero]], [[K.one], []]]
    h = dmp_ground(f[0], 2)
    for c in f[1:]:
        h = dmp_mul(h, g, 2, K)
        h = dmp_add_term(h, dmp_ground(c, 1), 0, 2, K)
    H = dup_to_raw_dict(h)
    for k, h in H.items():
        m = k % 4
        if not m:
            f1 = dmp_add(f1, h, 1, K)
        elif m == 1:
            f2 = dmp_add(f2, h, 1, K)
        elif m == 2:
            f1 = dmp_sub(f1, h, 1, K)
        else:
            f2 = dmp_sub(f2, h, 1, K)
    return (f1, f2)

def dup_mirror(f, K):
    f = list(f)
    for i in range(len(f) - 2, -1, -2):
        f[i] = -f[i]
    return f

def dup_scale(f, a, K):
    f, n, b = (list(f), len(f) - 1, a)
    for i in range(n - 1, -1, -1):
        f[i], b = (b * f[i], b * a)
    return f

def dup_shift(f, a, K):
    f, n = (list(f), len(f) - 1)
    for i in range(n, 0, -1):
        for j in range(0, i):
            f[j + 1] += a * f[j]
    return f

def dmp_shift(f, a, u, K):
    if not u:
        return dup_shift(f, a[0], K)
    if dmp_zero_p(f, u):
        return f
    a0, a1 = (a[0], a[1:])
    f = [dmp_shift(c, a1, u - 1, K) for c in f]
    n = len(f) - 1
    for i in range(n, 0, -1):
        for j in range(0, i):
            afj = dmp_mul_ground(f[j], a0, u - 1, K)
            f[j + 1] = dmp_add(f[j + 1], afj, u - 1, K)
    return f

def dup_transform(f, p, q, K):
    if not f:
        return []
    n = len(f) - 1
    h, Q = ([f[0]], [[K.one]])
    for i in range(0, n):
        Q.append(dup_mul(Q[-1], q, K))
    for c, q in zip(f[1:], Q[1:]):
        h = dup_mul(h, p, K)
        q = dup_mul_ground(q, c, K)
        h = dup_add(h, q, K)
    return h

def dup_compose(f, g, K):
    if len(g) <= 1:
        return dup_strip([dup_eval(f, dup_LC(g, K), K)])
    if not f:
        return []
    h = [f[0]]
    for c in f[1:]:
        h = dup_mul(h, g, K)
        h = dup_add_term(h, c, 0, K)
    return h

def dmp_compose(f, g, u, K):
    if not u:
        return dup_compose(f, g, K)
    if dmp_zero_p(f, u):
        return f
    h = [f[0]]
    for c in f[1:]:
        h = dmp_mul(h, g, u, K)
        h = dmp_add_term(h, c, 0, u, K)
    return h

def _dup_right_decompose(f, s, K):
    n = len(f) - 1
    lc = dup_LC(f, K)
    f = dup_to_raw_dict(f)
    g = {s: K.one}
    r = n // s
    for i in range(1, s):
        coeff = K.zero
        for j in range(0, i):
            if not n + j - i in f:
                continue
            if not s - j in g:
                continue
            fc, gc = (f[n + j - i], g[s - j])
            coeff += (i - r * j) * fc * gc
        g[s - i] = K.quo(coeff, i * r * lc)
    return dup_from_raw_dict(g, K)

def _dup_left_decompose(f, h, K):
    g, i = ({}, 0)
    while f:
        q, r = dup_div(f, h, K)
        if dup_degree(r) > 0:
            return None
        else:
            g[i] = dup_LC(r, K)
            f, i = (q, i + 1)
    return dup_from_raw_dict(g, K)

def _dup_decompose(f, K):
    df = len(f) - 1
    for s in range(2, df):
        if df % s != 0:
            continue
        h = _dup_right_decompose(f, s, K)
        if h is not None:
            g = _dup_left_decompose(f, h, K)
            if g is not None:
                return (g, h)
    return None

def dup_decompose(f, K):
    F = []
    while True:
        result = _dup_decompose(f, K)
        if result is not None:
            f, h = result
            F = [h] + F
        else:
            break
    return [f] + F

def dmp_lift(f, u, K):
    if K.is_GaussianField:
        K1 = K.as_AlgebraicField()
        f = dmp_convert(f, u, K, K1)
        K = K1
    if not K.is_Algebraic:
        raise DomainError('computation can be done only in an algebraic domain')
    F, monoms, polys = (dmp_to_dict(f, u), [], [])
    for monom, coeff in F.items():
        if not coeff.is_ground:
            monoms.append(monom)
    perms = variations([-1, 1], len(monoms), repetition=True)
    for perm in perms:
        G = dict(F)
        for sign, monom in zip(perm, monoms):
            if sign == -1:
                G[monom] = -G[monom]
        polys.append(dmp_from_dict(G, u, K))
    return dmp_convert(dmp_expand(polys, u, K), u, K, K.dom)

def dup_sign_variations(f, K):
    prev, k = (K.zero, 0)
    for coeff in f:
        if K.is_negative(coeff * prev):
            k += 1
        if coeff:
            prev = coeff
    return k

def dup_clear_denoms(f, K0, K1=None, convert=False):
    if K1 is None:
        if K0.has_assoc_Ring:
            K1 = K0.get_ring()
        else:
            K1 = K0
    common = K1.one
    for c in f:
        common = K1.lcm(common, K0.denom(c))
    if K1.is_one(common):
        if not convert:
            return (common, f)
        else:
            return (common, dup_convert(f, K0, K1))
    f = [K0.numer(c) * K1.quo(common, K0.denom(c)) for c in f]
    if not convert:
        return (common, dup_convert(f, K1, K0))
    else:
        return (common, f)

def _rec_clear_denoms(g, v, K0, K1):
    common = K1.one
    if not v:
        for c in g:
            common = K1.lcm(common, K0.denom(c))
    else:
        w = v - 1
        for c in g:
            common = K1.lcm(common, _rec_clear_denoms(c, w, K0, K1))
    return common

def dmp_clear_denoms(f, u, K0, K1=None, convert=False):
    if not u:
        return dup_clear_denoms(f, K0, K1, convert=convert)
    if K1 is None:
        if K0.has_assoc_Ring:
            K1 = K0.get_ring()
        else:
            K1 = K0
    common = _rec_clear_denoms(f, u, K0, K1)
    if not K1.is_one(common):
        f = dmp_mul_ground(f, common, u, K0)
    if not convert:
        return (common, f)
    else:
        return (common, dmp_convert(f, u, K0, K1))

def dup_revert(f, n, K):
    g = [K.revert(dup_TC(f, K))]
    h = [K.one, K.zero, K.zero]
    N = int(_ceil(_log2(n)))
    for i in range(1, N + 1):
        a = dup_mul_ground(g, K(2), K)
        b = dup_mul(f, dup_sqr(g, K), K)
        g = dup_rem(dup_sub(a, b, K), h, K)
        h = dup_lshift(h, dup_degree(h), K)
    return g

def dmp_revert(f, g, u, K):
    if not u:
        return dup_revert(f, g, K)
    else:
        raise MultivariatePolynomialError(f, g)

