    h = dup_monic(h, K0)
    cff = dup_convert(cff, K1, K0)
    cfg = dup_convert(cfg, K1, K0)
    cff = dup_mul_ground(cff, K0.quo(c, cf), K0)
    cfg = dup_mul_ground(cfg, K0.quo(c, cg), K0)
    return (h, cff, cfg)

def dmp_qq_heu_gcd(f, g, u, K0):
    result = _dmp_ff_trivial_gcd(f, g, u, K0)
