    fc, f = dup_primitive(f, K)
    gc, g = dup_primitive(g, K)
    c = K.lcm(fc, gc)
    h = dup_quo(dup_mul(f, g, K), dup_gcd(f, g, K), K)
    u = K.canonical_unit(dup_LC(h, K))
    return dup_mul_ground(h, c * u, K)

