        return dup_ff_lcm(f, g, K)
    else:
        return dup_rr_lcm(f, g, K)

def dmp_rr_lcm(f, g, u, K):
    fc, f = dmp_ground_primitive(f, u, K)
    gc, g = dmp_ground_primitive(g, u, K)
    c = K.lcm(fc, gc)
