def gf_crt(U, M, K=None):
    p = prod(M, start=K.one)
    v = K.zero
    for u, m in zip(U, M):
        e = p // m
        s, _, _ = K.gcdex(e, m)
        v += e * (u * s % m)
    return v % p

def gf_crt1(M, K):
    E, S = ([], [])
    p = prod(M, start=K.one)
    for m in M:
        E.append(p // m)
        S.append(K.gcdex(E[-1], m)[0] % m)
    return (p, E, S)

def gf_crt2(U, M, p, E, S, K):
    v = K.zero
    for u, m, e, s in zip(U, M, E, S):
        v += e * (u * s % m)
    return v % p

def gf_int(a, p):
    if a <= p // 2:
        return a
    else:
        return a - p

def gf_degree(f):
    return len(f) - 1

def gf_LC(f, K):
    if not f:
        return K.zero
    else:
        return f[0]

def gf_TC(f, K):
    if not f:
        return K.zero
    else:
        return f[-1]

def gf_strip(f):
    if not f or f[0]:
        return f
    k = 0
    for coeff in f:
        if coeff:
            break
        else:
            k += 1
    return f[k:]

def gf_trunc(f, p):
    return gf_strip([a % p for a in f])

def gf_normal(f, p, K):
    return gf_trunc(list(map(K, f)), p)

