class DUP_Flint(DMP):
    lev = 0
    __slots__ = ('_rep', 'dom', '_cls')

    def __reduce__(self):
        return (self.__class__, (self.to_list(), self.dom, self.lev))

    @classmethod
    def _new(cls, rep, dom, lev):
        rep = cls._flint_poly(rep[::-1], dom, lev)
        return cls.from_rep(rep, dom)

    def to_list(f):
        return f._rep.coeffs()[::-1]

