            return f.from_rep(flint.fmpq_poly(f._rep), dom)
        elif dom == ZZ and f.dom == QQ:
            return f.to_DMP_Python()._convert(dom).to_DUP_Flint()
        else:
            raise RuntimeError(f'DUP_Flint: Cannot convert {f.dom} to {dom}')

