            cF, G = g.clear_denoms()
        else:
            cG, F = (f.dom.one, f)
            cF, G = (g.dom.one, g)
        cH = cF.gcd(cG)
        cF, cG = (cF // cH, cG // cH)
        H = F._gcd(G)
        F, G = (F.exquo(H), G.exquo(H))
        f_neg = F.LC() < 0
        g_neg = G.LC() < 0
        if f_neg and g_neg:
            F, G = (F.neg(), G.neg())
        elif f_neg:
            cF, F = (-cF, F.neg())
        elif g_neg:
            cF, G = (-cF, G.neg())
        return (cF, cG, F, G)

