            coeff, factors = f._rep.factor()
            factors = [(f.from_rep(g, f.dom), k) for g, k in factors]
        elif f.dom.is_QQ:
            coeff, factors = f._rep.factor()
            factors_monic = [(f.from_rep(g, f.dom), k) for g, k in factors]
            factors = []
            for g, k in factors_monic:
                d, g = g.clear_denoms()
