        factors = [(g.to_list(), k) for g, k in factors]
        factors = _sort_factors(factors, multiple=True)
        to_dup_flint = lambda g: f.from_rep(f._cls(g[::-1]), f.dom)
        return [(to_dup_flint(g), k) for g, k in factors]

