            lev, dom, per, F, G = f.frac_unify(g)
            (F_num, F_den), (G_num, G_den) = (F, G)
            num = dmp_sub(dmp_mul(F_num, G_den, lev, dom), dmp_mul(F_den, G_num, lev, dom), lev, dom)
