def roots_linear(f):
    r = -f.nth(0) / f.nth(1)
    dom = f.get_domain()
    if not dom.is_Numerical:
        if dom.is_Composite:
            r = factor(r)
        else:
            from sympy.simplify.simplify import simplify
            r = simplify(r)
    return [r]

def roots_quadratic(f):
    a, b, c = f.all_coeffs()
    dom = f.get_domain()

    def _sqrt(d):
        co = []
        other = []
        for di in Mul.make_args(d):
            if di.is_Pow and di.exp.is_Integer and (di.exp % 2 == 0):
                co.append(Pow(di.base, di.exp // 2))
            else:
                other.append(di)
        if co:
            d = Mul(*other)
            co = Mul(*co)
            return co * sqrt(d)
        return sqrt(d)

    def _simplify(expr):
        if dom.is_Composite:
            return factor(expr)
        else:
            from sympy.simplify.simplify import simplify
            return simplify(expr)
    if c is S.Zero:
        r0, r1 = (S.Zero, -b / a)
        if not dom.is_Numerical:
            r1 = _simplify(r1)
        elif r1.is_negative:
            r0, r1 = (r1, r0)
    elif b is S.Zero:
        r = -c / a
        if not dom.is_Numerical:
            r = _simplify(r)
        R = _sqrt(r)
        r0 = -R
        r1 = R
    else:
        d = b ** 2 - 4 * a * c
        A = 2 * a
        B = -b / A
        if not dom.is_Numerical:
            d = _simplify(d)
            B = _simplify(B)
        D = factor_terms(_sqrt(d) / A)
        r0 = B - D
        r1 = B + D
        if a.is_negative:
            r0, r1 = (r1, r0)
        elif not dom.is_Numerical:
            r0, r1 = [expand_2arg(i) for i in (r0, r1)]
    return [r0, r1]

def roots_cubic(f, trig=False):
    if trig:
        a, b, c, d = f.all_coeffs()
        p = (3 * a * c - b ** 2) / (3 * a ** 2)
        q = (2 * b ** 3 - 9 * a * b * c + 27 * a ** 2 * d) / (27 * a ** 3)
        D = 18 * a * b * c * d - 4 * b ** 3 * d + b ** 2 * c ** 2 - 4 * a * c ** 3 - 27 * a ** 2 * d ** 2
        if (D > 0) == True:
            rv = []
            for k in range(3):
                rv.append(2 * sqrt(-p / 3) * cos(acos(q / p * sqrt(-3 / p) * Rational(3, 2)) / 3 - k * pi * Rational(2, 3)))
            return [i - b / 3 / a for i in rv]
    _, a, b, c = f.monic().all_coeffs()
    if c is S.Zero:
        x1, x2 = roots([1, a, b], multiple=True)
        return [x1, S.Zero, x2]
    p = b - a ** 2 / 3
    q = c - a * b / 3 + 2 * a ** 3 / 27
    pon3 = p / 3
    aon3 = a / 3
    u1 = None
    if p is S.Zero:
        if q is S.Zero:
            return [-aon3] * 3
        u1 = -root(q, 3) if q.is_positive else root(-q, 3)
    elif q is S.Zero:
        y1, y2 = roots([1, 0, p], multiple=True)
        return [tmp - aon3 for tmp in [y1, S.Zero, y2]]
    elif q.is_real and q.is_negative:
        u1 = -root(-q / 2 + sqrt(q ** 2 / 4 + pon3 ** 3), 3)
    coeff = I * sqrt(3) / 2
    if u1 is None:
        u1 = S.One
        u2 = Rational(-1, 2) + coeff
        u3 = Rational(-1, 2) - coeff
        b, c, d = (a, b, c)
        D0 = b ** 2 - 3 * c
        D1 = 2 * b ** 3 - 9 * b * c + 27 * d
        C = root((D1 + sqrt(D1 ** 2 - 4 * D0 ** 3)) / 2, 3)
        return [-(b + uk * C + D0 / C / uk) / 3 for uk in [u1, u2, u3]]
    u2 = u1 * (Rational(-1, 2) + coeff)
    u3 = u1 * (Rational(-1, 2) - coeff)
    if p is S.Zero:
        return [u1 - aon3, u2 - aon3, u3 - aon3]
    soln = [-u1 + pon3 / u1 - aon3, -u2 + pon3 / u2 - aon3, -u3 + pon3 / u3 - aon3]
    return soln

def _roots_quartic_euler(p, q, r, a):
    x = Dummy('x')
    eq = 64 * x ** 3 + 32 * p * x ** 2 + (4 * p ** 2 - 16 * r) * x - q ** 2
    xsols = list(roots(Poly(eq, x), cubics=False).keys())
    xsols = [sol for sol in xsols if sol.is_rational and sol.is_nonzero]
    if not xsols:
        return None
    R = max(xsols)
    c1 = sqrt(R)
    B = -q * c1 / (4 * R)
    A = -R - p / 2
    c2 = sqrt(A + B)
    c3 = sqrt(A - B)
    return [c1 - c2 - a, -c1 - c3 - a, -c1 + c3 - a, c1 + c2 - a]

def roots_quartic(f):
    _, a, b, c, d = f.monic().all_coeffs()
    if not d:
        return [S.Zero] + roots([1, a, b, c], multiple=True)
    elif (c / a) ** 2 == d:
        x, m = (f.gen, c / a)
        g = Poly(x ** 2 + a * x + b - 2 * m, x)
        z1, z2 = roots_quadratic(g)
        h1 = Poly(x ** 2 - z1 * x + m, x)
        h2 = Poly(x ** 2 - z2 * x + m, x)
        r1 = roots_quadratic(h1)
        r2 = roots_quadratic(h2)
        return r1 + r2
    else:
        a2 = a ** 2
        e = b - 3 * a2 / 8
        f = _mexpand(c + a * (a2 / 8 - b / 2))
        aon4 = a / 4
        g = _mexpand(d - aon4 * (a * (3 * a2 / 64 - b / 4) + c))
        if f.is_zero:
            y1, y2 = [sqrt(tmp) for tmp in roots([1, e, g], multiple=True)]
            return [tmp - aon4 for tmp in [-y1, -y2, y1, y2]]
        if g.is_zero:
            y = [S.Zero] + roots([1, 0, e, f], multiple=True)
            return [tmp - aon4 for tmp in y]
        else:
            sols = _roots_quartic_euler(e, f, g, aon4)
            if sols:
                return sols
            p = -e ** 2 / 12 - g
            q = -e ** 3 / 108 + e * g / 3 - f ** 2 / 8
            TH = Rational(1, 3)

            def _ans(y):
                w = sqrt(e + 2 * y)
                arg1 = 3 * e + 2 * y
                arg2 = 2 * f / w
                ans = []
                for s in [-1, 1]:
                    root = sqrt(-(arg1 + s * arg2))
                    for t in [-1, 1]:
                        ans.append((s * w - t * root) / 2 - aon4)
                return ans
            p = _mexpand(p)
            y1 = e * Rational(-5, 6) - q ** TH
            if p.is_zero:
                return _ans(y1)
            root = sqrt(q ** 2 / 4 + p ** 3 / 27)
            r = -q / 2 + root
            u = r ** TH
            y2 = e * Rational(-5, 6) + u - p / u / 3
            if fuzzy_not(p.is_zero):
                return _ans(y2)
            return [Piecewise((a1, Eq(p, 0)), (a2, True)) for a1, a2 in zip(_ans(y1), _ans(y2))]

def roots_binomial(f):
    n = f.degree()
    a, b = (f.nth(n), f.nth(0))
    base = -cancel(b / a)
    alpha = root(base, n)
    if alpha.is_number:
        alpha = alpha.expand(complex=True)
    neg = base.is_negative
    even = n % 2 == 0
    if neg:
        if even == True and (base + 1).is_positive:
            big = True
        else:
            big = False
    ks = []
    imax = n // 2
    if even:
        ks.append(imax)
        imax -= 1
    if not neg:
        ks.append(0)
    for i in range(imax, 0, -1):
        if neg:
            ks.extend([i, -i])
        else:
            ks.extend([-i, i])
    if neg:
        ks.append(0)
        if big:
            for i in range(0, len(ks), 2):
                pair = ks[i:i + 2]
                pair = list(reversed(pair))
    roots, d = ([], 2 * I * pi / n)
    for k in ks:
        zeta = exp(k * d).expand(complex=True)
        roots.append((alpha * zeta).expand(power_base=False))
    return roots

def _inv_totient_estimate(m):
    primes = [d + 1 for d in divisors(m) if isprime(d + 1)]
    a, b = (1, 1)
    for p in primes:
        a *= p
        b *= p - 1
    L = m
    U = int(math.ceil(m * (float(a) / b)))
    P = p = 2
    primes = []
    while P <= U:
        p = nextprime(p)
        primes.append(p)
        P *= p
    P //= p
    b = 1
    for p in primes[:-1]:
        b *= p - 1
    U = int(math.ceil(m * (float(P) / b)))
    return (L, U)

def roots_cyclotomic(f, factor=False):
    L, U = _inv_totient_estimate(f.degree())
    for n in range(L, U + 1):
        g = cyclotomic_poly(n, f.gen, polys=True)
        if f.expr == g.expr:
            break
    else:
        raise RuntimeError('failed to find index of a cyclotomic polynomial')
    roots = []
    if not factor:
        h = n // 2
        ks = [i for i in range(1, n + 1) if igcd(i, n) == 1]
        ks.sort(key=lambda x: (x, -1) if x <= h else (abs(x - n), 1))
        d = 2 * I * pi / n
        for k in reversed(ks):
            roots.append(exp(k * d).expand(complex=True))
    else:
        g = Poly(f, extension=root(-1, n))
        for h, _ in ordered(g.factor_list()[1]):
            roots.append(-h.TC())
    return roots

def roots_quintic(f):
    result = []
    coeff_5, coeff_4, p_, q_, r_, s_ = f.all_coeffs()
    if not all((coeff.is_Rational for coeff in (coeff_5, coeff_4, p_, q_, r_, s_))):
        return result
    if coeff_5 != 1:
        f = Poly(f / coeff_5)
        _, coeff_4, p_, q_, r_, s_ = f.all_coeffs()
    if coeff_4:
        p = p_ - 2 * coeff_4 * coeff_4 / 5
        q = q_ - 3 * coeff_4 * p_ / 5 + 4 * coeff_4 ** 3 / 25
        r = r_ - 2 * coeff_4 * q_ / 5 + 3 * coeff_4 ** 2 * p_ / 25 - 3 * coeff_4 ** 4 / 125
        s = s_ - coeff_4 * r_ / 5 + coeff_4 ** 2 * q_ / 25 - coeff_4 ** 3 * p_ / 125 + 4 * coeff_4 ** 5 / 3125
        x = f.gen
        f = Poly(x ** 5 + p * x ** 3 + q * x ** 2 + r * x + s)
    else:
        p, q, r, s = (p_, q_, r_, s_)
    quintic = PolyQuintic(f)
    if not f.is_irreducible:
        return result
    f20 = quintic.f20
    if f20.is_irreducible:
        return result
    for _factor in f20.factor_list()[1]:
        if _factor[0].is_linear:
            theta = _factor[0].root(0)
            break
    d = discriminant(f)
    delta = sqrt(d)
    zeta1, zeta2, zeta3, zeta4 = quintic.zeta
    T = quintic.T(theta, d)
    tol = S(1e-10)
    alpha = T[1] + T[2] * delta
    alpha_bar = T[1] - T[2] * delta
    beta = T[3] + T[4] * delta
    beta_bar = T[3] - T[4] * delta
    disc = alpha ** 2 - 4 * beta
    disc_bar = alpha_bar ** 2 - 4 * beta_bar
    l0 = quintic.l0(theta)
    Stwo = S(2)
    l1 = _quintic_simplify((-alpha + sqrt(disc)) / Stwo)
    l4 = _quintic_simplify((-alpha - sqrt(disc)) / Stwo)
    l2 = _quintic_simplify((-alpha_bar + sqrt(disc_bar)) / Stwo)
    l3 = _quintic_simplify((-alpha_bar - sqrt(disc_bar)) / Stwo)
    order = quintic.order(theta, d)
    test = order * delta.n() - (l1.n() - l4.n()) * (l2.n() - l3.n())
    if not comp(test, 0, tol):
        l2, l3 = (l3, l2)
    R1 = l0 + l1 * zeta1 + l2 * zeta2 + l3 * zeta3 + l4 * zeta4
    R2 = l0 + l3 * zeta1 + l1 * zeta2 + l4 * zeta3 + l2 * zeta4
    R3 = l0 + l2 * zeta1 + l4 * zeta2 + l1 * zeta3 + l3 * zeta4
    R4 = l0 + l4 * zeta1 + l3 * zeta2 + l2 * zeta3 + l1 * zeta4
    Res = [None, [None] * 5, [None] * 5, [None] * 5, [None] * 5]
    Res_n = [None, [None] * 5, [None] * 5, [None] * 5, [None] * 5]
    R1 = _quintic_simplify(R1)
    R2 = _quintic_simplify(R2)
    R3 = _quintic_simplify(R3)
    R4 = _quintic_simplify(R4)
    x0 = z ** (S(1) / 5)
    x1 = sqrt(2)
    x2 = sqrt(5)
    x3 = sqrt(5 - x2)
    x4 = I * x2
    x5 = x4 + I
    x6 = I * x0 / 4
    x7 = x1 * sqrt(x2 + 5)
    sol = [x0, -x6 * (x1 * x3 - x5), x6 * (x1 * x3 + x5), -x6 * (x4 + x7 - I), x6 * (-x4 + x7 + I)]
    R1 = R1.as_real_imag()
    R2 = R2.as_real_imag()
    R3 = R3.as_real_imag()
    R4 = R4.as_real_imag()
    for i, s in enumerate(sol):
        Res[1][i] = _quintic_simplify(s.xreplace({z: R1[0] + I * R1[1]}))
        Res[2][i] = _quintic_simplify(s.xreplace({z: R2[0] + I * R2[1]}))
        Res[3][i] = _quintic_simplify(s.xreplace({z: R3[0] + I * R3[1]}))
        Res[4][i] = _quintic_simplify(s.xreplace({z: R4[0] + I * R4[1]}))
    for i in range(1, 5):
        for j in range(5):
            Res_n[i][j] = Res[i][j].n()
            Res[i][j] = _quintic_simplify(Res[i][j])
    r1 = Res[1][0]
    r1_n = Res_n[1][0]
    for i in range(5):
        if comp(im(r1_n * Res_n[4][i]), 0, tol):
            r4 = Res[4][i]
            break
    u, v = quintic.uv(theta, d)
    testplus = (u + v * delta * sqrt(5)).n()
    testminus = (u - v * delta * sqrt(5)).n()
    r4_n = r4.n()
    r2 = r3 = None
    for i in range(5):
        r2temp_n = Res_n[2][i]
        for j in range(5):
            r3temp_n = Res_n[3][j]
            if comp((r1_n * r2temp_n ** 2 + r4_n * r3temp_n ** 2 - testplus).n(), 0, tol) and comp((r3temp_n * r1_n ** 2 + r2temp_n * r4_n ** 2 - testminus).n(), 0, tol):
                r2 = Res[2][i]
                r3 = Res[3][j]
                break
        if r2 is not None:
            break
    else:
        return []
    x1 = (r1 + r2 + r3 + r4) / 5
    x2 = (r1 * zeta4 + r2 * zeta3 + r3 * zeta2 + r4 * zeta1) / 5
    x3 = (r1 * zeta3 + r2 * zeta1 + r3 * zeta4 + r4 * zeta2) / 5
    x4 = (r1 * zeta2 + r2 * zeta4 + r3 * zeta1 + r4 * zeta3) / 5
    x5 = (r1 * zeta1 + r2 * zeta2 + r3 * zeta3 + r4 * zeta4) / 5
    result = [x1, x2, x3, x4, x5]
    saw = set()
    for r in result:
        r = r.n(2)
        if r in saw:
            return []
        saw.add(r)
    if coeff_4:
        result = [x - coeff_4 / 5 for x in result]
    return result

def _quintic_simplify(expr):
    from sympy.simplify.simplify import powsimp
    expr = powsimp(expr)
    expr = cancel(expr)
    return together(expr)

def _integer_basis(poly):
    monoms, coeffs = list(zip(*poly.terms()))
    monoms, = list(zip(*monoms))
    coeffs = list(map(abs, coeffs))
    if coeffs[0] < coeffs[-1]:
        coeffs = list(reversed(coeffs))
        n = monoms[0]
        monoms = [n - i for i in reversed(monoms)]
    else:
        return None
    monoms = monoms[:-1]
    coeffs = coeffs[:-1]
    if len(monoms) == 1:
        r = Pow(coeffs[0], S.One / monoms[0])
        if r.is_Integer:
            return int(r)
        else:
            return None
    divs = reversed(divisors(gcd_list(coeffs))[1:])
    try:
        div = next(divs)
    except StopIteration:
        return None
    while True:
        for monom, coeff in zip(monoms, coeffs):
            if coeff % div ** monom != 0:
                try:
                    div = next(divs)
                except StopIteration:
                    return None
                else:
                    break
        else:
            return div

def preprocess_roots(poly):
    coeff = S.One
    poly_func = poly.func
    try:
        _, poly = poly.clear_denoms(convert=True)
    except DomainError:
        return (coeff, poly)
    poly = poly.primitive()[1]
    poly = poly.retract()
    if poly.get_domain().is_Poly and all((c.is_term for c in poly.rep.coeffs())):
        poly = poly.inject()
        strips = list(zip(*poly.monoms()))
        gens = list(poly.gens[1:])
        base, strips = (strips[0], strips[1:])
        for gen, strip in zip(list(gens), strips):
            reverse = False
            if strip[0] < strip[-1]:
                strip = reversed(strip)
                reverse = True
            ratio = None
            for a, b in zip(base, strip):
                if not a and (not b):
                    continue
                elif not a or not b:
                    break
                elif b % a != 0:
                    break
                else:
                    _ratio = b // a
                    if ratio is None:
                        ratio = _ratio
                    elif ratio != _ratio:
                        break
            else:
                if reverse:
                    ratio = -ratio
                poly = poly.eval(gen, 1)
                coeff *= gen ** (-ratio)
                gens.remove(gen)
        if gens:
            poly = poly.eject(*gens)
    if poly.is_univariate and poly.get_domain().is_ZZ:
        basis = _integer_basis(poly)
        if basis is not None:
            n = poly.degree()

            def func(k, coeff):
                return coeff // basis ** (n - k[0])
            poly = poly.termwise(func)
            coeff *= basis
    if not isinstance(poly, poly_func):
        poly = poly_func(poly)
    return (coeff, poly)

