                    return gen
            else:
                raise PolynomialError('-%s <= gen < %s expected, got %s' % (length, length, gen))
        else:
            try:
                return f.gens.index(sympify(gen))
            except ValueError:
                raise PolynomialError('a valid generator expected, got %s' % gen)

