    @_sympifyit('other', NotImplemented)
    def __eq__(self, other):
        f, g = (self, other)
        if not g.is_Poly:
            try:
                g = f.__class__(g, f.gens, domain=f.get_domain())
            except (PolynomialError, DomainError, CoercionFailed):
                return False
        if f.gens != g.gens:
            return False
        if f.rep.dom != g.rep.dom:
            return False
        return f.rep == g.rep

