def _sorted_factors(factors, method):
    if method == 'sqf':

        def key(obj):
            poly, exp = obj
            rep = poly.rep.to_list()
            return (exp, len(rep), len(poly.gens), str(poly.domain), rep)
    else:

        def key(obj):
            poly, exp = obj
            rep = poly.rep.to_list()
            return (len(rep), len(poly.gens), exp, str(poly.domain), rep)
    return sorted(factors, key=key)

def _factors_product(factors):
    return Mul(*[f.as_expr() ** k for f, k in factors])

def _symbolic_factor_list(expr, opt, method):
    coeff, factors = (S.One, [])
    args = [i._eval_factor() if hasattr(i, '_eval_factor') else i for i in Mul.make_args(expr)]
    for arg in args:
        if arg.is_Number or (isinstance(arg, Expr) and pure_complex(arg)):
            coeff *= arg
            continue
        elif arg.is_Pow and arg.base != S.Exp1:
            base, exp = arg.args
            if base.is_Number and exp.is_Number:
                coeff *= arg
                continue
            if base.is_Number:
                factors.append((base, exp))
                continue
        else:
            base, exp = (arg, S.One)
        try:
            poly, _ = _poly_from_expr(base, opt)
        except PolificationFailed as exc:
            factors.append((exc.expr, exp))
        else:
            func = getattr(poly, method + '_list')
            _coeff, _factors = func()
            if _coeff is not S.One:
                if exp.is_Integer:
                    coeff *= _coeff ** exp
                elif _coeff.is_positive:
                    factors.append((_coeff, exp))
                else:
                    _factors.append((_coeff, S.One))
            if exp is S.One:
                factors.extend(_factors)
            elif exp.is_integer:
                factors.extend([(f, k * exp) for f, k in _factors])
            else:
                other = []
                for f, k in _factors:
                    if f.as_expr().is_positive:
                        factors.append((f, k * exp))
                    else:
                        other.append((f, k))
                factors.append((_factors_product(other), exp))
    if method == 'sqf':
        factors = [(reduce(mul, (f for f, _ in factors if _ == k)), k) for k in {i for _, i in factors}]
    return (coeff, factors)

def _symbolic_factor(expr, opt, method):
    if isinstance(expr, Expr):
        if hasattr(expr, '_eval_factor'):
            return expr._eval_factor()
        coeff, factors = _symbolic_factor_list(together(expr, fraction=opt['fraction']), opt, method)
        return _keep_coeff(coeff, _factors_product(factors))
    elif hasattr(expr, 'args'):
        return expr.func(*[_symbolic_factor(arg, opt, method) for arg in expr.args])
    elif hasattr(expr, '__iter__'):
        return expr.__class__([_symbolic_factor(arg, opt, method) for arg in expr])
    else:
        return expr

def _generic_factor_list(expr, gens, args, method):
    options.allowed_flags(args, ['frac', 'polys'])
    opt = options.build_options(gens, args)
    expr = sympify(expr)
    if isinstance(expr, (Expr, Poly)):
        if isinstance(expr, Poly):
            numer, denom = (expr, 1)
        else:
            numer, denom = together(expr).as_numer_denom()
        cp, fp = _symbolic_factor_list(numer, opt, method)
        cq, fq = _symbolic_factor_list(denom, opt, method)
        if fq and (not opt.frac):
            raise PolynomialError('a polynomial expected, got %s' % expr)
        _opt = opt.clone({'expand': True})
        for factors in (fp, fq):
            for i, (f, k) in enumerate(factors):
                if not f.is_Poly:
                    f, _ = _poly_from_expr(f, _opt)
                    factors[i] = (f, k)
        fp = _sorted_factors(fp, method)
        fq = _sorted_factors(fq, method)
        if not opt.polys:
            fp = [(f.as_expr(), k) for f, k in fp]
            fq = [(f.as_expr(), k) for f, k in fq]
        coeff = cp / cq
        if not opt.frac:
            return (coeff, fp)
        else:
            return (coeff, fp, fq)
    else:
        raise PolynomialError('a polynomial expected, got %s' % expr)

def _generic_factor(expr, gens, args, method):
    fraction = args.pop('fraction', True)
    options.allowed_flags(args, [])
    opt = options.build_options(gens, args)
    opt['fraction'] = fraction
    return _symbolic_factor(sympify(expr), opt, method)

def to_rational_coeffs(f):
    from sympy.simplify.simplify import simplify

    def _try_rescale(f, f1=None):
        if not len(f.gens) == 1 or not f.gens[0].is_Atom:
            return (None, f)
        n = f.degree()
        lc = f.LC()
        f1 = f1 or f1.monic()
        coeffs = f1.all_coeffs()[1:]
        coeffs = [simplify(coeffx) for coeffx in coeffs]
        if len(coeffs) > 1 and coeffs[-2]:
            rescale1_x = simplify(coeffs[-2] / coeffs[-1])
            coeffs1 = []
            for i in range(len(coeffs)):
                coeffx = simplify(coeffs[i] * rescale1_x ** (i + 1))
                if not coeffx.is_rational:
                    break
                coeffs1.append(coeffx)
            else:
                rescale_x = simplify(1 / rescale1_x)
                x = f.gens[0]
                v = [x ** n]
                for i in range(1, n + 1):
                    v.append(coeffs1[i - 1] * x ** (n - i))
                f = Add(*v)
                f = Poly(f)
                return (lc, rescale_x, f)
        return None

    def _try_translate(f, f1=None):
        if not len(f.gens) == 1 or not f.gens[0].is_Atom:
            return (None, f)
        n = f.degree()
        f1 = f1 or f1.monic()
        coeffs = f1.all_coeffs()[1:]
        c = simplify(coeffs[0])
        if c.is_Add and (not c.is_rational):
            rat, nonrat = sift(c.args, lambda z: z.is_rational is True, binary=True)
            alpha = -c.func(*nonrat) / n
            f2 = f1.shift(alpha)
            return (alpha, f2)
        return None

    def _has_square_roots(p):
        coeffs = p.coeffs()
        has_sq = False
        for y in coeffs:
            for x in Add.make_args(y):
                f = Factors(x).factors
                r = [wx.q for b, wx in f.items() if b.is_number and wx.is_Rational and (wx.q >= 2)]
                if not r:
                    continue
                if min(r) == 2:
                    has_sq = True
                if max(r) > 2:
                    return False
        return has_sq
    if f.get_domain().is_EX and _has_square_roots(f):
        f1 = f.monic()
        r = _try_rescale(f, f1)
        if r:
            return (r[0], r[1], None, r[2])
        else:
            r = _try_translate(f, f1)
            if r:
                return (None, None, r[0], r[1])
    return None

def _torational_factor_list(p, x):
    from sympy.simplify.simplify import simplify
    p1 = Poly(p, x, domain='EX')
    n = p1.degree()
    res = to_rational_coeffs(p1)
    if not res:
        return None
    lc, r, t, g = res
    factors = factor_list(g.as_expr())
    if lc:
        c = simplify(factors[0] * lc * r ** n)
        r1 = simplify(1 / r)
        a = []
        for z in factors[1:][0]:
            a.append((simplify(z[0].subs({x: x * r1})), z[1]))
    else:
        c = factors[0]
        a = []
        for z in factors[1:][0]:
            a.append((z[0].subs({x: x - t}), z[1]))
    return (c, a)

