def _nsort(roots, separated=False):
    if not all((r.is_number for r in roots)):
        raise NotImplementedError
    key = [[i.n(2).as_real_imag()[0] for i in r.as_real_imag()] for r in roots]
    if len(roots) > 1 and any((i._prec == 1 for k in key for i in k)):
        raise NotImplementedError('could not compute root with precision')
    key = [(1 if i else 0, r, i) for r, i in key]
    key = sorted(zip(key, roots))
    if separated:
        r = []
        i = []
        for (im, _, _), v in key:
            if im:
                i.append(v)
            else:
                r.append(v)
        return (r, i)
    _, roots = zip(*key)
    return list(roots)

def _sort_gens(gens, **args):
    opt = build_options(args)
    gens_order, wrt = ({}, None)
    if opt is not None:
        gens_order, wrt = ({}, opt.wrt)
        for i, gen in enumerate(opt.sort):
            gens_order[gen] = i + 1

    def order_key(gen):
        gen = str(gen)
        if wrt is not None:
            try:
                return (-len(wrt) + wrt.index(gen), gen, 0)
            except ValueError:
                pass
        name, index = _re_gen.match(gen).groups()
        if index:
            index = int(index)
        else:
            index = 0
        try:
            return (gens_order[name], name, index)
        except KeyError:
            pass
        try:
            return (_gens_order[name], name, index)
        except KeyError:
            pass
        return (_max_order, name, index)
    try:
        gens = sorted(gens, key=order_key)
    except TypeError:
        pass
    return tuple(gens)

def _unify_gens(f_gens, g_gens):
    f_gens = list(f_gens)
    g_gens = list(g_gens)
    if f_gens == g_gens:
        return tuple(f_gens)
    gens, common, k = ([], [], 0)
    for gen in f_gens:
        if gen in g_gens:
            common.append(gen)
    for i, gen in enumerate(g_gens):
        if gen in common:
            g_gens[i], k = (common[k], k + 1)
    for gen in common:
        i = f_gens.index(gen)
        gens.extend(f_gens[:i])
        f_gens = f_gens[i + 1:]
        i = g_gens.index(gen)
        gens.extend(g_gens[:i])
        g_gens = g_gens[i + 1:]
        gens.append(gen)
    gens.extend(f_gens)
    gens.extend(g_gens)
    return tuple(gens)

