def _dict_reorder(rep, gens, new_gens):
    gens = list(gens)
    monoms = rep.keys()
    coeffs = rep.values()
    new_monoms = [[] for _ in range(len(rep))]
    used_indices = set()
    for gen in new_gens:
        try:
            j = gens.index(gen)
            used_indices.add(j)
            for M, new_M in zip(monoms, new_monoms):
                new_M.append(M[j])
        except ValueError:
            for new_M in new_monoms:
                new_M.append(0)
    for i, _ in enumerate(gens):
        if i not in used_indices:
            for monom in monoms:
                if monom[i]:
                    raise GeneratorsError('unable to drop generators')
    return (map(tuple, new_monoms), coeffs)

class PicklableWithSlots:
    __slots__ = ()

    def __getstate__(self, cls=None):
        if cls is None:
            cls = self.__class__
        d = {}
        for c in cls.__bases__:
            getstate = getattr(c, '__getstate__', None)
            objstate = getattr(object, '__getstate__', None)
            if getstate is not None and getstate is not objstate:
                d.update(getstate(self, c))
        for name in cls.__slots__:
            if hasattr(self, name):
                d[name] = getattr(self, name)
        return d

