        terms = self.items()
        zero = self.ring.domain.zero
        poly = self.ring.zero
        for multinomial, multinomial_coeff in multinomials:
            product_monom = zero_monom
            product_coeff = multinomial_coeff
            for exp, (monom, coeff) in zip(multinomial, terms):
                if exp:
                    product_monom = monomial_mulpow(product_monom, monom, exp)
                    product_coeff *= coeff ** exp
            monom = tuple(product_monom)
            coeff = product_coeff
            coeff = poly.get(monom, zero) + coeff
            if coeff:
                poly[monom] = coeff
            elif monom in poly:
                del poly[monom]
        return poly

    def square(self):
        ring = self.ring
        p = ring.zero
        get = p.get
        keys = list(self.keys())
        zero = ring.domain.zero
        monomial_mul = ring.monomial_mul
        for i in range(len(keys)):
            k1 = keys[i]
            pk = self[k1]
            for j in range(i):
                k2 = keys[j]
                exp = monomial_mul(k1, k2)
                p[exp] = get(exp, zero) + pk * self[k2]
        p = p.imul_num(2)
        get = p.get
        for k, v in self.items():
            k2 = monomial_mul(k, k)
            p[k2] = get(k2, zero) + v ** 2
        p.strip_zero()
        return p

    def __divmod__(p1, p2):
        ring = p1.ring
        if not p2:
            raise ZeroDivisionError('polynomial division')
        elif isinstance(p2, ring.dtype):
            return p1.div(p2)
        elif isinstance(p2, PolyElement):
            if isinstance(ring.domain, PolynomialRing) and ring.domain.ring == p2.ring:
                pass
            elif isinstance(p2.ring.domain, PolynomialRing) and p2.ring.domain.ring == ring:
                return p2.__rdivmod__(p1)
            else:
                return NotImplemented
        try:
            p2 = ring.domain_new(p2)
        except CoercionFailed:
            return NotImplemented
        else:
            return (p1.quo_ground(p2), p1.rem_ground(p2))

    def __rdivmod__(p1, p2):
        return NotImplemented

    def __mod__(p1, p2):
        ring = p1.ring
        if not p2:
            raise ZeroDivisionError('polynomial division')
        elif isinstance(p2, ring.dtype):
            return p1.rem(p2)
        elif isinstance(p2, PolyElement):
            if isinstance(ring.domain, PolynomialRing) and ring.domain.ring == p2.ring:
                pass
            elif isinstance(p2.ring.domain, PolynomialRing) and p2.ring.domain.ring == ring:
                return p2.__rmod__(p1)
            else:
                return NotImplemented
        try:
            p2 = ring.domain_new(p2)
        except CoercionFailed:
            return NotImplemented
        else:
            return p1.rem_ground(p2)

    def __rmod__(p1, p2):
        return NotImplemented

    def __truediv__(p1, p2):
        ring = p1.ring
        if not p2:
            raise ZeroDivisionError('polynomial division')
        elif isinstance(p2, ring.dtype):
            if p2.is_monomial:
                return p1 * p2 ** (-1)
            else:
                return p1.quo(p2)
        elif isinstance(p2, PolyElement):
            if isinstance(ring.domain, PolynomialRing) and ring.domain.ring == p2.ring:
                pass
            elif isinstance(p2.ring.domain, PolynomialRing) and p2.ring.domain.ring == ring:
                return p2.__rtruediv__(p1)
            else:
                return NotImplemented
        try:
            p2 = ring.domain_new(p2)
        except CoercionFailed:
            return NotImplemented
        else:
            return p1.quo_ground(p2)

    def __rtruediv__(p1, p2):
        return NotImplemented
    __floordiv__ = __truediv__
    __rfloordiv__ = __rtruediv__

    def _term_div(self):
        zm = self.ring.zero_monom
        domain = self.ring.domain
        domain_quo = domain.quo
        monomial_div = self.ring.monomial_div
        if domain.is_Field:

            def term_div(a_lm_a_lc, b_lm_b_lc):
                a_lm, a_lc = a_lm_a_lc
                b_lm, b_lc = b_lm_b_lc
                if b_lm == zm:
                    monom = a_lm
                else:
                    monom = monomial_div(a_lm, b_lm)
                if monom is not None:
                    return (monom, domain_quo(a_lc, b_lc))
                else:
                    return None
        else:

            def term_div(a_lm_a_lc, b_lm_b_lc):
                a_lm, a_lc = a_lm_a_lc
                b_lm, b_lc = b_lm_b_lc
                if b_lm == zm:
                    monom = a_lm
                else:
                    monom = monomial_div(a_lm, b_lm)
                if not (monom is None or a_lc % b_lc):
                    return (monom, domain_quo(a_lc, b_lc))
                else:
                    return None
        return term_div

    def div(self, fv):
        ring = self.ring
        ret_single = False
        if isinstance(fv, PolyElement):
            ret_single = True
            fv = [fv]
        if not all(fv):
            raise ZeroDivisionError('polynomial division')
        if not self:
            if ret_single:
                return (ring.zero, ring.zero)
            else:
                return ([], ring.zero)
        for f in fv:
            if f.ring != ring:
                raise ValueError('self and f must have the same ring')
        s = len(fv)
        qv = [ring.zero for i in range(s)]
        p = self.copy()
        r = ring.zero
        term_div = self._term_div()
        expvs = [fx.leading_expv() for fx in fv]
        while p:
            i = 0
            divoccurred = 0
            while i < s and divoccurred == 0:
                expv = p.leading_expv()
                term = term_div((expv, p[expv]), (expvs[i], fv[i][expvs[i]]))
                if term is not None:
                    expv1, c = term
                    qv[i] = qv[i]._iadd_monom((expv1, c))
                    p = p._iadd_poly_monom(fv[i], (expv1, -c))
                    divoccurred = 1
                else:
                    i += 1
            if not divoccurred:
                expv = p.leading_expv()
                r = r._iadd_monom((expv, p[expv]))
                del p[expv]
        if expv == ring.zero_monom:
            r += p
        if ret_single:
            if not qv:
                return (ring.zero, r)
            else:
                return (qv[0], r)
        else:
            return (qv, r)

    def rem(self, G):
        f = self
        if isinstance(G, PolyElement):
            G = [G]
        if not all(G):
            raise ZeroDivisionError('polynomial division')
        ring = f.ring
        domain = ring.domain
        zero = domain.zero
        monomial_mul = ring.monomial_mul
        r = ring.zero
        term_div = f._term_div()
        ltf = f.LT
        f = f.copy()
        get = f.get
        while f:
            for g in G:
                tq = term_div(ltf, g.LT)
                if tq is not None:
                    m, c = tq
                    for mg, cg in g.iterterms():
                        m1 = monomial_mul(mg, m)
                        c1 = get(m1, zero) - c * cg
                        if not c1:
                            del f[m1]
                        else:
                            f[m1] = c1
                    ltm = f.leading_expv()
                    if ltm is not None:
                        ltf = (ltm, f[ltm])
                    break
            else:
                ltm, ltc = ltf
                if ltm in r:
                    r[ltm] += ltc
                else:
                    r[ltm] = ltc
                del f[ltm]
                ltm = f.leading_expv()
                if ltm is not None:
                    ltf = (ltm, f[ltm])
        return r

    def quo(f, G):
        return f.div(G)[0]

    def exquo(f, G):
        q, r = f.div(G)
        if not r:
            return q
        else:
            raise ExactQuotientFailed(f, G)

    def _iadd_monom(self, mc):
        if self in self.ring._gens_set:
            cpself = self.copy()
        else:
            cpself = self
        expv, coeff = mc
        c = cpself.get(expv)
        if c is None:
            cpself[expv] = coeff
        else:
            c += coeff
            if c:
                cpself[expv] = c
            else:
                del cpself[expv]
        return cpself

    def _iadd_poly_monom(self, p2, mc):
        p1 = self
        if p1 in p1.ring._gens_set:
            p1 = p1.copy()
        m, c = mc
        get = p1.get
        zero = p1.ring.domain.zero
        monomial_mul = p1.ring.monomial_mul
        for k, v in p2.items():
            ka = monomial_mul(k, m)
            coeff = get(ka, zero) + v * c
            if coeff:
                p1[ka] = coeff
            else:
                del p1[ka]
        return p1

    def degree(f, x=None):
        i = f.ring.index(x)
        if not f:
            return ninf
        elif i < 0:
            return 0
        else:
            return max((monom[i] for monom in f.itermonoms()))

    def degrees(f):
        if not f:
            return (ninf,) * f.ring.ngens
        else:
            return tuple(map(max, list(zip(*f.itermonoms()))))

    def tail_degree(f, x=None):
        i = f.ring.index(x)
        if not f:
            return ninf
        elif i < 0:
            return 0
        else:
            return min((monom[i] for monom in f.itermonoms()))

    def tail_degrees(f):
        if not f:
            return (ninf,) * f.ring.ngens
        else:
            return tuple(map(min, list(zip(*f.itermonoms()))))

    def leading_expv(self):
        if self:
            return self.ring.leading_expv(self)
        else:
            return None

    def _get_coeff(self, expv):
        return self.get(expv, self.ring.domain.zero)

    def coeff(self, element):
        if element == 1:
            return self._get_coeff(self.ring.zero_monom)
        elif isinstance(element, self.ring.dtype):
            terms = list(element.iterterms())
            if len(terms) == 1:
                monom, coeff = terms[0]
                if coeff == self.ring.domain.one:
                    return self._get_coeff(monom)
        raise ValueError('expected a monomial, got %s' % element)

    def const(self):
        return self._get_coeff(self.ring.zero_monom)

    @property
    def LC(self):
        return self._get_coeff(self.leading_expv())

    @property
    def LM(self):
        expv = self.leading_expv()
        if expv is None:
            return self.ring.zero_monom
        else:
            return expv

    def leading_monom(self):
        p = self.ring.zero
        expv = self.leading_expv()
        if expv:
            p[expv] = self.ring.domain.one
        return p

    @property
    def LT(self):
        expv = self.leading_expv()
        if expv is None:
            return (self.ring.zero_monom, self.ring.domain.zero)
        else:
            return (expv, self._get_coeff(expv))

    def leading_term(self):
        p = self.ring.zero
        expv = self.leading_expv()
        if expv is not None:
            p[expv] = self[expv]
        return p

    def _sorted(self, seq, order):
        if order is None:
            order = self.ring.order
        else:
            order = OrderOpt.preprocess(order)
        if order is lex:
            return sorted(seq, key=lambda monom: monom[0], reverse=True)
        else:
            return sorted(seq, key=lambda monom: order(monom[0]), reverse=True)

    def coeffs(self, order=None):
        return [coeff for _, coeff in self.terms(order)]

    def monoms(self, order=None):
        return [monom for monom, _ in self.terms(order)]

    def terms(self, order=None):
        return self._sorted(list(self.items()), order)

    def itercoeffs(self):
        return iter(self.values())

    def itermonoms(self):
        return iter(self.keys())

    def iterterms(self):
        return iter(self.items())

    def listcoeffs(self):
        return list(self.values())

    def listmonoms(self):
        return list(self.keys())

    def listterms(self):
        return list(self.items())

    def imul_num(p, c):
        if p in p.ring._gens_set:
            return p * c
        if not c:
            p.clear()
            return
        for exp in p:
            p[exp] *= c
        return p

    def content(f):
        domain = f.ring.domain
        cont = domain.zero
        gcd = domain.gcd
        for coeff in f.itercoeffs():
            cont = gcd(cont, coeff)
        return cont

    def primitive(f):
        cont = f.content()
        return (cont, f.quo_ground(cont))

    def monic(f):
        if not f:
            return f
        else:
            return f.quo_ground(f.LC)

    def mul_ground(f, x):
        if not x:
            return f.ring.zero
        terms = [(monom, coeff * x) for monom, coeff in f.iterterms()]
        return f.new(terms)

    def mul_monom(f, monom):
        monomial_mul = f.ring.monomial_mul
        terms = [(monomial_mul(f_monom, monom), f_coeff) for f_monom, f_coeff in f.items()]
        return f.new(terms)

    def mul_term(f, term):
        monom, coeff = term
        if not f or not coeff:
            return f.ring.zero
        elif monom == f.ring.zero_monom:
            return f.mul_ground(coeff)
        monomial_mul = f.ring.monomial_mul
        terms = [(monomial_mul(f_monom, monom), f_coeff * coeff) for f_monom, f_coeff in f.items()]
        return f.new(terms)

    def quo_ground(f, x):
        domain = f.ring.domain
        if not x:
            raise ZeroDivisionError('polynomial division')
        if not f or x == domain.one:
            return f
        if domain.is_Field:
            quo = domain.quo
            terms = [(monom, quo(coeff, x)) for monom, coeff in f.iterterms()]
        else:
            terms = [(monom, coeff // x) for monom, coeff in f.iterterms() if not coeff % x]
        return f.new(terms)

    def quo_term(f, term):
        monom, coeff = term
        if not coeff:
            raise ZeroDivisionError('polynomial division')
        elif not f:
            return f.ring.zero
        elif monom == f.ring.zero_monom:
            return f.quo_ground(coeff)
        term_div = f._term_div()
        terms = [term_div(t, term) for t in f.iterterms()]
        return f.new([t for t in terms if t is not None])

    def trunc_ground(f, p):
        if f.ring.domain.is_ZZ:
            terms = []
            for monom, coeff in f.iterterms():
                coeff = coeff % p
                if coeff > p // 2:
                    coeff = coeff - p
                terms.append((monom, coeff))
        else:
            terms = [(monom, coeff % p) for monom, coeff in f.iterterms()]
        poly = f.new(terms)
        poly.strip_zero()
        return poly
    rem_ground = trunc_ground

    def extract_ground(self, g):
        f = self
        fc = f.content()
        gc = g.content()
        gcd = f.ring.domain.gcd(fc, gc)
        f = f.quo_ground(gcd)
        g = g.quo_ground(gcd)
        return (gcd, f, g)

    def _norm(f, norm_func):
        if not f:
            return f.ring.domain.zero
        else:
            ground_abs = f.ring.domain.abs
            return norm_func([ground_abs(coeff) for coeff in f.itercoeffs()])

    def max_norm(f):
        return f._norm(max)

    def l1_norm(f):
        return f._norm(sum)

    def deflate(f, *G):
        ring = f.ring
        polys = [f] + list(G)
        J = [0] * ring.ngens
        for p in polys:
            for monom in p.itermonoms():
                for i, m in enumerate(monom):
                    J[i] = igcd(J[i], m)
        for i, b in enumerate(J):
            if not b:
                J[i] = 1
        J = tuple(J)
        if all((b == 1 for b in J)):
            return (J, polys)
        H = []
        for p in polys:
            h = ring.zero
            for I, coeff in p.iterterms():
                N = [i // j for i, j in zip(I, J)]
                h[tuple(N)] = coeff
            H.append(h)
        return (J, H)

    def inflate(f, J):
        poly = f.ring.zero
        for I, coeff in f.iterterms():
            N = [i * j for i, j in zip(I, J)]
            poly[tuple(N)] = coeff
        return poly

    def lcm(self, g):
        f = self
        domain = f.ring.domain
        if not domain.is_Field:
            fc, f = f.primitive()
            gc, g = g.primitive()
            c = domain.lcm(fc, gc)
        h = (f * g).quo(f.gcd(g))
        if not domain.is_Field:
            return h.mul_ground(c)
        else:
            return h.monic()

    def gcd(f, g):
        return f.cofactors(g)[0]

    def cofactors(f, g):
        if not f and (not g):
            zero = f.ring.zero
            return (zero, zero, zero)
        elif not f:
            h, cff, cfg = f._gcd_zero(g)
            return (h, cff, cfg)
        elif not g:
            h, cfg, cff = g._gcd_zero(f)
            return (h, cff, cfg)
        elif len(f) == 1:
            h, cff, cfg = f._gcd_monom(g)
            return (h, cff, cfg)
        elif len(g) == 1:
            h, cfg, cff = g._gcd_monom(f)
            return (h, cff, cfg)
        J, (f, g) = f.deflate(g)
        h, cff, cfg = f._gcd(g)
        return (h.inflate(J), cff.inflate(J), cfg.inflate(J))

    def _gcd_zero(f, g):
        one, zero = (f.ring.one, f.ring.zero)
        if g.is_nonnegative:
            return (g, zero, one)
        else:
            return (-g, zero, -one)

    def _gcd_monom(f, g):
        ring = f.ring
        ground_gcd = ring.domain.gcd
        ground_quo = ring.domain.quo
        monomial_gcd = ring.monomial_gcd
        monomial_ldiv = ring.monomial_ldiv
        mf, cf = list(f.iterterms())[0]
        _mgcd, _cgcd = (mf, cf)
        for mg, cg in g.iterterms():
            _mgcd = monomial_gcd(_mgcd, mg)
            _cgcd = ground_gcd(_cgcd, cg)
        h = f.new([(_mgcd, _cgcd)])
        cff = f.new([(monomial_ldiv(mf, _mgcd), ground_quo(cf, _cgcd))])
        cfg = f.new([(monomial_ldiv(mg, _mgcd), ground_quo(cg, _cgcd)) for mg, cg in g.iterterms()])
        return (h, cff, cfg)

    def _gcd(f, g):
        ring = f.ring
        if ring.domain.is_QQ:
            return f._gcd_QQ(g)
        elif ring.domain.is_ZZ:
            return f._gcd_ZZ(g)
        else:
            return ring.dmp_inner_gcd(f, g)

    def _gcd_ZZ(f, g):
        return heugcd(f, g)

    def _gcd_QQ(self, g):
        f = self
        ring = f.ring
        new_ring = ring.clone(domain=ring.domain.get_ring())
        cf, f = f.clear_denoms()
        cg, g = g.clear_denoms()
        f = f.set_ring(new_ring)
        g = g.set_ring(new_ring)
        h, cff, cfg = f._gcd_ZZ(g)
        h = h.set_ring(ring)
        c, h = (h.LC, h.monic())
        cff = cff.set_ring(ring).mul_ground(ring.domain.quo(c, cf))
        cfg = cfg.set_ring(ring).mul_ground(ring.domain.quo(c, cg))
        return (h, cff, cfg)

    def cancel(self, g):
        f = self
        ring = f.ring
        if not f:
            return (f, ring.one)
        domain = ring.domain
        if not (domain.is_Field and domain.has_assoc_Ring):
            _, p, q = f.cofactors(g)
        else:
            new_ring = ring.clone(domain=domain.get_ring())
            cq, f = f.clear_denoms()
            cp, g = g.clear_denoms()
            f = f.set_ring(new_ring)
            g = g.set_ring(new_ring)
            _, p, q = f.cofactors(g)
            _, cp, cq = new_ring.domain.cofactors(cp, cq)
            p = p.set_ring(ring)
            q = q.set_ring(ring)
            p = p.mul_ground(cp)
            q = q.mul_ground(cq)
        u = q.canonical_unit()
        if u == domain.one:
            p, q = (p, q)
        elif u == -domain.one:
            p, q = (-p, -q)
        else:
            p = p.mul_ground(u)
            q = q.mul_ground(u)
        return (p, q)

    def canonical_unit(f):
        domain = f.ring.domain
        return domain.canonical_unit(f.LC)

    def diff(f, x):
        ring = f.ring
        i = ring.index(x)
        m = ring.monomial_basis(i)
        g = ring.zero
        for expv, coeff in f.iterterms():
            if expv[i]:
                e = ring.monomial_ldiv(expv, m)
                g[e] = ring.domain_new(coeff * expv[i])
        return g

    def __call__(f, *values):
        if 0 < len(values) <= f.ring.ngens:
            return f.evaluate(list(zip(f.ring.gens, values)))
        else:
            raise ValueError('expected at least 1 and at most %s values, got %s' % (f.ring.ngens, len(values)))

    def evaluate(self, x, a=None):
        f = self
        if isinstance(x, list) and a is None:
            (X, a), x = (x[0], x[1:])
            f = f.evaluate(X, a)
            if not x:
                return f
            else:
                x = [(Y.drop(X), a) for Y, a in x]
                return f.evaluate(x)
        ring = f.ring
        i = ring.index(x)
        a = ring.domain.convert(a)
        if ring.ngens == 1:
            result = ring.domain.zero
            for (n,), coeff in f.iterterms():
                result += coeff * a ** n
            return result
        else:
            poly = ring.drop(x).zero
            for monom, coeff in f.iterterms():
                n, monom = (monom[i], monom[:i] + monom[i + 1:])
                coeff = coeff * a ** n
                if monom in poly:
                    coeff = coeff + poly[monom]
                    if coeff:
                        poly[monom] = coeff
                    else:
                        del poly[monom]
                elif coeff:
                    poly[monom] = coeff
            return poly

    def subs(self, x, a=None):
        f = self
        if isinstance(x, list) and a is None:
            for X, a in x:
                f = f.subs(X, a)
            return f
        ring = f.ring
        i = ring.index(x)
        a = ring.domain.convert(a)
        if ring.ngens == 1:
            result = ring.domain.zero
            for (n,), coeff in f.iterterms():
                result += coeff * a ** n
            return ring.ground_new(result)
        else:
            poly = ring.zero
            for monom, coeff in f.iterterms():
                n, monom = (monom[i], monom[:i] + (0,) + monom[i + 1:])
                coeff = coeff * a ** n
                if monom in poly:
                    coeff = coeff + poly[monom]
                    if coeff:
                        poly[monom] = coeff
                    else:
                        del poly[monom]
                elif coeff:
                    poly[monom] = coeff
            return poly

    def symmetrize(self):
        f = self.copy()
        ring = f.ring
        n = ring.ngens
        if not n:
            return (f, ring.zero, [])
        polys = [ring.symmetric_poly(i + 1) for i in range(n)]
        poly_powers = {}

        def get_poly_power(i, n):
            if (i, n) not in poly_powers:
                poly_powers[i, n] = polys[i] ** n
            return poly_powers[i, n]
        indices = list(range(n - 1))
        weights = list(range(n, 0, -1))
        symmetric = ring.zero
        while f:
            _height, _monom, _coeff = (-1, None, None)
            for i, (monom, coeff) in enumerate(f.terms()):
                if all((monom[i] >= monom[i + 1] for i in indices)):
                    height = max((n * m for n, m in zip(weights, monom)))
                    if height > _height:
                        _height, _monom, _coeff = (height, monom, coeff)
            if _height != -1:
                monom, coeff = (_monom, _coeff)
            else:
                break
            exponents = []
            for m1, m2 in zip(monom, monom[1:] + (0,)):
                exponents.append(m1 - m2)
            symmetric += ring.term_new(tuple(exponents), coeff)
            product = coeff
            for i, n in enumerate(exponents):
                product *= get_poly_power(i, n)
            f -= product
        mapping = list(zip(ring.gens, polys))
        return (symmetric, f, mapping)

    def compose(f, x, a=None):
        ring = f.ring
        poly = ring.zero
        gens_map = dict(zip(ring.gens, range(ring.ngens)))
        if a is not None:
            replacements = [(x, a)]
        elif isinstance(x, list):
            replacements = list(x)
        elif isinstance(x, dict):
            replacements = sorted(x.items(), key=lambda k: gens_map[k[0]])
        else:
            raise ValueError('expected a generator, value pair a sequence of such pairs')
        for k, (x, g) in enumerate(replacements):
            replacements[k] = (gens_map[x], ring.ring_new(g))
        for monom, coeff in f.iterterms():
            monom = list(monom)
            subpoly = ring.one
            for i, g in replacements:
                n, monom[i] = (monom[i], 0)
                if n:
                    subpoly *= g ** n
            subpoly = subpoly.mul_term((tuple(monom), coeff))
            poly += subpoly
        return poly

    def coeff_wrt(self, x, deg):
        p = self
        i = p.ring.index(x)
        terms = [(m, c) for m, c in p.iterterms() if m[i] == deg]
        if not terms:
            return p.ring.zero
        monoms, coeffs = zip(*terms)
        monoms = [m[:i] + (0,) + m[i + 1:] for m in monoms]
        return p.ring.from_dict(dict(zip(monoms, coeffs)))

    def prem(self, g, x=None):
        f = self
        x = f.ring.index(x)
        df = f.degree(x)
        dg = g.degree(x)
        if dg < 0:
            raise ZeroDivisionError('polynomial division')
        r, dr = (f, df)
        if df < dg:
            return r
        N = df - dg + 1
        lc_g = g.coeff_wrt(x, dg)
        xp = f.ring.gens[x]
        while True:
            lc_r = r.coeff_wrt(x, dr)
            j, N = (dr - dg, N - 1)
            R = r * lc_g
            G = g * lc_r * xp ** j
            r = R - G
            dr = r.degree(x)
            if dr < dg:
                break
        c = lc_g ** N
        return r * c

    def pdiv(self, g, x=None):
        f = self
        x = f.ring.index(x)
        df = f.degree(x)
        dg = g.degree(x)
        if dg < 0:
            raise ZeroDivisionError('polynomial division')
        q, r, dr = (x, f, df)
        if df < dg:
            return (q, r)
        N = df - dg + 1
        lc_g = g.coeff_wrt(x, dg)
        xp = f.ring.gens[x]
        while True:
            lc_r = r.coeff_wrt(x, dr)
            j, N = (dr - dg, N - 1)
            Q = q * lc_g
            q = Q + lc_r * xp ** j
            R = r * lc_g
            G = g * lc_r * xp ** j
            r = R - G
            dr = r.degree(x)
            if dr < dg:
                break
        c = lc_g ** N
        q = q * c
        r = r * c
        return (q, r)

    def pquo(self, g, x=None):
        f = self
        return f.pdiv(g, x)[0]

    def pexquo(self, g, x=None):
        f = self
        q, r = f.pdiv(g, x)
        if r.is_zero:
            return q
        else:
            raise ExactQuotientFailed(f, g)

    def subresultants(self, g, x=None):
        f = self
        x = f.ring.index(x)
        n = f.degree(x)
        m = g.degree(x)
        if n < m:
            f, g = (g, f)
            n, m = (m, n)
        if f == 0:
            return [0, 0]
        if g == 0:
            return [f, 1]
        R = [f, g]
        d = n - m
        b = (-1) ** (d + 1)
        h = f.prem(g, x)
        h = h * b
        lc = g.coeff_wrt(x, m)
        c = lc ** d
        S = [1, c]
        c = -c
        while h:
            k = h.degree(x)
            R.append(h)
            f, g, m, d = (g, h, k, m - k)
            b = -lc * c ** d
            h = f.prem(g, x)
            h = h.exquo(b)
            lc = g.coeff_wrt(x, k)
            if d > 1:
                p = (-lc) ** d
                q = c ** (d - 1)
                c = p.exquo(q)
            else:
                c = -lc
            S.append(-c)
        return R

    def half_gcdex(f, g):
        return f.ring.dmp_half_gcdex(f, g)

    def gcdex(f, g):
        return f.ring.dmp_gcdex(f, g)

    def resultant(f, g):
        return f.ring.dmp_resultant(f, g)

    def discriminant(f):
        return f.ring.dmp_discriminant(f)

    def decompose(f):
        if f.ring.is_univariate:
            return f.ring.dup_decompose(f)
        else:
            raise MultivariatePolynomialError('polynomial decomposition')

    def shift(f, a):
        if f.ring.is_univariate:
            return f.ring.dup_shift(f, a)
        else:
            raise MultivariatePolynomialError('shift: use shift_list instead')

    def shift_list(f, a):
        return f.ring.dmp_shift(f, a)

    def sturm(f):
        if f.ring.is_univariate:
            return f.ring.dup_sturm(f)
        else:
            raise MultivariatePolynomialError('sturm sequence')

    def gff_list(f):
        return f.ring.dmp_gff_list(f)

    def norm(f):
        return f.ring.dmp_norm(f)

    def sqf_norm(f):
        return f.ring.dmp_sqf_norm(f)

    def sqf_part(f):
        return f.ring.dmp_sqf_part(f)

    def sqf_list(f, all=False):
        return f.ring.dmp_sqf_list(f, all=all)

    def factor_list(f):
        return f.ring.dmp_factor_list(f)

