    if not K.is_Algebraic:
        raise DomainError('ground domain must be algebraic')
    g = dmp_raise(K.mod.to_list(), u + 1, 0, K.dom)
    h, _ = dmp_inject(f, u, K, front=True)
    return dmp_resultant(g, h, u + 1, K.dom)

