    deg = dmp_degree(f, u)
    if deg < 0:
        return (coeff, [])
    content, f = dmp_primitive(f, u, K)
    result = {}
    if deg != 0:
        h = dmp_diff(f, 1, u, K)
        g, p, q = dmp_inner_gcd(f, h, u, K)
        i = 1
        while True:
            d = dmp_diff(p, 1, u, K)
            h = dmp_sub(q, d, u, K)
