def sylvester(f, g, x, method=1):
    m, n = (degree(Poly(f, x), x), degree(Poly(g, x), x))
    if m == n and n < 0:
        return Matrix([])
    if m == n and n == 0:
        return Matrix([])
    if m == 0 and n < 0:
        return Matrix([])
    elif m < 0 and n == 0:
        return Matrix([])
    if m >= 1 and n < 0:
        return Matrix([0])
    elif m < 0 and n >= 1:
        return Matrix([0])
    fp = Poly(f, x).all_coeffs()
    gp = Poly(g, x).all_coeffs()
    if method <= 1:
        M = zeros(m + n)
        k = 0
        for i in range(n):
            j = k
            for coeff in fp:
                M[i, j] = coeff
                j = j + 1
            k = k + 1
        k = 0
        for i in range(n, m + n):
            j = k
            for coeff in gp:
                M[i, j] = coeff
                j = j + 1
            k = k + 1
        return M
    if method >= 2:
        if len(fp) < len(gp):
            h = []
            for i in range(len(gp) - len(fp)):
                h.append(0)
            fp[:0] = h
        else:
            h = []
            for i in range(len(fp) - len(gp)):
                h.append(0)
            gp[:0] = h
        mx = max(m, n)
        dim = 2 * mx
        M = zeros(dim)
        k = 0
        for i in range(mx):
            j = k
            for coeff in fp:
                M[2 * i, j] = coeff
                j = j + 1
            j = k
            for coeff in gp:
                M[2 * i + 1, j] = coeff
                j = j + 1
            k = k + 1
        return M

def process_matrix_output(poly_seq, x):
    L = poly_seq[:]
    d = degree(L[1], x)
    i = 2
    while i < len(L):
        d_i = degree(L[i], x)
        if d_i < 0:
            L.remove(L[i])
            i = i - 1
        if d == d_i:
            L.remove(L[i])
            i = i - 1
        if d_i >= 0:
            d = d_i
        i = i + 1
    return L

def subresultants_sylv(f, g, x):
    if f == 0 or g == 0:
        return [f, g]
    n = degF = degree(f, x)
    m = degG = degree(g, x)
    if n == 0 and m == 0:
        return [f, g]
    if n < m:
        n, m, degF, degG, f, g = (m, n, degG, degF, g, f)
    if n > 0 and m == 0:
        return [f, g]
    SR_L = [f, g]
    S = sylvester(f, g, x, 1)
    j = m - 1
    while j > 0:
        Sp = S[:, :]
        for ind in range(m + n - j, m + n):
            Sp.row_del(m + n - j)
        for ind in range(m - j, m):
            Sp.row_del(m - j)
        coeff_L, k, l = ([], Sp.rows, 0)
        while l <= j:
            coeff_L.append(Sp[:, 0:k].det())
            Sp.col_swap(k - 1, k + l)
            l += 1
        SR_L.append(Poly(coeff_L, x).as_expr())
        j -= 1
    SR_L.append(S.det())
    return process_matrix_output(SR_L, x)

