def res(f, g, x):
    if f == 0 or g == 0:
        raise PolynomialError('The resultant of %s and %s is not defined' % (f, g))
    else:
        return sylvester(f, g, x, 1).det()

def res_q(f, g, x):
    m = degree(f, x)
    n = degree(g, x)
    if m < n:
        return (-1) ** (m * n) * res_q(g, f, x)
    elif n == 0:
        return g ** m
    else:
        r = rem(f, g, x)
        if r == 0:
            return 0
        else:
            s = degree(r, x)
            l = LC(g, x)
            return (-1) ** (m * n) * l ** (m - s) * res_q(g, r, x)

def res_z(f, g, x):
    m = degree(f, x)
    n = degree(g, x)
    if m < n:
        return (-1) ** (m * n) * res_z(g, f, x)
    elif n == 0:
        return g ** m
    else:
        r = prem(f, g, x)
        if r == 0:
            return 0
        else:
            delta = m - n + 1
            w = (-1) ** (m * n) * res_z(g, r, x)
            s = degree(r, x)
            l = LC(g, x)
            k = delta * n - m + s
            return quo(w, l ** k, x)

