def bezout(p, q, x, method='bz'):
    m, n = (degree(Poly(p, x), x), degree(Poly(q, x), x))
    if m == n and n < 0:
        return Matrix([])
    if m == n and n == 0:
        return Matrix([])
    if m == 0 and n < 0:
        return Matrix([])
    elif m < 0 and n == 0:
        return Matrix([])
    if m >= 1 and n < 0:
        return Matrix([0])
    elif m < 0 and n >= 1:
        return Matrix([0])
    y = var('y')
    expr = p * q.subs({x: y}) - p.subs({x: y}) * q
    poly = Poly(quo(expr, x - y), x, y)
    mx = max(m, n)
    B = zeros(mx)
    for i in range(mx):
        for j in range(mx):
            if method == 'prs':
                B[mx - 1 - i, mx - 1 - j] = poly.nth(i, j)
            else:
                B[i, j] = poly.nth(i, j)
    return B

def backward_eye(n):
    M = eye(n)
    for i in range(int(M.rows / 2)):
        M.row_swap(0 + i, M.rows - 1 - i)
