def subresultants_bezout(p, q, x):
    if p == 0 or q == 0:
        return [p, q]
    f, g = (p, q)
    n = degF = degree(f, x)
    m = degG = degree(g, x)
    if n == 0 and m == 0:
        return [f, g]
    if n < m:
        n, m, degF, degG, f, g = (m, n, degG, degF, g, f)
    if n > 0 and m == 0:
        return [f, g]
    SR_L = [f, g]
    F = LC(f, x) ** (degF - degG)
    B = bezout(f, g, x, 'prs')
    if degF > degG:
        j = 2
    if degF == degG:
        j = 1
    while j <= degF:
        M = B[0:j, :]
        k, coeff_L = (j - 1, [])
        while k <= degF - 1:
            coeff_L.append(M[:, 0:j].det())
            if k < degF - 1:
                M.col_swap(j - 1, k + 1)
            k = k + 1
        SR_L.append(int((-1) ** (j * (j - 1) / 2)) * (Poly(coeff_L, x) / F).as_expr())
