    sigma1 = LC(a1, x)
    p0 = d0 - d1
    if p0 % 2 == 1:
        s += 1
    phi = floor((s + 1) / 2)
    mul_fac = 1
    d2 = d1
    while d2 > 0:
        i += 1
        a2 = rem(a0, a1, domain=QQ)
        if i == 1:
            sigma2 = LC(a2, x)
        else:
            sigma3 = LC(a2, x)
            sigma1, sigma2 = (sigma2, sigma3)
        d2 = degree(a2, x)
        p1 = d1 - d2
        psi = i + phi + p_odd_index_sum
        mul_fac = sigma1 ** (p0 + 1) * mul_fac
        num = (-1) ** psi
        den = sign(mul_fac)
