        p0 = p1
        if p0 % 2 == 1:
            s += 1
        phi = floor((s + 1) / 2)
        if i % 2 == 1:
            p_odd_index_sum += p0
    m = len(subres_l)
    if subres_l[m - 1] == nan or subres_l[m - 1] == 0:
