        if i % 2 == 1:
            p_odd_index_sum += p1
        a0, a1, d0, d1 = (a1, a2, d1, d2)
        p0 = p1
        i += 1
        sigma0 = -LC(a0)
        c = sigma0 ** (deg_dif_p1 - 1) / c ** (deg_dif_p1 - 2)
        deg_dif_p1 = degree(a0, x) - d2 + 1
