        num = (-1) ** psi
        den = sgn_den
        if sign(num / den) > 0:
            subres_l.append(a2)
        else:
            subres_l.append(-a2)
        if p1 % 2 == 1:
            s += 1
        if p1 - 1 > 0:
            sgn_den = sgn_den * compute_sign(sigma1, p1 - 1)
    m = len(subres_l)
    if subres_l[m - 1] == nan or subres_l[m - 1] == 0:
