    def mul(self, m, d):
        return m * d

    def div(self, m, d):
        return m / d

    def eq(self, d1, d2):
        return d1 == d2

    def __add__(self, om):
        if not isinstance(om, self.__class__) or om.module != self.module:
            try:
                om = self.module.convert(om)
            except CoercionFailed:
                return NotImplemented
