from sympy.polys.domains.field import Field
from sympy.polys.domains.simpledomain import SimpleDomain
from sympy.polys.polyutils import PicklableWithSlots
from sympy.utilities import public
eflags = {'deep': False, 'mul': True, 'power_exp': False, 'power_base': False, 'basic': False, 'multinomial': False, 'log': False}

@public
class ExpressionDomain(Field, CharacteristicZero, SimpleDomain):
    is_SymbolicDomain = is_EX = True

    class Expression(DomainElement, PicklableWithSlots):
        __slots__ = ('ex',)

        def __init__(self, ex):
            if not isinstance(ex, self.__class__):
                self.ex = sympify(ex)
            else:
                self.ex = ex.ex

        def __repr__(f):
            return 'EX(%s)' % repr(f.ex)

        def __str__(f):
            return 'EX(%s)' % str(f.ex)

        def __hash__(self):
            return hash((self.__class__.__name__, self.ex))

        def parent(self):
            return EX

        def as_expr(f):
            return f.ex

        def numer(f):
            return f.__class__(f.ex.as_numer_denom()[0])

        def denom(f):
            return f.__class__(f.ex.as_numer_denom()[1])

        def simplify(f, ex):
            return f.__class__(ex.cancel().expand(**eflags))

        def __abs__(f):
            return f.__class__(abs(f.ex))

        def __neg__(f):
            return f.__class__(-f.ex)

        def _to_ex(f, g):
            try:
                return f.__class__(g)
            except SympifyError:
                return None

        def __lt__(f, g):
            return f.ex.sort_key() < g.ex.sort_key()

        def __add__(f, g):
            g = f._to_ex(g)
            if g is None:
                return NotImplemented
            elif g == EX.zero:
                return f
            elif f == EX.zero:
                return g
            else:
                return f.simplify(f.ex + g.ex)

        def __radd__(f, g):
            return f.simplify(f.__class__(g).ex + f.ex)

        def __sub__(f, g):
            g = f._to_ex(g)
            if g is None:
                return NotImplemented
            elif g == EX.zero:
                return f
            elif f == EX.zero:
                return -g
            else:
                return f.simplify(f.ex - g.ex)

        def __rsub__(f, g):
            return f.simplify(f.__class__(g).ex - f.ex)

        def __mul__(f, g):
            g = f._to_ex(g)
            if g is None:
                return NotImplemented
            if EX.zero in (f, g):
                return EX.zero
            elif f.ex.is_Number and g.ex.is_Number:
                return f.__class__(f.ex * g.ex)
            return f.simplify(f.ex * g.ex)

        def __rmul__(f, g):
            return f.simplify(f.__class__(g).ex * f.ex)

        def __pow__(f, n):
            n = f._to_ex(n)
            if n is not None:
                return f.simplify(f.ex ** n.ex)
            else:
