        return self

    def get_field(self):
        return QQ_I

    def normalize(self, d, *args):
        unit = self.canonical_unit(d)
        d *= unit
        args = tuple((a * unit for a in args))
        return (d,) + args if args else d

    def gcd(self, a, b):
        while b:
            a, b = (b, a % b)
        return self.normalize(a)

