    def from_FF(K1, a, K0):
        return MPZ(K0.to_int(a))

    def from_FF_python(K1, a, K0):
        return MPZ(K0.to_int(a))

    def from_ZZ(K1, a, K0):
        return MPZ(a)

    def from_ZZ_python(K1, a, K0):
        return MPZ(a)

    def from_QQ(K1, a, K0):
        if a.denominator == 1:
            return MPZ(a.numerator)

    def from_QQ_python(K1, a, K0):
        if a.denominator == 1:
            return MPZ(a.numerator)

    def from_FF_gmpy(K1, a, K0):
        return MPZ(K0.to_int(a))

    def from_ZZ_gmpy(K1, a, K0):
        return a

    def from_QQ_gmpy(K1, a, K0):
        if a.denominator == 1:
            return a.numerator

    def from_RealField(K1, a, K0):
        p, q = K0.to_rational(a)
        if q == 1:
            return MPZ(int(p))

    def from_GaussianIntegerRing(K1, a, K0):
        if a.y == 0:
            return a.x

    def from_EX(K1, a, K0):
        if a.is_Integer:
            return K1.from_sympy(a)

    def gcdex(self, a, b):
        h, s, t = gcdex(a, b)
        if GROUND_TYPES == 'gmpy':
            return (s, t, h)
        else:
            return (h, s, t)

    def gcd(self, a, b):
        return gcd(a, b)

    def lcm(self, a, b):
        return lcm(a, b)

    def sqrt(self, a):
        return sqrt(a)

    def is_square(self, a):
        return is_square(a)

    def exsqrt(self, a):
        if a < 0:
            return None
        root, rem = sqrtrem(a)
        if rem != 0:
            return None
        return root

    def factorial(self, a):
